import React, { useState } from 'react';
import { User } from '../types';
import { Search, Plus, Edit2, Trash2, Mail, Shield, CheckCircle, XCircle, Settings, X } from 'lucide-react';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';

interface UserManagementProps {
  users: User[];
  onAddUser: (user: Omit<User, 'id' | 'lastLogin' | 'avatar'>) => void;
  onEditUser: (id: string, updates: Partial<User>) => void;
  onDeleteUser: (id: string) => void;
}

const UserManagement: React.FC<UserManagementProps> = ({ users, onAddUser, onEditUser, onDeleteUser }) => {
  const [searchTerm, setSearchTerm] = useState('');

  // Modal States
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [isRoleModalOpen, setIsRoleModalOpen] = useState(false);

  // Data States
  const [roles, setRoles] = useState<string[]>(['admin', 'manager', 'user']);
  const [editingUser, setEditingUser] = useState<User | null>(null);

  // Form States
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    role: '',
    status: 'active'
  });
  const [newRoleName, setNewRoleName] = useState('');

  const filteredUsers = users.filter(user => 
    user.username.toLowerCase().includes(searchTerm.toLowerCase()) || 
    user.email.toLowerCase().includes(searchTerm.toLowerCase())
  );

  // --- User Handlers ---

  const handleOpenAddUser = () => {
    setEditingUser(null);
    setFormData({ username: '', email: '', role: roles[0] || 'user', status: 'active' });
    setIsUserModalOpen(true);
  };

  const handleOpenEditUser = (user: User) => {
    setEditingUser(user);
    setFormData({ 
      username: user.username, 
      email: user.email, 
      role: user.role, 
      status: user.status as string
    });
    setIsUserModalOpen(true);
  };

  const handleUserSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingUser) {
      onEditUser(editingUser.id, {
        username: formData.username,
        email: formData.email,
        role: formData.role,
        status: formData.status as any
      });
    } else {
      onAddUser({
        username: formData.username,
        email: formData.email,
        role: formData.role,
        status: formData.status as any
      });
    }
    setIsUserModalOpen(false);
  };

  // --- Role Handlers ---

  const handleAddRole = (e: React.FormEvent) => {
    e.preventDefault();
    const formattedRole = newRoleName.trim().toLowerCase();
    if (formattedRole && !roles.includes(formattedRole)) {
      setRoles([...roles, formattedRole]);
      setNewRoleName('');
    }
  };

  const handleDeleteRole = (roleToDelete: string) => {
    if (roles.length <= 1) {
      alert("You must have at least one role.");
      return;
    }

    // Check if role is assigned to any user
    const isRoleAssigned = users.some(user => user.role === roleToDelete);

    if (isRoleAssigned) {
      alert(`Cannot delete role "${roleToDelete}" because it is currently assigned to one or more users. Please reassign these users before deleting the role.`);
      return;
    }

    setRoles(roles.filter(r => r !== roleToDelete));
  };

  return (
