                {roles.map((role) => (
                  <option key={role} value={role} className="capitalize">
                    {role.charAt(0).toUpperCase() + role.slice(1)}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Status</label>
              <select
                className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500/50 focus:border-primary-500"
                value={formData.status}
                onChange={(e) => setFormData({...formData, status: e.target.value})}
              >
                <option value="active">Active</option>
                <option value="inactive">Inactive</option>
              </select>
            </div>
          </div>

          <div className="flex justify-end space-x-3 pt-4 border-t border-slate-100 mt-6">
            <Button type="button" variant="secondary" onClick={() => setIsUserModalOpen(false)}>
              Cancel
            </Button>
            <Button type="submit">
              {editingUser ? 'Save Changes' : 'Create User'}
            </Button>
          </div>
        </form>
      </Modal>

      {/* Role Management Modal */}
      <Modal
        isOpen={isRoleModalOpen}
        onClose={() => setIsRoleModalOpen(false)}
        title="Manage Roles"
      >
        <div className="space-y-6">
           {/* Add New Role */}
           <form onSubmit={handleAddRole} className="flex gap-2 items-end bg-slate-50 p-4 rounded-xl border border-slate-100">
             <div className="flex-1">
               <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1">New Role Name</label>
               <input
                 type="text"
                 required
                 value={newRoleName}
                 onChange={(e) => setNewRoleName(e.target.value)}
                 className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500/50 focus:border-primary-500"
                 placeholder="e.g. Developer"
               />
             </div>
             <Button type="submit" className="h-[42px]">Add</Button>
           </form>

           {/* List Roles */}
           <div>
             <h4 className="text-sm font-medium text-slate-700 mb-3">Existing Roles</h4>
