            <Button type="submit">
              {editingUser ? 'Save Changes' : 'Create User'}
            </Button>
          </div>
        </form>
      </Modal>

      {/* Role Management Modal */}
      <Modal
        isOpen={isRoleModalOpen}
        onClose={() => setIsRoleModalOpen(false)}
        title="Manage Roles"
      >
        {/* ... Same as before ... */}
        <div className="space-y-6">
           <form onSubmit={handleAddRole} className="flex gap-2 items-end bg-slate-50 p-4 rounded-xl border border-slate-100">
             <div className="flex-1">
               <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1">New Role Name</label>
               <input
                 type="text"
                 required
                 value={newRoleName}
                 onChange={(e) => setNewRoleName(e.target.value)}
                 className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500/50 focus:border-primary-500"
                 placeholder="e.g. Developer"
               />
             </div>
             <Button type="submit" className="h-[42px]">Add</Button>
           </form>

           <div>
             <h4 className="text-sm font-medium text-slate-700 mb-3">Existing Roles</h4>
             <div className="flex flex-wrap gap-2">
               {roles.map((role) => {
                 const isAssigned = users.some(u => u.role === role);
                 return (
                 <div key={role} className={`flex items-center pl-3 pr-2 py-1.5 border rounded-full shadow-sm group ${isAssigned ? 'bg-slate-50 border-slate-200 opacity-80' : 'bg-white border-slate-200'}`}>
                   <span className="text-sm font-medium text-slate-700 capitalize">{role}</span>
                   <button 
                    onClick={() => handleDeleteRole(role)}
                    className={`ml-2 p-1 rounded-full transition-colors ${isAssigned ? 'text-slate-300 cursor-not-allowed' : 'text-slate-400 hover:text-red-500 hover:bg-red-50'}`}
                    title={isAssigned ? "Cannot delete role assigned to users" : "Remove Role"}
                    disabled={isAssigned}
                   >
                     <X size={14} />
                   </button>
                 </div>
               )})}
             </div>
           </div>

           <div className="flex justify-end pt-4 border-t border-slate-100">
             <Button type="button" variant="secondary" onClick={() => setIsRoleModalOpen(false)}>
               Close
             </Button>
           </div>
        </div>
      </Modal>

    </div>
  );
};

