  const [isRoleModalOpen, setIsRoleModalOpen] = useState(false);
  const [isDeptModalOpen, setIsDeptModalOpen] = useState(false);

  const [editingUser, setEditingUser] = useState<User | null>(null);

  // --- Form States ---

  // User Form
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    role: '',
    status: 'active',
    firstName: '',
    lastName: '',
    phone: '',
    department: '',
    position: '',
    location: '',
    joinDate: '',
    bio: ''
  });

  // Role Form
  const [newRoleName, setNewRoleName] = useState('');
  const [newRoleDesc, setNewRoleDesc] = useState('');
  const [selectedPermissions, setSelectedPermissions] = useState<string[]>([]);

  // Department Form
  const [newDeptName, setNewDeptName] = useState('');
  const [newDeptDesc, setNewDeptDesc] = useState('');

  const filteredUsers = users.filter(user => 
    user.username.toLowerCase().includes(searchTerm.toLowerCase()) || 
    user.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (user.firstName && user.firstName.toLowerCase().includes(searchTerm.toLowerCase())) ||
    (user.lastName && user.lastName.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  // --- User Handlers ---

  const handleOpenAddUser = () => {
    setEditingUser(null);
    setFormData({ 
      username: '', email: '', role: roles[0]?.name || 'user', status: 'active',
      firstName: '', lastName: '', phone: '', department: departments[0]?.name || '', position: '', location: '', joinDate: '', bio: ''
    });
    setIsUserModalOpen(true);
  };

  const handleOpenEditUser = (user: User, e?: React.MouseEvent) => {
    if (e) {
      e.stopPropagation();
      e.preventDefault();
    }
    setEditingUser(user);
    setFormData({ 
      username: user.username, 
      email: user.email, 
      role: user.role, 
      status: user.status as string,
      firstName: user.firstName || '',
      lastName: user.lastName || '',
      phone: user.phone || '',
      department: user.department || '',
      position: user.position || '',
      location: user.location || '',
      joinDate: user.joinDate || '',
      bio: user.bio || ''
    });
    setIsUserModalOpen(true);
  };

  const handleDeleteClick = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    if(window.confirm('Are you sure you want to delete this user?')) {
        onDeleteUser(id);
    }
  };

  const handleUserSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const userData = { ...formData, status: formData.status as any };

    if (editingUser) {
      onEditUser(editingUser.id, userData);
    } else {
      onAddUser(userData);
    }
    setIsUserModalOpen(false);
  };

  // --- Role Handlers ---

  const handleAddRole = (e: React.FormEvent) => {
    e.preventDefault();
    const formattedName = newRoleName.trim().toLowerCase();

    if (roles.some(r => r.name === formattedName)) {
      alert('Role already exists');
      return;
    }

    onAddRole({
      id: Math.random().toString(36).substr(2, 9),
      name: formattedName,
      description: newRoleDesc,
      permissions: selectedPermissions
    });

    setNewRoleName('');
    setNewRoleDesc('');
    setSelectedPermissions([]);
  };

  const handleDeleteRoleWrapper = (roleId: string, roleName: string) => {
    const isAssigned = users.some(user => user.role === roleName);
    if (isAssigned) {
      alert(`Cannot delete role "${roleName}" because it is currently assigned to one or more users.`);
      return;
    }
    onDeleteRole(roleId);
  };

  const togglePermission = (permId: string) => {
    setSelectedPermissions(prev => 
      prev.includes(permId) ? prev.filter(p => p !== permId) : [...prev, permId]
    );
  };

  // --- Department Handlers ---

  const handleAddDepartment = (e: React.FormEvent) => {
    e.preventDefault();
    if (departments.some(d => d.name.toLowerCase() === newDeptName.toLowerCase())) {
      alert('Department already exists');
      return;
    }
    onAddDepartment({
      id: Math.random().toString(36).substr(2, 9),
      name: newDeptName,
      description: newDeptDesc
    });
    setNewDeptName('');
    setNewDeptDesc('');
  };

  const handleDeleteDeptWrapper = (deptId: string, deptName: string) => {
    const isAssigned = users.some(user => user.department === deptName);
    if (isAssigned) {
      alert(`Cannot delete department "${deptName}" because users are assigned to it.`);
      return;
    }
    onDeleteDepartment(deptId);
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">

      {/* Header Actions */}
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
        <div>
           <h1 className="text-2xl font-bold text-slate-900">User Management & Access Control</h1>
           <p className="text-slate-500 mt-1">Manage users, roles, permissions, and department structures.</p>
        </div>
        <div className="flex flex-col sm:flex-row w-full xl:w-auto gap-3">
          <div className="relative flex-1 sm:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
            <input 
              type="text" 
              placeholder="Search users..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500 text-sm"
            />
          </div>
          <div className="flex flex-wrap gap-2">
            <Button onClick={() => setIsDeptModalOpen(true)} variant="secondary" className="shrink-0 bg-white text-slate-700">
              <Building className="w-4 h-4 mr-2" /> Departments
            </Button>
            <Button onClick={() => setIsRoleModalOpen(true)} variant="secondary" className="shrink-0 bg-white text-slate-700">
              <Shield className="w-4 h-4 mr-2" /> Roles & Perms
            </Button>
            <Button onClick={handleOpenAddUser} className="shrink-0">
              <Plus className="w-4 h-4 mr-2" /> Add User
            </Button>
          </div>
        </div>
      </div>

      {/* Users Table */}
      <div className="bg-white rounded-2xl shadow-[0_2px_10px_-4px_rgba(6,81,237,0.1)] border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50/50 border-b border-slate-100 text-xs uppercase text-slate-500 font-semibold tracking-wider">
                <th className="px-6 py-4">User</th>
                <th className="px-6 py-4">Role</th>
                <th className="px-6 py-4">Status</th>
                <th className="px-6 py-4">Department</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredUsers.length > 0 ? (
                filteredUsers.map((user) => (
                  <tr key={user.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-6 py-4">
                      <div className="flex items-center">
                        <img 
                          className="h-10 w-10 rounded-full object-cover border-2 border-white shadow-sm" 
                          src={user.avatar || `https://ui-avatars.com/api/?name=${user.username}&background=random`} 
                          alt="" 
                        />
                        <div className="ml-4">
                          <div className="font-semibold text-slate-900">
                            {user.firstName ? `${user.firstName} ${user.lastName}` : user.username}
                          </div>
                          <div className="text-sm text-slate-500 flex items-center mt-0.5">
                            <Mail size={12} className="mr-1.5" />
                            {user.email}
                          </div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center text-sm text-slate-700 capitalize">
                         <Shield size={14} className={`mr-2 ${user.role === 'admin' ? 'text-purple-600' : 'text-primary-500'}`} />
                         {user.role}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-medium border ${
                        user.status === 'active' 
                          ? 'bg-emerald-50 text-emerald-700 border-emerald-100' 
                          : 'bg-slate-100 text-slate-600 border-slate-200'
                      }`}>
                        {user.status === 'active' ? (
                          <CheckCircle size={12} className="mr-1.5" />
                        ) : (
                          <XCircle size={12} className="mr-1.5" />
                        )}
                        <span className="capitalize">{user.status}</span>
                      </span>
                    </td>
                    <td className="px-6 py-4 text-sm text-slate-500 capitalize">
                      {user.department || '-'}
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex items-center justify-end space-x-2">
                         <button 
                          onClick={() => onViewUser(user)}
                          className="p-2 text-slate-400 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"
                          title="View Details"
                        >
                          <Eye size={16} />
                        </button>
                        <button 
                          onClick={(e) => handleOpenEditUser(user, e)}
                          className="p-2 text-slate-400 hover:text-primary-600 hover:bg-primary-50 rounded-lg transition-colors"
                          title="Edit User"
                        >
                          <Edit2 size={16} />
                        </button>
                        <button 
                          onClick={(e) => handleDeleteClick(user.id, e)}
                          className="p-2 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-lg transition-colors cursor-pointer"
                          title="Delete User"
                        >
                          <Trash2 size={16} />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan={5} className="px-6 py-12 text-center text-slate-500">
                    <div className="flex flex-col items-center justify-center">
                      <div className="w-12 h-12 bg-slate-100 rounded-full flex items-center justify-center mb-3">
                         <Search className="text-slate-400" size={20} />
                      </div>
                      <p>No users found matching "{searchTerm}"</p>
                    </div>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Add/Edit User Modal */}
      <Modal 
        isOpen={isUserModalOpen} 
        onClose={() => setIsUserModalOpen(false)}
        title={editingUser ? 'Edit User Details' : 'Add New User'}
      >
        <form onSubmit={handleUserSubmit} className="space-y-6">
          <div className="max-h-[60vh] overflow-y-auto pr-2 space-y-6">

            {/* Account Details */}
            <div className="space-y-4">
               <h4 className="text-sm font-bold text-slate-900 uppercase border-b border-slate-100 pb-2">Account Details</h4>
               <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Username</label>
                  <input
                    required
                    type="text"
                    className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500/50 focus:border-primary-500"
                    value={formData.username}
                    onChange={(e) => setFormData({...formData, username: e.target.value})}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Email</label>
                  <input
                    required
                    type="email"
                    className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500/50 focus:border-primary-500"
                    value={formData.email}
                    onChange={(e) => setFormData({...formData, email: e.target.value})}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Role</label>
                  <select
                    className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500/50 focus:border-primary-500"
                    value={formData.role}
                    onChange={(e) => setFormData({...formData, role: e.target.value})}
                  >
                    {roles.map((role) => (
                      <option key={role.id} value={role.name} className="capitalize">
                        {role.name.charAt(0).toUpperCase() + role.name.slice(1)}
                      </option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Status</label>
                  <select
                    className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500/50 focus:border-primary-500"
                    value={formData.status}
                    onChange={(e) => setFormData({...formData, status: e.target.value})}
                  >
                    <option value="active">Active</option>
                    <option value="inactive">Inactive</option>
                  </select>
                </div>
               </div>
            </div>

            {/* Employment Details */}
            <div className="space-y-4">
              <h4 className="text-sm font-bold text-slate-900 uppercase border-b border-slate-100 pb-2">Employment Details</h4>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Department</label>
                  <select
                    className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500/50 focus:border-primary-500"
                    value={formData.department}
                    onChange={(e) => setFormData({...formData, department: e.target.value})}
                  >
                    <option value="">Select Department</option>
                    {departments.map((dept) => (
                      <option key={dept.id} value={dept.name}>{dept.name}</option>
                    ))}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Position</label>
                  <input
                    type="text"
                    className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500/50 focus:border-primary-500"
                    value={formData.position}
                    onChange={(e) => setFormData({...formData, position: e.target.value})}
                  />
                </div>
                {/* Other personal fields */}
                 <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">First Name</label>
                  <input
                    type="text"
                    className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500/50 focus:border-primary-500"
                    value={formData.firstName}
                    onChange={(e) => setFormData({...formData, firstName: e.target.value})}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Last Name</label>
                  <input
                    type="text"
                    className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500/50 focus:border-primary-500"
                    value={formData.lastName}
                    onChange={(e) => setFormData({...formData, lastName: e.target.value})}
                  />
                </div>
              </div>
            </div>

          </div>

          <div className="flex justify-end space-x-3 pt-4 border-t border-slate-100">
            <Button type="button" variant="secondary" onClick={() => setIsUserModalOpen(false)}>
              Cancel
            </Button>
            <Button type="submit">
              {editingUser ? 'Save Changes' : 'Create User'}
            </Button>
          </div>
        </form>
      </Modal>

      {/* Role Management Modal */}
      <Modal
        isOpen={isRoleModalOpen}
        onClose={() => setIsRoleModalOpen(false)}
        title="Role & Permission Management"
      >
        <div className="space-y-6 max-h-[70vh] overflow-y-auto px-1">
           {/* Add New Role */}
           <form onSubmit={handleAddRole} className="space-y-4 bg-slate-50 p-4 rounded-xl border border-slate-100">
             <div>
               <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1">Role Name</label>
               <input
                 type="text"
                 required
                 value={newRoleName}
                 onChange={(e) => setNewRoleName(e.target.value)}
                 className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500/50 focus:border-primary-500"
                 placeholder="e.g. Moderator"
               />
             </div>
             <div>
               <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1">Description</label>
               <input
                 type="text"
                 value={newRoleDesc}
                 onChange={(e) => setNewRoleDesc(e.target.value)}
                 className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500/50 focus:border-primary-500"
                 placeholder="Short description..."
               />
             </div>

             <div>
                <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-2">Permissions</label>
                <div className="grid grid-cols-2 gap-2">
                  {AVAILABLE_PERMISSIONS.map(perm => (
                    <label key={perm.id} className="flex items-start space-x-2 p-2 border rounded-lg bg-white hover:bg-slate-50 cursor-pointer">
                      <input 
                        type="checkbox" 
                        className="mt-1"
                        checked={selectedPermissions.includes(perm.id)}
                        onChange={() => togglePermission(perm.id)}
                      />
                      <div>
                        <div className="text-xs font-semibold">{perm.label}</div>
                        <div className="text-[10px] text-slate-500 leading-tight">{perm.description}</div>
                      </div>
                    </label>
                  ))}
                </div>
             </div>

             <Button type="submit" className="w-full">Create Role</Button>
           </form>

           {/* List Roles */}
           <div>
             <h4 className="text-sm font-medium text-slate-700 mb-3">Existing Roles</h4>
             <div className="space-y-3">
               {roles.map((role) => {
                 const isAssigned = users.some(u => u.role === role.name);
                 const isSystem = role.isSystem;
                 return (
                 <div key={role.id} className="p-3 bg-white border border-slate-200 rounded-xl shadow-sm">
                   <div className="flex justify-between items-start mb-2">
                     <div>
                        <div className="flex items-center gap-2">
                          <span className="font-semibold text-slate-900 capitalize">{role.name}</span>
                          {isSystem && <span className="text-xs bg-purple-100 text-purple-700 px-2 py-0.5 rounded-full">System</span>}
                        </div>
                        <p className="text-xs text-slate-500">{role.description || 'No description'}</p>
                     </div>
                     {!isSystem && (
                       <button 
                        onClick={() => handleDeleteRoleWrapper(role.id, role.name)}
                        className={`p-1.5 rounded-lg transition-colors ${isAssigned ? 'text-slate-300 cursor-not-allowed' : 'text-slate-400 hover:text-red-500 hover:bg-red-50'}`}
                        disabled={isAssigned}
                        title={isAssigned ? "Assigned to users" : "Delete Role"}
                       >
                         <Trash2 size={16} />
                       </button>
                     )}
                   </div>
                   <div className="flex flex-wrap gap-1">
                     {role.permissions.map(p => {
                       const permLabel = AVAILABLE_PERMISSIONS.find(ap => ap.id === p)?.label || p;
                       return (
                         <span key={p} className="text-[10px] px-2 py-0.5 bg-slate-100 text-slate-600 rounded border border-slate-200">
                           {permLabel}
                         </span>
                       )
                     })}
                     {role.permissions.length === 0 && <span className="text-[10px] text-slate-400 italic">No permissions</span>}
                   </div>
                 </div>
               )})}
             </div>
           </div>
        </div>
      </Modal>

      {/* Department Management Modal */}
      <Modal
        isOpen={isDeptModalOpen}
        onClose={() => setIsDeptModalOpen(false)}
        title="Department Structure"
      >
        <div className="space-y-6">
           <form onSubmit={handleAddDepartment} className="bg-slate-50 p-4 rounded-xl border border-slate-100 space-y-3">
             <div className="flex gap-3">
               <div className="flex-1">
                 <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1">Name</label>
                 <input
                   type="text"
                   required
                   value={newDeptName}
                   onChange={(e) => setNewDeptName(e.target.value)}
                   className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg text-sm"
                   placeholder="e.g. Engineering"
                 />
               </div>
               <div className="flex-1">
                 <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wider mb-1">Description</label>
                 <input
                   type="text"
                   value={newDeptDesc}
                   onChange={(e) => setNewDeptDesc(e.target.value)}
                   className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg text-sm"
                   placeholder="Optional"
                 />
               </div>
             </div>
             <Button type="submit" className="w-full">Add Department</Button>
           </form>

           <div className="space-y-2">
             <h4 className="text-sm font-medium text-slate-700">All Departments</h4>
             {departments.map((dept) => {
                const userCount = users.filter(u => u.department === dept.name).length;
                return (
                  <div key={dept.id} className="flex items-center justify-between p-3 bg-white border border-slate-200 rounded-lg">
                    <div>
                      <div className="font-medium text-sm text-slate-900">{dept.name}</div>
                      <div className="text-xs text-slate-500">{dept.description} • {userCount} Users</div>
                    </div>
                    <button 
                      onClick={() => handleDeleteDeptWrapper(dept.id, dept.name)}
                      className="text-slate-400 hover:text-red-500 p-1"
                    >
                      <X size={16} />
                    </button>
                  </div>
                )
             })}
           </div>
        </div>
      </Modal>

    </div>
  );
};

export default UserManagement;

