import React, { useState } from 'react';
import { User, Role, Department, Permission } from '../types';
import { Search, Plus, Edit2, Trash2, Mail, Shield, CheckCircle, XCircle, Settings, X, Eye, Users, Building, Lock } from 'lucide-react';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import ConfirmationModal from '../components/ui/ConfirmationModal';
import AlertModal from '../components/ui/AlertModal';

// Mock Permissions List
const AVAILABLE_PERMISSIONS: Permission[] = [
  { id: 'view_dashboard', label: 'View Dashboard', description: 'Access to main dashboard' },
  { id: 'manage_users', label: 'Manage Users', description: 'Create, edit, and delete users' },
  { id: 'manage_roles', label: 'Manage Roles', description: 'Create and modify user roles' },
  { id: 'manage_departments', label: 'Manage Departments', description: 'Create and modify departments' },
  { id: 'view_analytics', label: 'View Analytics', description: 'Access to detailed reports' },
  { id: 'system_settings', label: 'System Settings', description: 'Configure global system settings' },
];

interface UserManagementProps {
  users: User[];
  roles: Role[];
  departments: Department[];
  onAddUser: (user: Omit<User, 'id' | 'lastLogin' | 'avatar'>) => void;
  onEditUser: (id: string, updates: Partial<User>) => void;
  onDeleteUser: (id: string) => void;
  onViewUser: (user: User) => void;

  // New props for management
  onAddRole: (role: Role) => void;
  onDeleteRole: (roleId: string) => void;
  onAddDepartment: (dept: Department) => void;
  onDeleteDepartment: (deptId: string) => void;
}

const UserManagement: React.FC<UserManagementProps> = ({ 
  users, 
  roles, 
  departments,
  onAddUser, 
  onEditUser, 
  onDeleteUser, 
  onViewUser,
  onAddRole,
  onDeleteRole,
  onAddDepartment,
  onDeleteDepartment
}) => {
  const [searchTerm, setSearchTerm] = useState('');

  // Modal States
  const [isUserModalOpen, setIsUserModalOpen] = useState(false);
  const [isRoleModalOpen, setIsRoleModalOpen] = useState(false);
  const [isDeptModalOpen, setIsDeptModalOpen] = useState(false);

  // Popup States for Delete/Alerts
  const [confirmState, setConfirmState] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({ isOpen: false, title: '', message: '', onConfirm: () => {} });

  const [alertState, setAlertState] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
  }>({ isOpen: false, title: '', message: '' });

  const [editingUser, setEditingUser] = useState<User | null>(null);

  // --- Form States ---

  // User Form
  const [formData, setFormData] = useState({
    username: '',
    email: '',
    role: '',
    status: 'active',
    firstName: '',
    lastName: '',
    phone: '',
    department: '',
    position: '',
    location: '',
    joinDate: '',
    bio: ''
  });

  // Role Form
  const [newRoleName, setNewRoleName] = useState('');
  const [newRoleDesc, setNewRoleDesc] = useState('');
  const [selectedPermissions, setSelectedPermissions] = useState<string[]>([]);

  // Department Form
  const [newDeptName, setNewDeptName] = useState('');
  const [newDeptDesc, setNewDeptDesc] = useState('');

  const filteredUsers = users.filter(user => 
    user.username.toLowerCase().includes(searchTerm.toLowerCase()) || 
    user.email.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (user.firstName && user.firstName.toLowerCase().includes(searchTerm.toLowerCase())) ||
    (user.lastName && user.lastName.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  // --- Helper Functions ---

  const showAlert = (title: string, message: string) => {
    setAlertState({ isOpen: true, title, message });
  };

  const showConfirm = (title: string, message: string, onConfirm: () => void) => {
    setConfirmState({ isOpen: true, title, message, onConfirm });
  };

  // --- User Handlers ---

  const handleOpenAddUser = () => {
    setEditingUser(null);
    setFormData({ 
      username: '', email: '', role: roles[0]?.name || 'user', status: 'active',
      firstName: '', lastName: '', phone: '', department: departments[0]?.name || '', position: '', location: '', joinDate: '', bio: ''
    });
    setIsUserModalOpen(true);
  };

  const handleOpenEditUser = (user: User, e?: React.MouseEvent) => {
    if (e) {
      e.stopPropagation();
      e.preventDefault();
    }
    setEditingUser(user);
    setFormData({ 
      username: user.username, 
      email: user.email, 
      role: user.role, 
      status: user.status as string,
      firstName: user.firstName || '',
      lastName: user.lastName || '',
      phone: user.phone || '',
      department: user.department || '',
      position: user.position || '',
      location: user.location || '',
      joinDate: user.joinDate || '',
      bio: user.bio || ''
    });
    setIsUserModalOpen(true);
  };

  const handleDeleteUserClick = (id: string, username: string, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();

    // User Deletion Constraint (if any) or just confirm
    // For now, simple confirmation
    showConfirm(
      'Delete User?',
      `Are you sure you want to delete ${username}? This action cannot be undone.`,
      () => onDeleteUser(id)
    );
  };

  const handleUserSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const userData = { ...formData, status: formData.status as any };

    if (editingUser) {
      onEditUser(editingUser.id, userData);
    } else {
      onAddUser(userData);
    }
    setIsUserModalOpen(false);
  };

  // --- Role Handlers ---

  const handleAddRole = (e: React.FormEvent) => {
    e.preventDefault();
    const formattedName = newRoleName.trim().toLowerCase();

    if (roles.some(r => r.name === formattedName)) {
      showAlert('Duplicate Role', 'A role with this name already exists.');
      return;
    }

    onAddRole({
      id: Math.random().toString(36).substr(2, 9),
      name: formattedName,
      description: newRoleDesc,
      permissions: selectedPermissions
    });

    setNewRoleName('');
    setNewRoleDesc('');
    setSelectedPermissions([]);
  };

  const handleDeleteRoleWrapper = (roleId: string, roleName: string) => {
    const assignedUserCount = users.filter(user => user.role === roleName).length;

    if (assignedUserCount > 0) {
      showAlert(
        'Cannot Delete Role', 
        `Role "${roleName}" is currently assigned to ${assignedUserCount} user(s). You must reassign them before deleting this role.`
      );
      return;
    }

    showConfirm(
      'Delete Role?',
      `Are you sure you want to delete the role "${roleName}"?`,
      () => onDeleteRole(roleId)
    );
  };

  const togglePermission = (permId: string) => {
    setSelectedPermissions(prev => 
      prev.includes(permId) ? prev.filter(p => p !== permId) : [...prev, permId]
    );
  };

  // --- Department Handlers ---

  const handleAddDepartment = (e: React.FormEvent) => {
    e.preventDefault();
    if (departments.some(d => d.name.toLowerCase() === newDeptName.toLowerCase())) {
      showAlert('Duplicate Department', 'A department with this name already exists.');
      return;
    }
    onAddDepartment({
      id: Math.random().toString(36).substr(2, 9),
      name: newDeptName,
      description: newDeptDesc
    });
    setNewDeptName('');
    setNewDeptDesc('');
  };

  const handleDeleteDeptWrapper = (deptId: string, deptName: string) => {
    const assignedUserCount = users.filter(user => user.department === deptName).length;

    if (assignedUserCount > 0) {
      showAlert(
        'Cannot Delete Department', 
        `Department "${deptName}" has ${assignedUserCount} active user(s). Please move these users to another department before deleting.`
      );
      return;
    }

    showConfirm(
      'Delete Department?',
      `Are you sure you want to delete the department "${deptName}"?`,
      () => onDeleteDepartment(deptId)
    );
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500">

      {/* Header Actions */}
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4">
        <div>
           <h1 className="text-2xl font-bold text-slate-900">User Management & Access Control</h1>
           <p className="text-slate-500 mt-1">Manage users, roles, permissions, and department structures.</p>
        </div>
        <div className="flex flex-col sm:flex-row w-full xl:w-auto gap-3">
          <div className="relative flex-1 sm:w-64">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 w-4 h-4" />
            <input 
              type="text" 
              placeholder="Search users..." 
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full pl-10 pr-4 py-2.5 bg-white border border-slate-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-primary-500/20 focus:border-primary-500 text-sm"
            />
          </div>
          <div className="flex flex-wrap gap-2">
            <Button onClick={() => setIsDeptModalOpen(true)} variant="secondary" className="shrink-0 bg-white text-slate-700">
              <Building className="w-4 h-4 mr-2" /> Departments
            </Button>
            <Button onClick={() => setIsRoleModalOpen(true)} variant="secondary" className="shrink-0 bg-white text-slate-700">
              <Shield className="w-4 h-4 mr-2" /> Roles & Perms
            </Button>
            <Button onClick={handleOpenAddUser} className="shrink-0">
              <Plus className="w-4 h-4 mr-2" /> Add User
            </Button>
          </div>
        </div>
      </div>

      {/* Users Table */}
      <div className="bg-white rounded-2xl shadow-[0_2px_10px_-4px_rgba(6,81,237,0.1)] border border-slate-100 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50/50 border-b border-slate-100 text-xs uppercase text-slate-500 font-semibold tracking-wider">
                <th className="px-6 py-4">User</th>
                <th className="px-6 py-4">Role</th>
                <th className="px-6 py-4">Status</th>
                <th className="px-6 py-4">Department</th>
                <th className="px-6 py-4 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {filteredUsers.length > 0 ? (
                filteredUsers.map((user) => (
                  <tr key={user.id} className="hover:bg-slate-50/50 transition-colors group">
                    <td className="px-6 py-4">
                      <div className="flex items-center">
                        <img 
                          className="h-10 w-10 rounded-full object-cover border-2 border-white shadow-sm" 
                          src={user.avatar || `https://ui-avatars.com/api/?name=${user.username}&background=random`} 
                          alt="" 
                        />
                        <div className="ml-4">
                          <div className="font-semibold text-slate-900">
                            {user.firstName ? `${user.firstName} ${user.lastName}` : user.username}
                          </div>
                          <div className="text-sm text-slate-500 flex items-center mt-0.5">
                            <Mail size={12} className="mr-1.5" />
                            {user.email}
                          </div>
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <div className="flex items-center text-sm text-slate-700 capitalize">
                         <Shield size={14} className={`mr-2 ${user.role === 'admin' ? 'text-purple-600' : 'text-primary-500'}`} />
                         {user.role}
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-xs font-medium border ${
                        user.status === 'active' 
                          ? 'bg-emerald-50 text-emerald-700 border-emerald-100' 
                          : 'bg-slate-100 text-slate-600 border-slate-200'
                      }`}>
                        {user.status === 'active' ? (
                          <CheckCircle size={12} className="mr-1.5" />
                        ) : (
                          <XCircle size={12} className="mr-1.5" />
