             >
               Admin Overview
             </button>
           )}
         </nav>
      </div>

      {/* Content */}
      <div className="pt-4">

        {activeTab === 'calendar' && renderCalendar()}

        {activeTab === 'requests' && (
          <div className="grid grid-cols-1 gap-6">
             {/* Admin: Approval Queue */}
             {isAdmin && (
               <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 mb-6">
