                   <Clock className="text-amber-500" /> Pending Approvals
                 </h3>
                 <div className="space-y-4">
                   {leaveRequests.filter(r => r.status === 'pending').length === 0 ? (
                     <p className="text-slate-500 italic">No pending requests.</p>
                   ) : (
                     leaveRequests.filter(r => r.status === 'pending').map(req => {
                       const user = users.find(u => u.id === req.userId);
                       return (
                         <div key={req.id} className="flex flex-col sm:flex-row justify-between items-start sm:items-center p-4 bg-slate-50 rounded-lg border border-slate-200">
                           <div className="flex items-start gap-3 mb-3 sm:mb-0">
                             <div className="w-10 h-10 rounded-full bg-slate-200 overflow-hidden shrink-0">
                               <img src={user?.avatar || `https://ui-avatars.com/api/?name=${user?.username}`} className="w-full h-full object-cover" />
                             </div>
                             <div>
                               <p className="font-bold text-slate-900">{user?.username || 'Unknown User'}</p>
                               <p className="text-sm text-slate-500 capitalize">{req.type} Leave • {req.startDate} to {req.endDate}</p>
                               <p className="text-sm text-slate-600 mt-1 italic">"{req.reason}"</p>
                             </div>
                           </div>
                           <div className="flex gap-2 w-full sm:w-auto">
                             <Button variant="secondary" className="flex-1 sm:flex-none text-red-600 hover:bg-red-50 border-red-200" onClick={() => handleApproveDeny(req, 'rejected')}>Deny</Button>
                             <Button className="flex-1 sm:flex-none bg-emerald-600 hover:bg-emerald-700" onClick={() => handleApproveDeny(req, 'approved')}>Approve</Button>
                           </div>
                         </div>
                       )
                     })
                   )}
                 </div>
               </div>
             )}

             {/* Personal Requests History */}
             <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
                <h3 className="text-lg font-bold text-slate-900 mb-4">My Request History</h3>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50 text-xs font-bold text-slate-500 uppercase">
                      <tr>
                        <th className="p-3">Type</th>
                        <th className="p-3">Dates</th>
                        <th className="p-3">Reason</th>
                        <th className="p-3">Status</th>
                        <th className="p-3 text-right">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                       {leaveRequests.filter(r => r.userId === currentUser.id).map(req => (
                         <tr key={req.id}>
                           <td className="p-3 font-medium capitalize">{req.type}</td>
                           <td className="p-3 text-sm text-slate-600">{req.startDate} to {req.endDate}</td>
                           <td className="p-3 text-sm text-slate-500 italic truncate max-w-xs">{req.reason}</td>
                           <td className="p-3">
                             <span className={`px-2 py-1 rounded-full text-xs font-bold capitalize ${
                               req.status === 'approved' ? 'bg-emerald-100 text-emerald-700' :
                               req.status === 'rejected' ? 'bg-red-100 text-red-700' :
                               'bg-amber-100 text-amber-700'
                             }`}>
                               {req.status}
                             </span>
                           </td>
                           <td className="p-3 text-right">
                             {req.status === 'pending' && (
                               <button 
                                 onClick={() => onDeleteLeaveRequest(req.id)}
                                 className="text-red-400 hover:text-red-600 text-sm font-medium"
                               >
                                 Cancel
                               </button>
                             )}
                           </td>
                         </tr>
                       ))}
                       {leaveRequests.filter(r => r.userId === currentUser.id).length === 0 && (
                         <tr><td colSpan={5} className="p-4 text-center text-slate-400">No requests found.</td></tr>
                       )}
                    </tbody>
                  </table>
                </div>
             </div>
          </div>
        )}

        {activeTab === 'admin_overview' && isAdmin && renderAdminOverview()}

      </div>

      {/* Request Modal */}
      <Modal isOpen={isLeaveModalOpen} onClose={() => setIsLeaveModalOpen(false)} title="Request Leave">
         <form onSubmit={handleLeaveSubmit} className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
               <div>
                  <label className="block text-sm font-bold text-slate-700 mb-1">Start Date</label>
                  <input type="date" required value={leaveForm.startDate} onChange={e => setLeaveForm({...leaveForm, startDate: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500" />
               </div>
               <div>
                  <label className="block text-sm font-bold text-slate-700 mb-1">End Date</label>
                  <input type="date" required value={leaveForm.endDate} onChange={e => setLeaveForm({...leaveForm, endDate: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500" />
               </div>
            </div>
            <div>
               <label className="block text-sm font-bold text-slate-700 mb-1">Leave Type</label>
               <select value={leaveForm.type} onChange={e => setLeaveForm({...leaveForm, type: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500">
                  <option value="sick">Sick Leave</option>
                  <option value="vacation">Vacation</option>
                  <option value="personal">Personal Reason</option>
                  <option value="emergency">Emergency</option>
               </select>
            </div>
            <div>
               <label className="block text-sm font-bold text-slate-700 mb-1">Reason</label>
               <textarea required rows={3} value={leaveForm.reason} onChange={e => setLeaveForm({...leaveForm, reason: e.target.value})} className="w-full px-3 py-2 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500" placeholder="Please describe why you need leave..."></textarea>
            </div>
            <div className="flex justify-end gap-2 mt-4">
               <Button type="button" variant="secondary" onClick={() => setIsLeaveModalOpen(false)}>Cancel</Button>
               <Button type="submit">Submit Request</Button>
            </div>
         </form>
      </Modal>

      {/* Confirmation Modal */}
      <ConfirmationModal
        isOpen={confirmModal.isOpen}
        onClose={() => setConfirmModal(prev => ({...prev, isOpen: false}))}
        onConfirm={confirmModal.action}
        title="Confirm Action"
        message={confirmModal.message}
        confirmLabel="Confirm"
        isDanger={false}
      />
    </div>
  );
};

