                    } else if (record) {
                      if (record.status === 'present') { content = <span className="text-emerald-600 font-bold text-xs">P</span>; bgColor = 'bg-emerald-50'; }
                      if (record.status === 'absent') { content = <span className="text-red-500 font-bold text-xs">A</span>; bgColor = 'bg-red-50'; }
                      if (record.status === 'holiday') { content = <span className="text-purple-500 font-bold text-xs">H</span>; bgColor = 'bg-purple-50'; }
                    }

                    return (
                      <td key={d} className={`text-center border-r border-slate-100 p-1 ${bgColor}`}>
                        {content}
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-10">

      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Attendance & Leave Management</h1>
          <p className="text-slate-500 mt-1">Track attendance, manage holidays, and approve leave requests.</p>
        </div>
        <Button onClick={() => setIsLeaveModalOpen(true)}>
          <Plus className="w-4 h-4 mr-2" /> Request Leave
        </Button>
      </div>

      {/* Tabs */}
