import React, { useState } from 'react';
import LoginPage from './pages/LoginPage';
import HomePage from './pages/HomePage';
import { AuthState } from './types';

const App: React.FC = () => {
  // Simple state-based routing/auth for this demo
  const [auth, setAuth] = useState<AuthState>({
    isAuthenticated: false,
    user: null,
  });

  const handleLogin = (username: string) => {
    // Admin Login
    if (username === 'admin') {
      setAuth({
        isAuthenticated: true,
        user: {
          id: '1',
          username: 'admin',
          email: 'admin@et-tool.com',
          role: 'admin',
          status: 'active',
          lastLogin: new Date().toLocaleString(),
          avatar: 'https://i.pravatar.cc/150?u=admin'
        },
      });
    } 
    // Employee Login
    else if (username === 'employee') {
      setAuth({
        isAuthenticated: true,
        user: {
          id: '99',
          username: 'employee',
          email: 'employee@et-tool.com',
          role: 'user', // Standard user role
          status: 'active',
          lastLogin: new Date().toLocaleString(),
          avatar: 'https://i.pravatar.cc/150?u=employee',
          firstName: 'John',
          lastName: 'Smith',
          position: 'Developer',
          department: 'IT'
        },
      });
    }
  };

  const handleLogout = () => {
    setAuth({
      isAuthenticated: false,
      user: null,
    });
  };

  return (
    <>
      {auth.isAuthenticated && auth.user ? (
        <HomePage user={auth.user} onLogout={handleLogout} />
      ) : (
        <LoginPage onLogin={handleLogin} />
      )}
    </>
  );
};

export default App;

