import React, { useState } from 'react';
import { User, LeaveRequest, AttendanceRecord } from '../types';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import ConfirmationModal from '../components/ui/ConfirmationModal';
import { Calendar, CheckCircle, XCircle, Clock, ChevronLeft, ChevronRight, Plus, User as UserIcon, ShieldAlert } from 'lucide-react';

interface AttendancePageProps {
  currentUser: User;
  users: User[];
  leaveRequests: LeaveRequest[];
  attendanceRecords: AttendanceRecord[];
  onAddLeaveRequest: (request: Omit<LeaveRequest, 'id' | 'status' | 'createdAt'>) => void;
  onUpdateLeaveStatus: (id: string, status: 'approved' | 'rejected', comment?: string) => void;
  onDeleteLeaveRequest: (id: string) => void;
  onUpdateAttendance: (record: AttendanceRecord) => void;
}

const AttendancePage: React.FC<AttendancePageProps> = ({
  currentUser,
  users,
  leaveRequests,
  attendanceRecords,
  onAddLeaveRequest,
  onUpdateLeaveStatus,
  onDeleteLeaveRequest,
  onUpdateAttendance
}) => {
  const isAdmin = currentUser.role === 'admin' || currentUser.role === 'manager';
  const [activeTab, setActiveTab] = useState<'calendar' | 'requests' | 'admin_overview'>('calendar');

  // Calendar State
  const [currentDate, setCurrentDate] = useState(new Date());

  // Modal States
  const [isLeaveModalOpen, setIsLeaveModalOpen] = useState(false);
  const [confirmModal, setConfirmModal] = useState<{isOpen: boolean, action: () => void, message: string}>({isOpen: false, action: () => {}, message: ''});

  // Leave Form State
  const [leaveForm, setLeaveForm] = useState({
    startDate: '',
    endDate: '',
    type: 'sick',
    reason: ''
  });

  // --- Helpers ---

  const getDaysInMonth = (date: Date) => {
    return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  };

  const getFirstDayOfMonth = (date: Date) => {
    return new Date(date.getFullYear(), date.getMonth(), 1).getDay();
  };

  const nextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  const prevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const formatDate = (date: Date) => {
    return date.toISOString().split('T')[0];
  };

  // --- Handlers ---

  const handleLeaveSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAddLeaveRequest({
      userId: currentUser.id,
      startDate: leaveForm.startDate,
      endDate: leaveForm.endDate,
      type: leaveForm.type as any,
      reason: leaveForm.reason
    });
    setIsLeaveModalOpen(false);
    setLeaveForm({ startDate: '', endDate: '', type: 'sick', reason: '' });
  };

  const handleApproveDeny = (req: LeaveRequest, status: 'approved' | 'rejected') => {
    setConfirmModal({
      isOpen: true,
      message: `Are you sure you want to ${status} this request from ${users.find(u => u.id === req.userId)?.username}?`,
      action: () => {
        onUpdateLeaveStatus(req.id, status);
        setConfirmModal(prev => ({ ...prev, isOpen: false }));
      }
    });
  };

  // --- Render Components ---

  const renderCalendar = () => {
    const daysInMonth = getDaysInMonth(currentDate);
    const firstDay = getFirstDayOfMonth(currentDate);
    const days = [];
    const monthName = currentDate.toLocaleString('default', { month: 'long', year: 'numeric' });

    // Empty cells for previous month
    for (let i = 0; i < firstDay; i++) {
      days.push(<div key={`empty-${i}`} className="h-24 bg-slate-50 border border-slate-100"></div>);
    }

    // Days
    for (let d = 1; d <= daysInMonth; d++) {
      const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;

      // Find events strictly for this user (or global holidays)
      const attendance = attendanceRecords.find(r => r.userId === currentUser.id && r.date === dateStr);
      const leave = leaveRequests.find(r => r.userId === currentUser.id && r.startDate <= dateStr && r.endDate >= dateStr && r.status === 'approved');

      let statusColor = 'bg-white';
      let statusText = '';

      if (leave) {
        statusColor = 'bg-amber-50';
        statusText = 'On Leave';
      } else if (attendance) {
         if (attendance.status === 'present') { statusColor = 'bg-emerald-50'; statusText = 'Present'; }
         if (attendance.status === 'absent') { statusColor = 'bg-red-50'; statusText = 'Absent'; }
         if (attendance.status === 'holiday') { statusColor = 'bg-purple-50'; statusText = 'Holiday'; }
      }

      days.push(
        <div key={d} className={`h-24 border border-slate-100 p-2 relative transition-colors hover:bg-slate-50 ${statusColor}`}>
          <span className="text-sm font-semibold text-slate-700">{d}</span>
          {statusText && (
             <div className={`mt-2 text-xs font-medium px-2 py-1 rounded ${
               statusText === 'Present' ? 'text-emerald-700 bg-emerald-100' :
               statusText === 'Absent' ? 'text-red-700 bg-red-100' :
               statusText === 'On Leave' ? 'text-amber-700 bg-amber-100' :
               'text-purple-700 bg-purple-100'
             }`}>
               {statusText}
             </div>
          )}
          {attendance?.checkIn && (
            <div className="absolute bottom-1 right-2 text-[10px] text-slate-500">
              {attendance.checkIn} - {attendance.checkOut || '?'}
            </div>
          )}
        </div>
      );
    }

    return (
      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="flex items-center justify-between p-4 border-b border-slate-200">
           <h2 className="text-lg font-bold text-slate-900 flex items-center gap-2">
             <Calendar className="text-primary-500" />
             {monthName} <span className="text-sm font-normal text-slate-500 ml-2">(My Schedule)</span>
           </h2>
           <div className="flex gap-2">
             <Button variant="secondary" onClick={prevMonth} className="p-2"><ChevronLeft size={16} /></Button>
             <Button variant="secondary" onClick={nextMonth} className="p-2"><ChevronRight size={16} /></Button>
           </div>
        </div>
        <div className="grid grid-cols-7 text-center bg-slate-50 border-b border-slate-200">
          {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
            <div key={day} className="py-2 text-xs font-bold text-slate-500 uppercase">{day}</div>
          ))}
        </div>
        <div className="grid grid-cols-7">
          {days}
        </div>
      </div>
    );
  };

  const renderAdminOverview = () => {
    // Master Matrix: Rows = Users, Cols = Dates (simple scrollable view for now)
    const daysInMonth = getDaysInMonth(currentDate);
    const dateHeaders = [];
    for(let i=1; i<=daysInMonth; i++) dateHeaders.push(i);

    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
           <h2 className="text-lg font-bold text-slate-900">Attendance Master Sheet</h2>
           <div className="flex gap-2">
             <Button variant="secondary" onClick={prevMonth}><ChevronLeft size={16} /></Button>
             <span className="font-bold text-slate-700 px-2 py-2">{currentDate.toLocaleString('default', { month: 'long' })}</span>
             <Button variant="secondary" onClick={nextMonth}><ChevronRight size={16} /></Button>
           </div>
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50">
                <th className="p-3 sticky left-0 bg-slate-50 z-10 border-r border-slate-200 min-w-[200px] text-xs font-bold text-slate-500 uppercase">Employee</th>
                {dateHeaders.map(d => (
                  <th key={d} className="p-2 min-w-[40px] text-center text-xs font-bold text-slate-500 border-r border-slate-100">{d}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {users.map(user => (
                <tr key={user.id} className="hover:bg-slate-50">
                  <td className="p-3 sticky left-0 bg-white border-r border-slate-200 flex items-center gap-2">
                     <div className="w-6 h-6 rounded-full bg-slate-200 overflow-hidden">
                       <img src={user.avatar || `https://ui-avatars.com/api/?name=${user.username}`} alt="" className="w-full h-full object-cover" />
                     </div>
                     <span className="text-sm font-medium text-slate-900">{user.username}</span>
                  </td>
                  {dateHeaders.map(d => {
                    const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
                    const record = attendanceRecords.find(r => r.userId === user.id && r.date === dateStr);
                    const leave = leaveRequests.find(r => r.userId === user.id && r.startDate <= dateStr && r.endDate >= dateStr && r.status === 'approved');

                    let content = <span className="text-slate-200">-</span>;
                    let bgColor = '';

                    if (leave) {
                      content = <span className="text-amber-600 font-bold text-xs">L</span>;
                      bgColor = 'bg-amber-50';
                    } else if (record) {
                      if (record.status === 'present') { content = <span className="text-emerald-600 font-bold text-xs">P</span>; bgColor = 'bg-emerald-50'; }
                      if (record.status === 'absent') { content = <span className="text-red-500 font-bold text-xs">A</span>; bgColor = 'bg-red-50'; }
                      if (record.status === 'holiday') { content = <span className="text-purple-500 font-bold text-xs">H</span>; bgColor = 'bg-purple-50'; }
                    }

                    return (
                      <td key={d} className={`text-center border-r border-slate-100 p-1 ${bgColor}`}>
                        {content}
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">

      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Attendance & Leave Management</h1>
          <p className="text-slate-500 mt-1">
            {isAdmin ? 'Manage employee attendance and leave approvals.' : 'Track your attendance and request leave.'}
          </p>
        </div>
        {/* Everyone can request leave for themselves */}
        <Button onClick={() => setIsLeaveModalOpen(true)}>
          <Plus className="w-4 h-4 mr-2" /> Request Leave
        </Button>
      </div>

      {/* Tabs */}
      <div className="border-b border-slate-200">
         <nav className="flex space-x-8">
           <button 
             onClick={() => setActiveTab('calendar')}
             className={`py-4 px-1 border-b-2 font-medium text-sm transition-colors ${activeTab === 'calendar' ? 'border-primary-500 text-primary-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
           >
             My Calendar
           </button>
           <button 
             onClick={() => setActiveTab('requests')}
             className={`py-4 px-1 border-b-2 font-medium text-sm transition-colors ${activeTab === 'requests' ? 'border-primary-500 text-primary-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
           >
             {isAdmin ? 'Approvals & Requests' : 'My Requests'}
             {isAdmin && (
                <span className="ml-2 bg-red-100 text-red-600 px-2 py-0.5 rounded-full text-xs font-bold">
                  {leaveRequests.filter(r => r.status === 'pending').length}
                </span>
             )}
           </button>
           {isAdmin && (
             <button 
               onClick={() => setActiveTab('admin_overview')}
               className={`py-4 px-1 border-b-2 font-medium text-sm transition-colors ${activeTab === 'admin_overview' ? 'border-primary-500 text-primary-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
             >
               Admin Overview
             </button>
           )}
         </nav>
      </div>

      {/* Content */}
      <div className="pt-4">

        {activeTab === 'calendar' && renderCalendar()}

        {activeTab === 'requests' && (
          <div className="grid grid-cols-1 gap-6">

             {/* Admin: Approval Queue - STRICTLY ADMIN ONLY */}
             {isAdmin && (
               <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 mb-6">
                 <h3 className="text-lg font-bold text-slate-900 mb-4 flex items-center gap-2">
                   <ShieldAlert className="text-amber-500" /> Pending Employee Approvals
                 </h3>
                 <div className="space-y-4">
                   {leaveRequests.filter(r => r.status === 'pending').length === 0 ? (
                     <p className="text-slate-500 italic p-4 bg-slate-50 rounded-lg">No pending requests from employees.</p>
                   ) : (
                     leaveRequests.filter(r => r.status === 'pending').map(req => {
                       const user = users.find(u => u.id === req.userId);
                       return (
                         <div key={req.id} className="flex flex-col md:flex-row justify-between items-start md:items-center p-5 bg-white rounded-lg border border-slate-200 shadow-sm hover:border-primary-200 transition-colors">
                           <div className="flex items-start gap-4 mb-4 md:mb-0">
                             <div className="w-12 h-12 rounded-full bg-slate-100 overflow-hidden shrink-0 border border-slate-200">
                               <img src={user?.avatar || `https://ui-avatars.com/api/?name=${user?.username}`} className="w-full h-full object-cover" />
                             </div>
                             <div>
                               <div className="flex items-center gap-2">
                                  <p className="font-bold text-slate-900 text-lg">{user?.username || 'Unknown User'}</p>
                                  <span className="text-xs bg-slate-100 text-slate-600 px-2 py-0.5 rounded-full uppercase tracking-wide">{user?.role}</span>
                               </div>
                               <p className="text-sm font-medium text-slate-700 mt-1 capitalize">
                                  Requesting: <span className="text-primary-600">{req.type} Leave</span>
                               </p>
                               <p className="text-xs text-slate-500">
                                  {req.startDate} <span className="px-1">to</span> {req.endDate}
                               </p>
                               <div className="mt-2 p-2 bg-slate-50 rounded text-sm text-slate-700 italic border-l-4 border-slate-300">
                                  "{req.reason}"
                               </div>
                             </div>
                           </div>
                           <div className="flex gap-3 w-full md:w-auto">
                             <Button variant="secondary" className="flex-1 md:flex-none text-red-600 hover:bg-red-50 border-red-200" onClick={() => handleApproveDeny(req, 'rejected')}>Deny Request</Button>
                             <Button className="flex-1 md:flex-none bg-emerald-600 hover:bg-emerald-700 border-transparent shadow-emerald-500/20" onClick={() => handleApproveDeny(req, 'approved')}>Approve Request</Button>
                           </div>
                         </div>
                       )
                     })
                   )}
                 </div>
               </div>
             )}

             {/* Personal Requests History - Visible to Everyone (but filtered for current user) */}
             <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
                <h3 className="text-lg font-bold text-slate-900 mb-4">
                  {isAdmin ? "My Personal Request History" : "My Leave History"}
                </h3>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50 text-xs font-bold text-slate-500 uppercase">
                      <tr>
                        <th className="p-3 rounded-l-lg">Type</th>
                        <th className="p-3">Dates</th>
                        <th className="p-3">Reason</th>
                        <th className="p-3">Status</th>
                        <th className="p-3 text-right rounded-r-lg">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                       {leaveRequests.filter(r => r.userId === currentUser.id).map(req => (
                         <tr key={req.id} className="hover:bg-slate-50/50">
                           <td className="p-3 font-medium capitalize text-slate-800">{req.type}</td>
                           <td className="p-3 text-sm text-slate-600">{req.startDate} to {req.endDate}</td>
                           <td className="p-3 text-sm text-slate-500 italic truncate max-w-xs">"{req.reason}"</td>
                           <td className="p-3">
                             <span className={`px-2.5 py-1 rounded-full text-xs font-bold capitalize inline-flex items-center ${
                               req.status === 'approved' ? 'bg-emerald-100 text-emerald-700' :
                               req.status === 'rejected' ? 'bg-red-100 text-red-700' :
                               'bg-amber-100 text-amber-700'
                             }`}>
                               {req.status === 'approved' && <CheckCircle size={12} className="mr-1" />}
                               {req.status === 'rejected' && <XCircle size={12} className="mr-1" />}
                               {req.status === 'pending' && <Clock size={12} className="mr-1" />}
                               {req.status}
                             </span>
                           </td>
                           <td className="p-3 text-right">
                             {req.status === 'pending' && (
                               <button 
                                 onClick={() => onDeleteLeaveRequest(req.id)}
                                 className="text-red-400 hover:text-red-600 text-sm font-medium hover:underline"
                               >
                                 Cancel Request
                               </button>
                             )}
                           </td>
                         </tr>
                       ))}
                       {leaveRequests.filter(r => r.userId === currentUser.id).length === 0 && (
                         <tr><td colSpan={5} className="p-8 text-center text-slate-400">You haven't made any leave requests yet.</td></tr>
                       )}
                    </tbody>
                  </table>
                </div>
             </div>
          </div>
        )}

        {activeTab === 'admin_overview' && isAdmin && renderAdminOverview()}

      </div>

      {/* Request Modal */}
      <Modal isOpen={isLeaveModalOpen} onClose={() => setIsLeaveModalOpen(false)} title="Request Leave">
         <form onSubmit={handleLeaveSubmit} className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
               <div>
                  <label className="block text-sm font-bold text-slate-700 mb-1">Start Date</label>
                  <input 
                    type="date" 
                    required 
                    value={leaveForm.startDate} 
                    onChange={e => setLeaveForm({...leaveForm, startDate: e.target.value})} 
                    className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500" 
                  />
               </div>
               <div>
                  <label className="block text-sm font-bold text-slate-700 mb-1">End Date</label>
                  <input 
                    type="date" 
                    required 
                    value={leaveForm.endDate} 
                    onChange={e => setLeaveForm({...leaveForm, endDate: e.target.value})} 
                    className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500" 
                  />
               </div>
            </div>
            <div>
               <label className="block text-sm font-bold text-slate-700 mb-1">Leave Type</label>
               <select 
                 value={leaveForm.type} 
                 onChange={e => setLeaveForm({...leaveForm, type: e.target.value})} 
                 className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500"
               >
                  <option value="sick">Sick Leave</option>
                  <option value="vacation">Vacation</option>
                  <option value="personal">Personal Reason</option>
                  <option value="emergency">Emergency</option>
               </select>
            </div>
            <div>
               <label className="block text-sm font-bold text-slate-700 mb-1">Reason</label>
               <textarea 
                 required 
                 rows={3} 
                 value={leaveForm.reason} 
                 onChange={e => setLeaveForm({...leaveForm, reason: e.target.value})} 
                 className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500" 
                 placeholder="Please describe why you need leave..."
               ></textarea>
            </div>
            <div className="flex justify-end gap-2 mt-4">
               <Button type="button" variant="secondary" onClick={() => setIsLeaveModalOpen(false)}>Cancel</Button>
               <Button type="submit">Submit Request</Button>
            </div>
         </form>
      </Modal>

      {/* Confirmation Modal */}
      <ConfirmationModal
        isOpen={confirmModal.isOpen}
        onClose={() => setConfirmModal(prev => ({...prev, isOpen: false}))}
        onConfirm={confirmModal.action}
        title="Confirm Action"
        message={confirmModal.message}
        confirmLabel="Confirm"
        isDanger={false}
      />
    </div>
  );
};

export default AttendancePage;

import React, { useState } from 'react';
import { User, LeaveRequest, AttendanceRecord } from '../types';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import ConfirmationModal from '../components/ui/ConfirmationModal';
import { Calendar, CheckCircle, XCircle, Clock, ChevronLeft, ChevronRight, Plus, User as UserIcon, ShieldAlert, MessageSquare } from 'lucide-react';

interface AttendancePageProps {
  currentUser: User;
  users: User[];
  leaveRequests: LeaveRequest[];
  attendanceRecords: AttendanceRecord[];
  onAddLeaveRequest: (request: Omit<LeaveRequest, 'id' | 'status' | 'createdAt'>) => void;
  onUpdateLeaveStatus: (id: string, status: 'approved' | 'rejected', comment?: string) => void;
  onDeleteLeaveRequest: (id: string) => void;
  onUpdateAttendance: (record: AttendanceRecord) => void;
}

const AttendancePage: React.FC<AttendancePageProps> = ({
  currentUser,
  users,
  leaveRequests,
  attendanceRecords,
  onAddLeaveRequest,
  onUpdateLeaveStatus,
  onDeleteLeaveRequest,
  onUpdateAttendance
}) => {
  const isAdmin = currentUser.role === 'admin' || currentUser.role === 'manager';
  const [activeTab, setActiveTab] = useState<'calendar' | 'requests' | 'admin_overview'>('calendar');

  // Calendar State
  const [currentDate, setCurrentDate] = useState(new Date());

  // Modal States
  const [isLeaveModalOpen, setIsLeaveModalOpen] = useState(false);
  const [confirmModal, setConfirmModal] = useState<{isOpen: boolean, action: () => void, message: string}>({isOpen: false, action: () => {}, message: ''});

  // Reject Modal State
  const [rejectModal, setRejectModal] = useState<{isOpen: boolean, req: LeaveRequest | null}>({isOpen: false, req: null});
  const [rejectionReason, setRejectionReason] = useState('');

  // Leave Form State
  const [leaveForm, setLeaveForm] = useState({
    startDate: '',
    endDate: '',
    type: 'sick',
    reason: ''
  });

  // --- Helpers ---

  const getDaysInMonth = (date: Date) => {
    return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  };

  const getFirstDayOfMonth = (date: Date) => {
    return new Date(date.getFullYear(), date.getMonth(), 1).getDay();
  };

  const nextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  const prevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const formatDate = (date: Date) => {
    return date.toISOString().split('T')[0];
  };

  // --- Handlers ---

  const handleLeaveSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onAddLeaveRequest({
      userId: currentUser.id,
      startDate: leaveForm.startDate,
      endDate: leaveForm.endDate,
      type: leaveForm.type as any,
      reason: leaveForm.reason
    });
    setIsLeaveModalOpen(false);
    setLeaveForm({ startDate: '', endDate: '', type: 'sick', reason: '' });
  };

  // Open Reject Modal
  const handleRejectClick = (req: LeaveRequest) => {
    setRejectModal({ isOpen: true, req });
    setRejectionReason('');
  };

  // Submit Rejection
  const handleRejectSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (rejectModal.req) {
      // Enforce a reason if it's empty? Optionally. For now we just pass it.
      const reason = rejectionReason.trim() || 'No reason provided';
      onUpdateLeaveStatus(rejectModal.req.id, 'rejected', reason);
      setRejectModal({ isOpen: false, req: null });
    }
  };

  // Handle Approve
  const handleApproveClick = (req: LeaveRequest) => {
    setConfirmModal({
      isOpen: true,
      message: `Are you sure you want to approve this request from ${users.find(u => u.id === req.userId)?.username}?`,
      action: () => {
        onUpdateLeaveStatus(req.id, 'approved', 'Approved');
        setConfirmModal(prev => ({ ...prev, isOpen: false }));
      }
    });
  };

  // --- Render Components ---

  const renderCalendar = () => {
    const daysInMonth = getDaysInMonth(currentDate);
    const firstDay = getFirstDayOfMonth(currentDate);
    const days = [];
    const monthName = currentDate.toLocaleString('default', { month: 'long', year: 'numeric' });

    // Empty cells for previous month
    for (let i = 0; i < firstDay; i++) {
      days.push(<div key={`empty-${i}`} className="h-24 bg-slate-50 border border-slate-100"></div>);
    }

    // Days
    for (let d = 1; d <= daysInMonth; d++) {
      const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;

      // Find events strictly for this user (or global holidays)
      const attendance = attendanceRecords.find(r => r.userId === currentUser.id && r.date === dateStr);
      const leave = leaveRequests.find(r => r.userId === currentUser.id && r.startDate <= dateStr && r.endDate >= dateStr && r.status === 'approved');

      let statusColor = 'bg-white';
      let statusText = '';

      if (leave) {
        statusColor = 'bg-amber-50';
        statusText = 'On Leave';
      } else if (attendance) {
         if (attendance.status === 'present') { statusColor = 'bg-emerald-50'; statusText = 'Present'; }
         if (attendance.status === 'absent') { statusColor = 'bg-red-50'; statusText = 'Absent'; }
         if (attendance.status === 'holiday') { statusColor = 'bg-purple-50'; statusText = 'Holiday'; }
      }

      days.push(
        <div key={d} className={`h-24 border border-slate-100 p-2 relative transition-colors hover:bg-slate-50 ${statusColor}`}>
          <span className="text-sm font-semibold text-slate-700">{d}</span>
          {statusText && (
             <div className={`mt-2 text-xs font-medium px-2 py-1 rounded ${
               statusText === 'Present' ? 'text-emerald-700 bg-emerald-100' :
               statusText === 'Absent' ? 'text-red-700 bg-red-100' :
               statusText === 'On Leave' ? 'text-amber-700 bg-amber-100' :
               'text-purple-700 bg-purple-100'
             }`}>
               {statusText}
             </div>
          )}
          {attendance?.checkIn && (
            <div className="absolute bottom-1 right-2 text-[10px] text-slate-500">
              {attendance.checkIn} - {attendance.checkOut || '?'}
            </div>
          )}
        </div>
      );
    }

    return (
      <div className="bg-white rounded-2xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="flex items-center justify-between p-4 border-b border-slate-200">
           <h2 className="text-lg font-bold text-slate-900 flex items-center gap-2">
             <Calendar className="text-primary-500" />
             {monthName} <span className="text-sm font-normal text-slate-500 ml-2">(My Schedule)</span>
           </h2>
           <div className="flex gap-2">
             <Button variant="secondary" onClick={prevMonth} className="p-2"><ChevronLeft size={16} /></Button>
             <Button variant="secondary" onClick={nextMonth} className="p-2"><ChevronRight size={16} /></Button>
           </div>
        </div>
        <div className="grid grid-cols-7 text-center bg-slate-50 border-b border-slate-200">
          {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
            <div key={day} className="py-2 text-xs font-bold text-slate-500 uppercase">{day}</div>
          ))}
        </div>
        <div className="grid grid-cols-7">
          {days}
        </div>
      </div>
    );
  };

  const renderAdminOverview = () => {
    // Master Matrix: Rows = Users, Cols = Dates (simple scrollable view for now)
    const daysInMonth = getDaysInMonth(currentDate);
    const dateHeaders = [];
    for(let i=1; i<=daysInMonth; i++) dateHeaders.push(i);

    return (
      <div className="space-y-6">
        <div className="flex items-center justify-between">
           <h2 className="text-lg font-bold text-slate-900">Attendance Master Sheet</h2>
           <div className="flex gap-2">
             <Button variant="secondary" onClick={prevMonth}><ChevronLeft size={16} /></Button>
             <span className="font-bold text-slate-700 px-2 py-2">{currentDate.toLocaleString('default', { month: 'long' })}</span>
             <Button variant="secondary" onClick={nextMonth}><ChevronRight size={16} /></Button>
           </div>
        </div>

        <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-slate-50">
                <th className="p-3 sticky left-0 bg-slate-50 z-10 border-r border-slate-200 min-w-[200px] text-xs font-bold text-slate-500 uppercase">Employee</th>
                {dateHeaders.map(d => (
                  <th key={d} className="p-2 min-w-[40px] text-center text-xs font-bold text-slate-500 border-r border-slate-100">{d}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {users.map(user => (
                <tr key={user.id} className="hover:bg-slate-50">
                  <td className="p-3 sticky left-0 bg-white border-r border-slate-200 flex items-center gap-2">
                     <div className="w-6 h-6 rounded-full bg-slate-200 overflow-hidden">
                       <img src={user.avatar || `https://ui-avatars.com/api/?name=${user.username}`} alt="" className="w-full h-full object-cover" />
                     </div>
                     <span className="text-sm font-medium text-slate-900">{user.username}</span>
                  </td>
                  {dateHeaders.map(d => {
                    const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
                    const record = attendanceRecords.find(r => r.userId === user.id && r.date === dateStr);
                    const leave = leaveRequests.find(r => r.userId === user.id && r.startDate <= dateStr && r.endDate >= dateStr && r.status === 'approved');

                    let content = <span className="text-slate-200">-</span>;
                    let bgColor = '';

                    if (leave) {
                      content = <span className="text-amber-600 font-bold text-xs">L</span>;
                      bgColor = 'bg-amber-50';
                    } else if (record) {
                      if (record.status === 'present') { content = <span className="text-emerald-600 font-bold text-xs">P</span>; bgColor = 'bg-emerald-50'; }
                      if (record.status === 'absent') { content = <span className="text-red-500 font-bold text-xs">A</span>; bgColor = 'bg-red-50'; }
                      if (record.status === 'holiday') { content = <span className="text-purple-500 font-bold text-xs">H</span>; bgColor = 'bg-purple-50'; }
                    }

                    return (
                      <td key={d} className={`text-center border-r border-slate-100 p-1 ${bgColor}`}>
                        {content}
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-20">

      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Attendance & Leave Management</h1>
          <p className="text-slate-500 mt-1">
            {isAdmin ? 'Manage employee attendance and leave approvals.' : 'Track your attendance and request leave.'}
          </p>
        </div>
        {/* Everyone can request leave for themselves */}
        <Button onClick={() => setIsLeaveModalOpen(true)}>
          <Plus className="w-4 h-4 mr-2" /> Request Leave
        </Button>
      </div>

      {/* Tabs */}
      <div className="border-b border-slate-200">
         <nav className="flex space-x-8">
           <button 
             onClick={() => setActiveTab('calendar')}
             className={`py-4 px-1 border-b-2 font-medium text-sm transition-colors ${activeTab === 'calendar' ? 'border-primary-500 text-primary-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
           >
             My Calendar
           </button>
           <button 
             onClick={() => setActiveTab('requests')}
             className={`py-4 px-1 border-b-2 font-medium text-sm transition-colors ${activeTab === 'requests' ? 'border-primary-500 text-primary-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
           >
             {isAdmin ? 'Approvals & Requests' : 'My Requests'}
             {isAdmin && (
                <span className="ml-2 bg-red-100 text-red-600 px-2 py-0.5 rounded-full text-xs font-bold">
                  {leaveRequests.filter(r => r.status === 'pending').length}
                </span>
             )}
           </button>
           {isAdmin && (
             <button 
               onClick={() => setActiveTab('admin_overview')}
               className={`py-4 px-1 border-b-2 font-medium text-sm transition-colors ${activeTab === 'admin_overview' ? 'border-primary-500 text-primary-600' : 'border-transparent text-slate-500 hover:text-slate-700'}`}
             >
               Admin Overview
             </button>
           )}
         </nav>
      </div>

      {/* Content */}
      <div className="pt-4">

        {activeTab === 'calendar' && renderCalendar()}

        {activeTab === 'requests' && (
          <div className="grid grid-cols-1 gap-6">

             {/* Admin: Approval Queue - STRICTLY ADMIN ONLY */}
             {isAdmin && (
               <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 mb-6">
                 <h3 className="text-lg font-bold text-slate-900 mb-4 flex items-center gap-2">
                   <ShieldAlert className="text-amber-500" /> Pending Employee Approvals
                 </h3>
                 <div className="space-y-4">
                   {leaveRequests.filter(r => r.status === 'pending').length === 0 ? (
                     <p className="text-slate-500 italic p-4 bg-slate-50 rounded-lg">No pending requests from employees.</p>
                   ) : (
                     leaveRequests.filter(r => r.status === 'pending').map(req => {
                       const user = users.find(u => u.id === req.userId);
                       return (
                         <div key={req.id} className="flex flex-col md:flex-row justify-between items-start md:items-center p-5 bg-white rounded-lg border border-slate-200 shadow-sm hover:border-primary-200 transition-colors">
                           <div className="flex items-start gap-4 mb-4 md:mb-0">
                             <div className="w-12 h-12 rounded-full bg-slate-100 overflow-hidden shrink-0 border border-slate-200">
                               <img src={user?.avatar || `https://ui-avatars.com/api/?name=${user?.username}`} className="w-full h-full object-cover" />
                             </div>
                             <div>
                               <div className="flex items-center gap-2">
                                  <p className="font-bold text-slate-900 text-lg">{user?.username || 'Unknown User'}</p>
                                  <span className="text-xs bg-slate-100 text-slate-600 px-2 py-0.5 rounded-full uppercase tracking-wide">{user?.role}</span>
                               </div>
                               <p className="text-sm font-medium text-slate-700 mt-1 capitalize">
                                  Requesting: <span className="text-primary-600">{req.type} Leave</span>
                               </p>
                               <p className="text-xs text-slate-500">
                                  {req.startDate} <span className="px-1">to</span> {req.endDate}
                               </p>
                               <div className="mt-2 p-2 bg-slate-50 rounded text-sm text-slate-700 italic border-l-4 border-slate-300">
                                  "{req.reason}"
                               </div>
                             </div>
                           </div>
                           <div className="flex gap-3 w-full md:w-auto">
                             <Button variant="secondary" className="flex-1 md:flex-none text-red-600 hover:bg-red-50 border-red-200" onClick={() => handleRejectClick(req)}>Deny Request</Button>
                             <Button className="flex-1 md:flex-none bg-emerald-600 hover:bg-emerald-700 border-transparent shadow-emerald-500/20" onClick={() => handleApproveClick(req)}>Approve Request</Button>
                           </div>
                         </div>
                       )
                     })
                   )}
                 </div>
               </div>
             )}

             {/* Personal Requests History - Visible to Everyone */}
             <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6">
                <h3 className="text-lg font-bold text-slate-900 mb-4">
                  {isAdmin ? "My Personal Request History" : "My Leave History"}
                </h3>
                <div className="overflow-x-auto">
                  <table className="w-full text-left">
                    <thead className="bg-slate-50 text-xs font-bold text-slate-500 uppercase">
                      <tr>
                        <th className="p-3 rounded-l-lg">Type</th>
                        <th className="p-3">Dates</th>
                        <th className="p-3">Reason</th>
                        <th className="p-3">Status & Admin Message</th>
                        <th className="p-3 text-right rounded-r-lg">Actions</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                       {leaveRequests.filter(r => r.userId === currentUser.id).map(req => (
                         <tr key={req.id} className="hover:bg-slate-50/50">
                           <td className="p-3 font-medium capitalize text-slate-800 align-top">{req.type}</td>
                           <td className="p-3 text-sm text-slate-600 align-top">{req.startDate} to {req.endDate}</td>
                           <td className="p-3 text-sm text-slate-500 italic truncate max-w-xs align-top">"{req.reason}"</td>
                           <td className="p-3 align-top">
                             <div className="flex flex-col gap-2">
                               <span className={`px-2.5 py-1 rounded-full text-xs font-bold capitalize inline-flex items-center w-fit ${
                                 req.status === 'approved' ? 'bg-emerald-100 text-emerald-700' :
                                 req.status === 'rejected' ? 'bg-red-100 text-red-700' :
                                 'bg-amber-100 text-amber-700'
                               }`}>
                                 {req.status === 'approved' && <CheckCircle size={12} className="mr-1" />}
                                 {req.status === 'rejected' && <XCircle size={12} className="mr-1" />}
                                 {req.status === 'pending' && <Clock size={12} className="mr-1" />}
                                 {req.status}
                               </span>

                               {/* Admin Comment Display */}
                               {(req.adminComment) && (
                                 <div className={`text-xs p-2 rounded-lg border flex gap-2 ${
                                   req.status === 'rejected' ? 'bg-red-50 border-red-100 text-red-800' : 'bg-slate-50 border-slate-100 text-slate-600'
                                 }`}>
                                    <MessageSquare size={14} className="shrink-0 mt-0.5" />
                                    <div>
                                      <span className="font-bold block mb-0.5">Admin Response:</span>
                                      "{req.adminComment}"
                                    </div>
                                 </div>
                               )}
                             </div>
                           </td>
                           <td className="p-3 text-right align-top">
                             {req.status === 'pending' && (
                               <button 
                                 onClick={() => onDeleteLeaveRequest(req.id)}
                                 className="text-red-400 hover:text-red-600 text-sm font-medium hover:underline"
                               >
                                 Cancel Request
                               </button>
                             )}
                           </td>
                         </tr>
                       ))}
                       {leaveRequests.filter(r => r.userId === currentUser.id).length === 0 && (
                         <tr><td colSpan={5} className="p-8 text-center text-slate-400">You haven't made any leave requests yet.</td></tr>
                       )}
                    </tbody>
                  </table>
                </div>
             </div>
          </div>
        )}

        {activeTab === 'admin_overview' && isAdmin && renderAdminOverview()}

      </div>

      {/* Request Leave Modal */}
      <Modal isOpen={isLeaveModalOpen} onClose={() => setIsLeaveModalOpen(false)} title="Request Leave">
         <form onSubmit={handleLeaveSubmit} className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
               <div>
                  <label className="block text-sm font-bold text-slate-700 mb-1">Start Date</label>
                  <input 
                    type="date" 
                    required 
                    value={leaveForm.startDate} 
                    onChange={e => setLeaveForm({...leaveForm, startDate: e.target.value})} 
                    className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500" 
                  />
               </div>
               <div>
                  <label className="block text-sm font-bold text-slate-700 mb-1">End Date</label>
                  <input 
                    type="date" 
                    required 
                    value={leaveForm.endDate} 
                    onChange={e => setLeaveForm({...leaveForm, endDate: e.target.value})} 
                    className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500" 
                  />
               </div>
            </div>
            <div>
               <label className="block text-sm font-bold text-slate-700 mb-1">Leave Type</label>
               <select 
                 value={leaveForm.type} 
                 onChange={e => setLeaveForm({...leaveForm, type: e.target.value})} 
                 className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500"
               >
                  <option value="sick">Sick Leave</option>
                  <option value="vacation">Vacation</option>
                  <option value="personal">Personal Reason</option>
                  <option value="emergency">Emergency</option>
               </select>
            </div>
            <div>
               <label className="block text-sm font-bold text-slate-700 mb-1">Reason</label>
               <textarea 
                 required 
                 rows={3} 
                 value={leaveForm.reason} 
                 onChange={e => setLeaveForm({...leaveForm, reason: e.target.value})} 
                 className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-primary-500" 
                 placeholder="Please describe why you need leave..."
               ></textarea>
            </div>
            <div className="flex justify-end gap-2 mt-4">
               <Button type="button" variant="secondary" onClick={() => setIsLeaveModalOpen(false)}>Cancel</Button>
               <Button type="submit">Submit Request</Button>
            </div>
         </form>
      </Modal>

      {/* Reject Reason Modal */}
      <Modal isOpen={rejectModal.isOpen} onClose={() => setRejectModal({...rejectModal, isOpen: false})} title="Deny Leave Request">
        <form onSubmit={handleRejectSubmit} className="space-y-4">
          <div className="bg-amber-50 border border-amber-200 rounded-lg p-3 text-sm text-amber-800 mb-4">
             You are about to deny a leave request. Please provide a reason for the employee.
          </div>
          <div>
            <label className="block text-sm font-bold text-slate-700 mb-1">Reason for Denial <span className="text-red-500">*</span></label>
            <textarea
              required
              rows={4}
              value={rejectionReason}
              onChange={(e) => setRejectionReason(e.target.value)}
              className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-red-500"
              placeholder="e.g., Critical project deadline overlapping..."
            />
          </div>
          <div className="flex justify-end gap-2 mt-4">
            <Button type="button" variant="secondary" onClick={() => setRejectModal({...rejectModal, isOpen: false})}>Cancel</Button>
            <Button type="submit" variant="danger">Confirm Denial</Button>
          </div>
        </form>
      </Modal>

      {/* Confirmation Modal */}
      <ConfirmationModal
        isOpen={confirmModal.isOpen}
        onClose={() => setConfirmModal(prev => ({...prev, isOpen: false}))}
        onConfirm={confirmModal.action}
        title="Confirm Action"
        message={confirmModal.message}
        confirmLabel="Confirm"
        isDanger={false}
      />
    </div>
  );
};

export default AttendancePage;

import React from 'react';

export interface User {
  id: string;
  username: string;
  email: string;
  role: string;
  status: 'active' | 'inactive';
  lastLogin: string;
  avatar?: string;

  // Extended Details
  firstName?: string;
  lastName?: string;
  phone?: string;
  department?: string;
  position?: string;
  location?: string;
  joinDate?: string;
  bio?: string;

  // Preferences
  preferences?: {
    theme?: 'light' | 'dark';
    notifications?: boolean;
    dashboardLayout?: string[];
  };
}

export interface AuthState {
  isAuthenticated: boolean;
  user: User | null;
}

export interface NavItem {
  id: string;
  label: string;
  icon: React.ReactNode;
}

export interface Role {
  id: string;
  name: string;
  description: string;
  permissions: string[];
  isSystem?: boolean;
}

export interface Department {
  id: string;
  name: string;
  description?: string;
}

export interface Permission {
  id: string;
  label: string;
  description: string;
}

// --- Attendance & Leave ---

export type LeaveStatus = 'pending' | 'approved' | 'rejected';
export type LeaveType = 'sick' | 'vacation' | 'personal' | 'emergency';

export interface LeaveRequest {
  id: string;
  userId: string;
  startDate: string; // YYYY-MM-DD
  endDate: string;   // YYYY-MM-DD
  type: LeaveType;
  reason: string;
  status: LeaveStatus;
  adminComment?: string;
  createdAt: string;
}

export interface AttendanceRecord {
  id: string;
  userId: string;
  date: string; // YYYY-MM-DD
  status: 'present' | 'absent' | 'leave' | 'holiday' | 'weekend';
  checkIn?: string; // HH:MM
  checkOut?: string; // HH:MM
}

export interface PerformanceReview {
  id: string;
  userId: string;
  date: string;
  rating: number; // 1-5
  comment: string;
  reviewer: string;
}

// --- Project Management ---

export type TaskStatus = 'todo' | 'in-progress' | 'testing' | 'pending-approval' | 'done';
export type TaskPriority = 'low' | 'medium' | 'high' | 'urgent';

export interface Project {
  id: string;
  name: string;
  description: string;
  status: 'active' | 'completed' | 'on-hold';
  startDate: string;
  endDate: string;
  managerId: string;
  teamMemberIds: string[];
  progress: number; // 0-100
}

export interface Task {
  id: string;
  projectId: string;
  title: string;
