  };

  const handleDeleteLeaveRequest = (id: string) => {
    setLeaveRequests(leaveRequests.filter(req => req.id !== id));
  };

  const handleUpdateAttendance = (record: AttendanceRecord) => {
    setAttendanceRecords(prev => {
      const existing = prev.findIndex(r => r.id === record.id);
      if (existing >= 0) {
        const updated = [...prev];
        updated[existing] = record;
        return updated;
      }
      return [...prev, record];
    });
  };

  // --- Project Handlers ---

  const handleAddProject = (newProject: Omit<Project, 'id' | 'progress'>) => {
    const project: Project = {
      ...newProject,
      id: Math.random().toString(36).substr(2, 9),
      progress: 0
    };
    setProjects([...projects, project]);
  };

  const handleDeleteProject = (projectId: string) => {
    setProjects(projects.filter(p => p.id !== projectId));
    setTasks(tasks.filter(t => t.projectId !== projectId));
  };

  const handleAddTask = (newTask: Omit<Task, 'id' | 'createdAt' | 'createdBy'>) => {
    const task: Task = {
      ...newTask,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString().split('T')[0],
      createdBy: user.id
    };
    setTasks([...tasks, task]);
  };

  const handleUpdateTaskStatus = (taskId: string, newStatus: Task['status']) => {
    setTasks(tasks.map(t => t.id === taskId ? { ...t, status: newStatus } : t));

    // Auto update project progress
    const task = tasks.find(t => t.id === taskId);
    if(task) {
      const projectTasks = tasks.filter(t => t.projectId === task.projectId);
      // We need to account for the update we just made, but state hasn't flushed yet
      // So let's calculate based on current map logic
      const updatedProjectTasks = projectTasks.map(t => t.id === taskId ? { ...t, status: newStatus } : t);
      const doneCount = updatedProjectTasks.filter(t => t.status === 'done').length;
      const progress = Math.round((doneCount / updatedProjectTasks.length) * 100) || 0;

      setProjects(prev => prev.map(p => p.id === task.projectId ? { ...p, progress } : p));
    }
  };

  const handleDeleteTask = (taskId: string) => {
    setTasks(tasks.filter(t => t.id !== taskId));
  };

  // --- Render ---

  const renderContent = () => {
    const isAdmin = user.role === 'admin' || user.role === 'manager';

    switch (currentView) {
      case 'dashboard':
        return <Dashboard user={user} />;

      case 'attendance':
        return (
          <AttendancePage 
            currentUser={user}
            users={users}
            leaveRequests={leaveRequests}
            attendanceRecords={attendanceRecords}
            onAddLeaveRequest={handleAddLeaveRequest}
            onUpdateLeaveStatus={handleUpdateLeaveStatus}
