          </div>
          <div>
             <label className="block text-sm font-bold text-slate-700 mb-1">Description</label>
             <textarea required rows={2} className="w-full px-3 py-2 border rounded-lg" value={projectForm.description} onChange={e => setProjectForm({...projectForm, description: e.target.value})} />
          </div>
          <div className="grid grid-cols-2 gap-4">
             <div>
