import React from 'react';

export interface User {
  id: string;
  username: string;
  email: string;
  role: string;
  status: 'active' | 'inactive';
  lastLogin: string;
  avatar?: string;

  // Extended Details
  firstName?: string;
  lastName?: string;
  phone?: string;
  department?: string;
  position?: string;
  location?: string;
  joinDate?: string;
  bio?: string;

  // Preferences
  preferences?: {
    theme?: 'light' | 'dark';
    notifications?: boolean;
    dashboardLayout?: string[];
  };
}

export interface AuthState {
  isAuthenticated: boolean;
  user: User | null;
}

export interface NavItem {
  id: string;
  label: string;
  icon: React.ReactNode;
}

export interface Role {
  id: string;
  name: string;
  description: string;
  permissions: string[];
  isSystem?: boolean;
}

export interface Department {
  id: string;
  name: string;
  description?: string;
}

export interface Permission {
  id: string;
  label: string;
  description: string;
}

// --- Attendance & Leave ---

export type LeaveStatus = 'pending' | 'approved' | 'rejected';
export type LeaveType = 'sick' | 'vacation' | 'personal' | 'emergency';

export interface LeaveRequest {
  id: string;
  userId: string;
  startDate: string; // YYYY-MM-DD
  endDate: string;   // YYYY-MM-DD
  type: LeaveType;
  reason: string;
  status: LeaveStatus;
  adminComment?: string;
  createdAt: string;
}

export interface AttendanceRecord {
  id: string;
  userId: string;
  date: string; // YYYY-MM-DD
  status: 'present' | 'absent' | 'leave' | 'holiday' | 'weekend';
  checkIn?: string; // HH:MM
  checkOut?: string; // HH:MM
}

export interface PerformanceReview {
  id: string;
  userId: string;
  date: string;
  rating: number; // 1-5
  comment: string;
  reviewer: string;
}

// --- Project Management ---

export type TaskStatus = 'todo' | 'in-progress' | 'testing' | 'pending-approval' | 'done';
export type TaskPriority = 'low' | 'medium' | 'high' | 'urgent';

export interface TimeLogEntry {
  status: 'in-progress' | 'testing';
  start: number; // Timestamp
  end?: number;  // Timestamp
}

export interface Project {
  id: string;
  name: string;
  description: string;
  status: 'active' | 'completed' | 'on-hold';
  startDate: string;
  endDate: string;
  managerId: string;
  teamMemberIds: string[];
  progress: number; // 0-100
}

export interface Task {
  id: string;
  projectId: string;
  title: string;
  description: string;
  status: TaskStatus;
  priority: TaskPriority;
  assignedTo: string[]; // Array of User IDs
  dueDate: string;
  createdAt: string;
  createdBy: string; // User ID (Admin/Manager)

  // Time Tracking
  timeLogs: TimeLogEntry[];
  isPaused: boolean; 
}

