    setTasks(tasks.filter(t => t.id !== taskId));
  };

  // --- Render ---

  const renderContent = () => {
    const isAdmin = user.role === 'admin' || user.role === 'manager';

    switch (currentView) {
      case 'dashboard':
        return <Dashboard user={user} tasks={tasks} />;

      case 'attendance':
        return (
          <AttendancePage 
            currentUser={user}
            users={users}
            leaveRequests={leaveRequests}
            attendanceRecords={attendanceRecords}
            onAddLeaveRequest={handleAddLeaveRequest}
            onUpdateLeaveStatus={handleUpdateLeaveStatus}
            onDeleteLeaveRequest={handleDeleteLeaveRequest}
            onUpdateAttendance={handleUpdateAttendance}
          />
        );

      case 'projects':
        return (
          <ProjectManagement 
            currentUser={user}
            users={users}
            projects={projects}
            tasks={tasks}
            onAddProject={handleAddProject}
            onDeleteProject={handleDeleteProject}
            onAddTask={handleAddTask}
            onUpdateTask={handleUpdateTask}
            onDeleteTask={handleDeleteTask}
          />
        );

      case 'users':
        if (!isAdmin) return <AccessDenied />;
        return (
          <UserManagement 
            users={users}
            roles={roles}
            departments={departments} 
            onAddUser={handleAddUser}
            onEditUser={handleEditUser}
            onDeleteUser={handleDeleteUser}
            onViewUser={handleViewUser}
            onAddRole={handleAddRole}
            onDeleteRole={handleDeleteRole}
            onAddDepartment={handleAddDepartment}
            onDeleteDepartment={handleDeleteDepartment}
          />
        );

      case 'user-details':
        if (!selectedUser) return <div className="text-center p-10">User not found</div>;
        if (!isAdmin && selectedUser.id !== user.id) return <AccessDenied />;

        return (
          <UserDetails 
            user={selectedUser} 
            onBack={() => setCurrentView('users')}
            onEdit={(u) => {
              if (isAdmin) setCurrentView('users');
            }}
            attendanceHistory={attendanceRecords.filter(r => r.userId === selectedUser.id)}
            leaveHistory={leaveRequests.filter(r => r.userId === selectedUser.id)}
            performanceHistory={performanceReviews.filter(r => r.userId === selectedUser.id)}
            tasks={tasks.filter(t => t.assignedTo.includes(selectedUser.id))}
          />
        );

      case 'settings':
        return <SettingsPage user={user} onUpdateUser={(updates) => {
          console.log('Update user preferences:', updates);
        }} />;

      default:
        // Handle views that are not allowed for standard users
        if (!isAdmin && ['analytics', 'reports', 'security'].includes(currentView)) {
          return <AccessDenied />;
        }
        return (
          <div className="flex items-center justify-center h-96 text-slate-400">
            <p>Module "{currentView}" is currently under development.</p>
          </div>
        );
    }
  };

  // Access Denied Component
  const AccessDenied = () => (
    <div className="flex flex-col items-center justify-center h-full py-20 text-center">
      <div className="w-16 h-16 bg-red-50 text-red-500 rounded-full flex items-center justify-center mb-4">
        <Lock size={32} />
      </div>
      <h2 className="text-2xl font-bold text-slate-900 mb-2">Access Denied</h2>
      <p className="text-slate-500 max-w-md">
        You do not have permission to view this page. Please contact your system administrator if you believe this is an error.
      </p>
      <Button variant="secondary" className="mt-6" onClick={() => setCurrentView('dashboard')}>
        Return to Dashboard
      </Button>
    </div>
  );

  return (
    <div className="h-screen bg-slate-50 flex overflow-hidden">
      <Sidebar 
        currentView={currentView === 'user-details' ? 'users' : currentView} 
        onChangeView={setCurrentView}
        userRole={user.role}
      />

      <main className="flex-1 md:ml-64 transition-all h-full overflow-y-auto">
        <header className="sticky top-0 z-10 bg-white/80 backdrop-blur-md border-b border-slate-200 px-6 py-3 shadow-sm">
          <div className="flex items-center justify-between">
            <div className="hidden sm:flex items-center bg-slate-100/50 rounded-full px-4 py-2 w-64 border border-transparent focus-within:border-primary-300 focus-within:bg-white focus-within:ring-2 focus-within:ring-primary-100 transition-all">
              <Search className="w-4 h-4 text-slate-400 mr-2" />
              <input 
                type="text" 
                placeholder="Global Search..." 
                className="bg-transparent border-none outline-none text-sm w-full placeholder-slate-400 text-slate-700"
              />
            </div>

            <div className="flex sm:hidden font-bold text-slate-800">ET-TOOL-V2</div>

            <div className="flex items-center space-x-4">
              <button className="relative p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition-colors">
                <Bell size={20} />
