  const handleResumeTask = (task: Task) => {
    // Validation: Check if any assignee has a running task
    for (const userId of task.assignedTo) {
      const activeTask = getActiveTaskForUser(userId);
      if (activeTask) {
        setAlertModal({
          isOpen: true,
          title: 'Task Conflict',
          message: `${users.find(u => u.id === userId)?.username || 'User'} is already working on task "${activeTask.title}". They must complete their current task or submit it for approval before resuming another.`
        });
        return;
      }
    }

    const lastLog = task.timeLogs?.[task.timeLogs.length - 1];
    if (lastLog?.status === 'in-progress' || lastLog?.status === 'testing') {
      // Find the last in-progress or testing log entry
      const lastLogIndex = task.timeLogs.findLastIndex(log => log.status === 'in-progress' || log.status === 'testing');

      if (lastLogIndex !== -1) {
        const updatedTimeLogs = [...(task.timeLogs || [])];
        const updatedLog = { ...updatedTimeLogs[lastLogIndex], end: Date.now() };

        updatedTimeLogs[lastLogIndex] = updatedLog;

        onUpdateTask(task.id, {
          isPaused: false,
          timeLogs: updatedTimeLogs
        });
      }
    }
  };
```


