             View All Activity
           </button>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { User, LeaveRequest, AttendanceRecord, Holiday } from '../types';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import ConfirmationModal from '../components/ui/ConfirmationModal';
import { 
  Calendar as CalendarIcon, CheckCircle, XCircle, Clock, ChevronLeft, ChevronRight, 
  Plus, ShieldAlert, MessageSquare, MapPin, Briefcase, Lock, Fingerprint, FileText
} from 'lucide-react';

interface AttendancePageProps {
  currentUser: User;
  users: User[];
  leaveRequests: LeaveRequest[];
  attendanceRecords: AttendanceRecord[];
  onAddLeaveRequest: (request: Omit<LeaveRequest, 'id' | 'status' | 'createdAt'>) => void;
  onUpdateLeaveStatus: (id: string, status: 'approved' | 'rejected', comment?: string) => void;
  onDeleteLeaveRequest: (id: string) => void;
  onUpdateAttendance: (record: AttendanceRecord) => void;
}

const AttendancePage: React.FC<AttendancePageProps> = ({
  currentUser,
  users,
  leaveRequests,
  attendanceRecords,
  onAddLeaveRequest,
  onUpdateLeaveStatus,
  onDeleteLeaveRequest,
  onUpdateAttendance
}) => {
  const isAdmin = currentUser.role === 'admin' || currentUser.role === 'manager';
  const [activeTab, setActiveTab] = useState<'calendar' | 'my_stats' | 'requests' | 'admin_overview'>('calendar');
  const [currentDate, setCurrentDate] = useState(new Date());
  const [now, setNow] = useState(new Date());

  // --- Clock & Timer ---
  useEffect(() => {
    const timer = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // --- Mock Holidays ---
  const [holidays] = useState<Holiday[]>([
    { id: 'h1', date: '2023-11-24', name: 'Thanksgiving', type: 'national' },
    { id: 'h2', date: '2023-12-25', name: 'Christmas', type: 'national' },
    { id: 'h3', date: '2023-12-31', name: 'Year End Closure', type: 'company' },
  ]);

  // --- Modals ---
  const [isLeaveModalOpen, setIsLeaveModalOpen] = useState(false);
  const [isCorrectionModalOpen, setIsCorrectionModalOpen] = useState(false);
  const [correctionForm, setCorrectionForm] = useState({ date: '', checkIn: '', checkOut: '', reason: '' });

  const [confirmModal, setConfirmModal] = useState<{isOpen: boolean, action: () => void, message: string}>({isOpen: false, action: () => {}, message: ''});
  const [leaveForm, setLeaveForm] = useState({ startDate: '', endDate: '', type: 'sick', reason: '' });

  // Admin Modals
  const [rejectModal, setRejectModal] = useState<{isOpen: boolean, req: LeaveRequest | null}>({isOpen: false, req: null});
  const [rejectionReason, setRejectionReason] = useState('');
  const [adminManualEntryModal, setAdminManualEntryModal] = useState({ isOpen: false, userId: '', date: '', checkIn: '', checkOut: '', status: 'present' });

  // --- Attendance Logic ---

  const todayStr = now.toLocaleDateString('en-CA', { timeZone: 'Asia/Kolkata' }); // YYYY-MM-DD
  const myTodayRecord = attendanceRecords.find(r => r.userId === currentUser.id && r.date === todayStr);

  const handleCheckIn = () => {
    // Force IST for Check-in
    const timeStr = now.toLocaleTimeString('en-IN', { timeZone: 'Asia/Kolkata', hour12: false, hour: '2-digit', minute: '2-digit' });

    // Auto-calculate Late status (Example: Late after 09:15)
    let status: any = 'present';

    // Parse the IST time
    const [h, m] = timeStr.split(':').map(Number);
    if (h > 9 || (h === 9 && m > 15)) status = 'late';

    const newRecord: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      userId: currentUser.id,
      date: todayStr,
      status: status,
      checkIn: timeStr,
      location: 'Office HQ (IP: 192.168.1.55)', // Simulated
      totalHours: 0
    };
    onUpdateAttendance(newRecord);
  };

  const handleCheckOut = () => {
    if (!myTodayRecord || !myTodayRecord.checkIn) return;

    // Force IST for Check-out
    const timeStr = now.toLocaleTimeString('en-IN', { timeZone: 'Asia/Kolkata', hour12: false, hour: '2-digit', minute: '2-digit' });

    // Calculate Duration
    const [inH, inM] = myTodayRecord.checkIn.split(':').map(Number);
    const [outH, outM] = timeStr.split(':').map(Number);

    // Create simple date objects for math (using same day)
    const start = new Date(0, 0, 0, inH, inM, 0);
    const end = new Date(0, 0, 0, outH, outM, 0);

    const diffMs = end.getTime() - start.getTime();
    const diffHrs = diffMs / (1000 * 60 * 60);

    // Determine Status Adjustments
    let status = myTodayRecord.status;
    let overtime = 0;

    if (diffHrs < 4.5) status = 'half-day'; // Logic: < 4.5 hrs is half day
    if (diffHrs > 9) overtime = diffHrs - 9; // Logic: > 9 hrs is OT

    onUpdateAttendance({
      ...myTodayRecord,
      checkOut: timeStr,
      totalHours: parseFloat(diffHrs.toFixed(2)),
      overtimeHours: parseFloat(overtime.toFixed(2)),
      status: status
    });
  };

  const handleCorrectionSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // In a real app, this creates a Request object. 
    // Here we update the record but mark it as "correctionRequested" for visual indication.
    // For simplicity in this demo, we assume the system creates a "pending" record.
    alert('Correction request submitted to Admin for approval.');
    setIsCorrectionModalOpen(false);
  };

  const handleAdminManualSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    // Manual Admin Entry logic
    const { userId, date, checkIn, checkOut, status } = adminManualEntryModal;

    // Simple duration calc
    let total = 0;
    if (checkIn && checkOut) {
       const [h1, m1] = checkIn.split(':').map(Number);
       const [h2, m2] = checkOut.split(':').map(Number);
       total = (h2 + m2/60) - (h1 + m1/60);
    }

    onUpdateAttendance({
      id: Math.random().toString(36).substr(2, 9),
      userId,
      date,
      status: status as any,
      checkIn,
      checkOut,
      totalHours: parseFloat(total.toFixed(2)),
      isLocked: true // Admin entries are auto-verified
    });
    setAdminManualEntryModal({ ...adminManualEntryModal, isOpen: false });
  };

  const handleLockPayroll = () => {
    setConfirmModal({
      isOpen: true,
      message: `Are you sure you want to LOCK attendance for ${currentDate.toLocaleString('default', { month: 'long' })}? No further edits will be allowed.`,
      action: () => {
         // Loop through displayed records and set isLocked = true
         alert('Payroll Locked Successfully. Reports generated.');
         setConfirmModal(prev => ({...prev, isOpen: false}));
      }
    });
  };

  // --- Render Helpers ---

  const getDaysInMonth = (date: Date) => new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  const getFirstDayOfMonth = (date: Date) => new Date(date.getFullYear(), date.getMonth(), 1).getDay();
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));

  // --- Render Calendar ---

  const renderCalendar = () => {
    const daysInMonth = getDaysInMonth(currentDate);
    const firstDay = getFirstDayOfMonth(currentDate);
    const days = [];
    const monthName = currentDate.toLocaleString('default', { month: 'long', year: 'numeric' });

    for (let i = 0; i < firstDay; i++) {
      days.push(<div key={`empty-${i}`} className="h-28 bg-dark-900/50 border border-dark-800"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
      const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;

      const attendance = attendanceRecords.find(r => r.userId === currentUser.id && r.date === dateStr);
      const leave = leaveRequests.find(r => r.userId === currentUser.id && r.startDate <= dateStr && r.endDate >= dateStr && r.status === 'approved');
      const holiday = holidays.find(h => h.date === dateStr);

      let bgClass = 'bg-dark-800 hover:bg-dark-700';
      let borderClass = 'border-dark-700';
      let statusText = '';

      if (holiday) {
        bgClass = 'bg-purple-900/20 hover:bg-purple-900/30';
        borderClass = 'border-purple-800';
        statusText = `🎉 ${holiday.name}`;
      } else if (leave) {
        bgClass = 'bg-amber-900/20 hover:bg-amber-900/30';
        borderClass = 'border-amber-800';
        statusText = 'On Leave';
      } else if (attendance) {
         if (attendance.status === 'present') { bgClass = 'bg-emerald-900/20'; borderClass = 'border-emerald-800'; statusText = 'Present'; }
         if (attendance.status === 'late') { bgClass = 'bg-orange-900/20'; borderClass = 'border-orange-800'; statusText = 'Late Entry'; }
         if (attendance.status === 'half-day') { bgClass = 'bg-yellow-900/20'; borderClass = 'border-yellow-800'; statusText = 'Half Day'; }
         if (attendance.status === 'absent') { bgClass = 'bg-red-900/20'; borderClass = 'border-red-800'; statusText = 'Absent'; }
      }

      days.push(
        <div key={d} className={`h-28 border ${borderClass} p-2 relative transition-all group ${bgClass}`}>
          <span className="text-sm font-bold text-slate-300 group-hover:text-white">{d}</span>

          <div className="mt-2 space-y-1">
             {statusText && (
                <div className={`text-[10px] font-bold px-1.5 py-0.5 rounded w-fit ${
                   statusText === 'Present' ? 'text-emerald-400 bg-emerald-950/50' :
                   statusText.includes('Holiday') ? 'text-purple-400 bg-purple-950/50' :
                   statusText === 'On Leave' ? 'text-amber-400 bg-amber-950/50' :
                   statusText === 'Late Entry' ? 'text-orange-400 bg-orange-950/50' :
                   'text-red-400 bg-red-950/50'
                }`}>
                  {statusText}
                </div>
             )}
             {attendance?.checkIn && (
               <div className="text-[10px] text-slate-400 flex items-center gap-1">
                 <Clock size={10} /> {attendance.checkIn} - {attendance.checkOut || '...'}
               </div>
             )}
             {attendance?.totalHours ? (
               <div className="text-[10px] text-slate-500">
                 {attendance.totalHours} hrs {attendance.overtimeHours ? `(+${attendance.overtimeHours} OT)` : ''}
               </div>
             ) : null}
          </div>
        </div>
      );
    }

    return (
      <div className="bg-dark-900 rounded-2xl shadow-xl border border-dark-700 overflow-hidden">
        <div className="flex items-center justify-between p-5 border-b border-dark-700 bg-dark-800/50">
           <h2 className="text-xl font-bold text-white flex items-center gap-2">
             <CalendarIcon className="text-primary-500" />
             {monthName}
           </h2>
           <div className="flex gap-2">
             <Button variant="secondary" onClick={prevMonth} className="p-2 border-dark-600 text-slate-300 hover:text-white"><ChevronLeft size={16} /></Button>
             <Button variant="secondary" onClick={nextMonth} className="p-2 border-dark-600 text-slate-300 hover:text-white"><ChevronRight size={16} /></Button>
           </div>
        </div>
        <div className="grid grid-cols-7 text-center bg-dark-800 border-b border-dark-700">
          {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
            <div key={day} className="py-3 text-xs font-bold text-slate-500 uppercase tracking-wider">{day}</div>
          ))}
        </div>
        <div className="grid grid-cols-7 bg-dark-900">
          {days}
        </div>
      </div>
    );
  };

  const renderStats = () => {
    // Calculate Stats for current month
    const userRecords = attendanceRecords.filter(r => r.userId === currentUser.id && r.date.startsWith(`${currentDate.getFullYear()}-${String(currentDate.getMonth()+1).padStart(2,'0')}`));
    const daysPresent = userRecords.filter(r => ['present', 'late', 'half-day'].includes(r.status)).length;
    const totalHours = userRecords.reduce((acc, curr) => acc + (curr.totalHours || 0), 0);
    const totalOT = userRecords.reduce((acc, curr) => acc + (curr.overtimeHours || 0), 0);
    const lateDays = userRecords.filter(r => r.status === 'late').length;

    return (
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
         <div className="p-4 rounded-xl bg-dark-800 border border-dark-700">
            <p className="text-xs font-bold text-slate-500 uppercase">Days Present</p>
            <p className="text-2xl font-bold text-white mt-1">{daysPresent} <span className="text-sm text-slate-500 font-normal">/ {getDaysInMonth(currentDate)}</span></p>
         </div>
         <div className="p-4 rounded-xl bg-dark-800 border border-dark-700">
            <p className="text-xs font-bold text-slate-500 uppercase">Total Hours</p>
            <p className="text-2xl font-bold text-primary-400 mt-1">{totalHours.toFixed(1)} <span className="text-sm text-slate-500 font-normal">hrs</span></p>
         </div>
         <div className="p-4 rounded-xl bg-dark-800 border border-dark-700">
            <p className="text-xs font-bold text-slate-500 uppercase">Overtime</p>
            <p className="text-2xl font-bold text-emerald-400 mt-1">{totalOT.toFixed(1)} <span className="text-sm text-slate-500 font-normal">hrs</span></p>
         </div>
         <div className="p-4 rounded-xl bg-dark-800 border border-dark-700">
            <p className="text-xs font-bold text-slate-500 uppercase">Late Arrivals</p>
            <p className="text-2xl font-bold text-orange-400 mt-1">{lateDays}</p>
         </div>
      </div>
    );
  };

  const renderAdminOverview = () => {
    const daysInMonth = getDaysInMonth(currentDate);
    const dateHeaders = [];
    for(let i=1; i<=daysInMonth; i++) dateHeaders.push(i);

    return (
      <div className="space-y-6">
        <div className="flex flex-col sm:flex-row justify-between items-end sm:items-center gap-4">
           <div>
             <h2 className="text-lg font-bold text-white">Attendance Master Sheet</h2>
             <p className="text-sm text-slate-400">{currentDate.toLocaleString('default', { month: 'long', year: 'numeric' })}</p>
           </div>
           <div className="flex gap-3">
             <Button variant="secondary" onClick={() => setAdminManualEntryModal({...adminManualEntryModal, isOpen: true})}>
               <Plus size={16} className="mr-2" /> Manual Entry
             </Button>
             <Button variant="primary" className="bg-red-600 hover:bg-red-700 border-none text-white" onClick={handleLockPayroll}>
               <Lock size={16} className="mr-2" /> Lock Month (Payroll)
             </Button>
           </div>
        </div>

        <div className="bg-dark-800 rounded-xl shadow-lg border border-dark-700 overflow-x-auto custom-scrollbar">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-dark-900/50">
                <th className="p-3 sticky left-0 bg-dark-900 z-10 border-r border-dark-700 min-w-[200px] text-xs font-bold text-slate-400 uppercase">Employee</th>
                {dateHeaders.map(d => (
                  <th key={d} className="p-2 min-w-[40px] text-center text-xs font-bold text-slate-500 border-r border-dark-700/50">{d}</th>
                ))}
              </tr>
            </thead>
            <tbody className="divide-y divide-dark-700">
              {users.map(user => (
                <tr key={user.id} className="hover:bg-white/5 transition-colors">
                  <td className="p-3 sticky left-0 bg-dark-800 border-r border-dark-700 flex items-center gap-2">
                     <div className="w-8 h-8 rounded-full bg-dark-700 overflow-hidden border border-dark-600">
                       <img src={user.avatar || `https://ui-avatars.com/api/?name=${user.username}`} alt="" className="w-full h-full object-cover" />
                     </div>
                     <div>
                       <div className="text-sm font-bold text-slate-200">{user.username}</div>
                       <div className="text-[10px] text-slate-500 uppercase">{user.role}</div>
                     </div>
                  </td>
                  {dateHeaders.map(d => {
                    const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
                    const record = attendanceRecords.find(r => r.userId === user.id && r.date === dateStr);
                    const leave = leaveRequests.find(r => r.userId === user.id && r.startDate <= dateStr && r.endDate >= dateStr && r.status === 'approved');
                    const holiday = holidays.find(h => h.date === dateStr);

                    let content = <span className="text-dark-700">·</span>;
                    let bgColor = '';

                    if (holiday) {
                       content = <span className="text-purple-500 font-bold text-xs" title={holiday.name}>H</span>;
                       bgColor = 'bg-purple-900/10';
                    } else if (leave) {
                      content = <span className="text-amber-500 font-bold text-xs" title="Leave">L</span>;
                      bgColor = 'bg-amber-900/10';
                    } else if (record) {
                      if (record.status === 'present') { content = <span className="text-emerald-500 font-bold text-xs">P</span>; bgColor = 'bg-emerald-900/10'; }
                      if (record.status === 'late') { content = <span className="text-orange-500 font-bold text-xs">LT</span>; bgColor = 'bg-orange-900/10'; }
                      if (record.status === 'half-day') { content = <span className="text-yellow-500 font-bold text-xs">HD</span>; bgColor = 'bg-yellow-900/10'; }
                      if (record.status === 'absent') { content = <span className="text-red-500 font-bold text-xs">A</span>; bgColor = 'bg-red-900/10'; }
                    }

                    return (
                      <td key={d} className={`text-center border-r border-dark-700/50 p-1 ${bgColor}`}>
                        {content}
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    );
  };

  // --- Main Render ---

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">

      {/* Top Bar: Live Clock & Actions */}
      <div className="glass-card rounded-2xl p-6 flex flex-col md:flex-row justify-between items-center gap-6">
         <div>
            <h1 className="text-3xl font-black text-white tracking-tight">EETTI <span className="text-primary-500">Attendance</span></h1>
            <p className="text-slate-400 mt-1 flex items-center gap-2">
              <MapPin size={14} /> Corporate Office HQ • {now.toLocaleDateString('en-IN', { timeZone: 'Asia/Kolkata', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
            </p>
         </div>

         {/* Punch Clock Widget */}
         <div className="flex items-center gap-6 bg-dark-900/50 p-4 rounded-xl border border-dark-700">
            <div className="text-right">
               <div className="text-3xl font-mono font-bold text-white tabular-nums tracking-wider">
                 {now.toLocaleTimeString('en-IN', { timeZone: 'Asia/Kolkata', hour12: false })}
               </div>
               <div className="text-xs text-slate-500 uppercase tracking-widest font-bold">IST (Asia/Kolkata)</div>
            </div>
            <div className="h-10 w-px bg-dark-700"></div>
            <div>
              {myTodayRecord?.checkIn && !myTodayRecord.checkOut ? (
                 <Button onClick={handleCheckOut} className="bg-red-600 hover:bg-red-500 text-white border-none shadow-[0_0_15px_rgba(220,38,38,0.4)]">
                   <Briefcase className="mr-2" size={18} /> Check Out
                 </Button>
              ) : myTodayRecord?.checkOut ? (
                 <div className="px-4 py-2 bg-emerald-900/30 border border-emerald-800 text-emerald-400 rounded-lg flex items-center">
                    <CheckCircle className="mr-2" size={18} /> Day Complete
                 </div>
              ) : (
                 <Button onClick={handleCheckIn} className="bg-primary-500 hover:bg-primary-400 text-black font-bold border-none shadow-[0_0_15px_rgba(234,179,8,0.4)]">
                   <Fingerprint className="mr-2" size={18} /> Check In
                 </Button>
              )}
            </div>
         </div>
      </div>

      {/* Main Tabs */}
