           </button>
           <button onClick={() => setActiveTab('requests')} className={`px-6 py-4 text-sm font-bold border-b-2 transition-colors ${activeTab === 'requests' ? 'border-primary-500 text-primary-400' : 'border-transparent text-slate-500 hover:text-slate-300'}`}>
