        {activeTab === 'calendar' && (
          <div className="space-y-6">
             {renderStats()}
             <div className="flex justify-end mb-2">
               <Button variant="secondary" onClick={() => setIsCorrectionModalOpen(true)} className="text-xs">
                 Request Correction
