                  </div>
                  <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Status</label>
                    <select className="w-full p-2 border border-slate-300 rounded-lg" value={userForm.status} onChange={e => setUserForm({...userForm, status: e.target.value as any})}>
                      <option value="active">Active</option>
                      <option value="inactive">Inactive</option>
                      <option value="suspended">Suspended</option>
                    </select>
                  </div>
               </div>
            </div>
          )}

          {/* TAB 4: INTERN DETAILS (Conditional) */}
          {userFormTab === 'intern' && userForm.userType === 'intern' && (
            <div className="space-y-4 bg-orange-50 p-4 rounded-xl border border-orange-100">
               <h4 className="flex items-center gap-2 text-sm font-bold text-orange-800 border-b border-orange-200 pb-2">
                 <Briefcase size={16} /> Internship Specifics
               </h4>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div>
                    <label className="block text-xs font-bold text-orange-800 uppercase mb-1">Internship Type</label>
                    <select className="w-full p-2 border border-orange-200 rounded-lg" value={userForm.internDetails?.type} onChange={e => setUserForm({...userForm, internDetails: {...userForm.internDetails!, type: e.target.value as any}})}>
                      <option value="paid">Paid</option>
