                      <input type="number" className="w-full pl-8 p-2 border border-orange-200 rounded-lg" value={userForm.internDetails?.stipendAmount || ''} onChange={e => setUserForm({...userForm, internDetails: {...userForm.internDetails!, stipendAmount: parseFloat(e.target.value)}})} />
                    </div>
                 </div>
                 <div>
                    <label className="block text-xs font-bold text-orange-800 uppercase mb-1">Start Date</label>
                    <input type="date" className="w-full p-2 border border-orange-200 rounded-lg" value={userForm.internDetails?.startDate || ''} onChange={e => setUserForm({...userForm, internDetails: {...userForm.internDetails!, startDate: e.target.value}})} />
                 </div>
                 <div>
                    <label className="block text-xs font-bold text-orange-800 uppercase mb-1">End Date (Auto Expiry) *</label>
                    <input required type="date" className="w-full p-2 border border-orange-200 rounded-lg bg-white" value={userForm.internDetails?.endDate || ''} onChange={e => setUserForm({...userForm, internDetails: {...userForm.internDetails!, endDate: e.target.value}})} />
                 </div>
                 <div>
                    <label className="block text-xs font-bold text-orange-800 uppercase mb-1">Mentor</label>
                    <select className="w-full p-2 border border-orange-200 rounded-lg" value={userForm.internDetails?.mentorId || ''} onChange={e => setUserForm({...userForm, internDetails: {...userForm.internDetails!, mentorId: e.target.value}})}>
                      <option value="">Assign Mentor</option>
                      {users.filter(u => u.userType === 'employee').map(u => (
                        <option key={u.id} value={u.id}>{u.firstName} {u.lastName}</option>
