                    <label className="flex items-center gap-2 cursor-pointer">
                      <input type="checkbox" className="w-4 h-4 text-orange-600 rounded" checked={userForm.internDetails?.conversionEligibility || false} onChange={e => setUserForm({...userForm, internDetails: {...userForm.internDetails!, conversionEligibility: e.target.checked}})} />
