                    <input type="text" className="w-full p-2 border border-slate-300 rounded-lg uppercase" value={userForm.payrollDetails?.pan || ''} onChange={e => setUserForm({...userForm, payrollDetails: {...userForm.payrollDetails!, pan: e.target.value}})} />
