import React from 'react';

// --- Corporate Role Structure ---
export type SystemRole = 
  | 'super_admin' 
  | 'hr_admin' 
  | 'payroll_admin' 
  | 'manager' 
  | 'shift_supervisor' 
  | 'employee' 
  | 'intern' 
  | 'contract' 
  | 'auditor' 
  | 'it_support';

export type PermissionKey = 
  | 'all_access'           // Super Admin Exclusive
  | 'view_dashboard'
  | 'calendar_view'
  | 'calendar_manage'      // Create schedules/events
  | 'user_view'
  | 'user_manage'          // Create/Edit users
  | 'role_manage'          // Configure permissions (Super Admin)
  | 'payroll_view'
  | 'payroll_manage'
  | 'project_view'
  | 'project_manage'
  | 'reports_view'
  | 'security_manage';

export interface User {
  id: string; // System Generated

  // 2.1 Core Identity
  employeeCode: string;
  username: string; // Login ID
  passwordHash?: string; // Simulated encrypted
  firstName: string;
  lastName: string;
  displayName?: string;
  gender: 'male' | 'female' | 'other';
  dateOfBirth: string;
  avatar?: string;

  // 2.2 Contact
  officialEmail: string;
  personalEmail?: string;
  mobileNumber: string;
  emergencyContactName?: string;
  emergencyContactNumber?: string;

  // 2.3 Account Status
  status: 'active' | 'inactive' | 'suspended';
  lastLogin: string;

  // 2.4 Employment
  userType: 'employee' | 'intern' | 'contract' | 'consultant';
  employmentStatus: 'permanent' | 'probation' | 'notice-period' | 'temporary';
  department: string;
  position: string; // Designation
  reportingManagerId?: string;
  workLocation: string;
  workMode: 'office' | 'remote' | 'hybrid';
  joinDate: string;
  exitDate?: string; // For offboarding

  // 2.5 Role & Access
  role: SystemRole; 
  permissionGroup?: string; // ID of custom permission set
  dataVisibilityScope: 'self' | 'team' | 'department' | 'all';

  // 2.6 Attendance Config
  shiftId?: string; // Link to Shift Config
  attendanceMode: 'web' | 'mobile' | 'biometric' | 'all';
  ipRestriction: boolean;

  // 2.8 Intern Specifics
  internDetails?: {
    type: 'paid' | 'unpaid';
    startDate: string;
    endDate: string; // Auto-expiry
    stipendAmount?: number;
    mentorId: string;
    conversionEligibility: boolean;
  };

  // 2.9 Payroll (Restricted View)
  payrollDetails?: {
    salaryType: 'monthly' | 'hourly' | 'stipend';
    bankAccount?: string;
    ifsc?: string;
    pan?: string;
    uan?: string;
    isOvertimeEligible: boolean;
  };

  // 2.10 Audit
  createdBy: string;
  createdAt: string;
  modifiedBy?: string;
  modifiedAt?: string;

  // Legacy/UI props
  bio?: string;
  preferences?: {
    theme?: 'light' | 'dark';
    notifications?: boolean;
    dashboardLayout?: string[];
  };
}

export interface AuthState {
  isAuthenticated: boolean;
  user: User | null;
}

export interface NavItem {
  id: string;
  label: string;
  icon: React.ReactNode;
  requiredPermission?: PermissionKey;
}

export interface Role {
  id: string;
  name: SystemRole | string; // Allow custom strings but strictly typed for system defaults
  displayName: string;
  description: string;
  permissions: PermissionKey[];
  isSystem?: boolean;
}

export interface Department {
  id: string;
  name: string;
  description?: string;
  headOfDepartmentId?: string;
}

export interface Permission {
  id: PermissionKey;
  label: string;
  description: string;
  category: 'core' | 'hr' | 'finance' | 'operations' | 'it';
}

// --- Attendance & Leave ---

export type LeaveStatus = 'pending' | 'approved' | 'rejected';
export type LeaveType = 'sick' | 'vacation' | 'personal' | 'emergency';
export type AttendanceStatus = 'present' | 'absent' | 'leave' | 'holiday' | 'weekend' | 'half-day' | 'late' | 'work-from-home' | 'on-duty';

export interface LeaveRequest {
  id: string;
  userId: string;
  startDate: string; // YYYY-MM-DD
  endDate: string;   // YYYY-MM-DD
  type: LeaveType;
  reason: string;
  status: LeaveStatus;
  adminComment?: string;
  createdAt: string;
}

export interface AttendanceRecord {
  id: string;
  userId: string;
  date: string; // YYYY-MM-DD
  status: AttendanceStatus;

  // Timings
  checkIn?: string; // HH:MM
  checkOut?: string; // HH:MM

  // Calculations
  totalHours?: number; // Duration in hours
  overtimeHours?: number; // Overtime duration

  // Compliance
  isLocked?: boolean; // Payroll lock
  correctionRequested?: boolean;
  correctionReason?: string;

  // Metadata
  location?: string;
  ipAddress?: string;
}

export interface Holiday {
  id: string;
  date: string; // YYYY-MM-DD
  name: string;
  type: 'company' | 'national' | 'restricted';
}

export interface PerformanceReview {
  id: string;
  userId: string;
  date: string;
  rating: number; // 1-5
  comment: string;
  reviewer: string;
}

// --- Project Management ---

export type TaskStatus = 'todo' | 'in-progress' | 'testing' | 'pending-approval' | 'done';
export type TaskPriority = 'low' | 'medium' | 'high' | 'urgent';

export interface TimeLogEntry {
  status: 'in-progress' | 'testing';
  start: number; // Timestamp
  end?: number;  // Timestamp
}

export interface TaskFeedback {
  id: string;
  date: string;
  comment: string;
}

export interface Project {
  id: string;
  name: string;
  description: string;
  status: 'active' | 'completed' | 'on-hold';
  startDate: string;
  endDate: string;
  managerId: string;
  teamMemberIds: string[];
  progress: number; // 0-100
}

export interface Task {
  id: string;
  projectId: string;
  title: string;
  description: string;
  status: TaskStatus;
  priority: TaskPriority;
  assignedTo: string[]; // Array of User IDs
  dueDate: string;
  createdAt: string;
  createdBy: string; // User ID (Admin/Manager)

  // Time Tracking
  timeLogs: TimeLogEntry[];
  isPaused: boolean;
  feedbackHistory?: TaskFeedback[];
}

