            <div className="flex justify-end pt-2">
               <Button type="submit">Submit Application</Button>
            </div>
         </form>
      </Modal>

      <Modal isOpen={isCorrectionModalOpen} onClose={() => setIsCorrectionModalOpen(false)} title="Attendance Correction">
