        {/* Form Tabs */}
        <div className="flex border-b border-slate-200 mb-4 overflow-x-auto">
          <button type="button" onClick={() => setUserFormTab('identity')} className={`px-4 py-2 text-sm font-medium border-b-2 whitespace-nowrap ${userFormTab === 'identity' ? 'border-primary-500 text-primary-700' : 'border-transparent text-slate-500'}`}>1. Identity</button>
          <button type="button" onClick={() => setUserFormTab('contact')} className={`px-4 py-2 text-sm font-medium border-b-2 whitespace-nowrap ${userFormTab === 'contact' ? 'border-primary-500 text-primary-700' : 'border-transparent text-slate-500'}`}>2. Contact & Auth</button>
          <button type="button" onClick={() => setUserFormTab('employment')} className={`px-4 py-2 text-sm font-medium border-b-2 whitespace-nowrap ${userFormTab === 'employment' ? 'border-primary-500 text-primary-700' : 'border-transparent text-slate-500'}`}>3. Employment & Role</button>
          {userForm.userType === 'intern' && (
            <button type="button" onClick={() => setUserFormTab('intern')} className={`px-4 py-2 text-sm font-medium border-b-2 whitespace-nowrap ${userFormTab === 'intern' ? 'border-orange-500 text-orange-700' : 'border-transparent text-slate-500'}`}>4. Intern Details</button>
          )}
          <button type="button" onClick={() => setUserFormTab('payroll')} className={`px-4 py-2 text-sm font-medium border-b-2 whitespace-nowrap ${userFormTab === 'payroll' ? 'border-primary-500 text-primary-700' : 'border-transparent text-slate-500'}`}>5. Payroll & Bank</button>
        </div>

        <div className="flex-1 overflow-y-auto pr-2 pb-4 space-y-4">

          {/* TAB 1: IDENTITY */}
          {userFormTab === 'identity' && (
