                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">First Name *</label>
                <input required type="text" className="w-full p-2 border border-slate-300 rounded-lg" value={userForm.firstName} onChange={e => setUserForm({...userForm, firstName: e.target.value})} />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Last Name *</label>
                <input required type="text" className="w-full p-2 border border-slate-300 rounded-lg" value={userForm.lastName} onChange={e => setUserForm({...userForm, lastName: e.target.value})} />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Employee Code</label>
                <input type="text" className="w-full p-2 bg-slate-100 border border-slate-300 rounded-lg" value={userForm.employeeCode} readOnly />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Gender *</label>
                <select className="w-full p-2 border border-slate-300 rounded-lg" value={userForm.gender} onChange={e => setUserForm({...userForm, gender: e.target.value as any})}>
                  <option value="male">Male</option>
                  <option value="female">Female</option>
                  <option value="other">Other</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Date of Birth *</label>
                <input required type="date" className="w-full p-2 border border-slate-300 rounded-lg" value={userForm.dateOfBirth} onChange={e => setUserForm({...userForm, dateOfBirth: e.target.value})} />
              </div>
            </div>
          )}

          {/* TAB 2: CONTACT */}
          {userFormTab === 'contact' && (
            <div className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Official Email (Login ID) *</label>
                  <input required type="email" className="w-full p-2 border border-slate-300 rounded-lg" value={userForm.officialEmail} onChange={e => setUserForm({...userForm, officialEmail: e.target.value, username: e.target.value})} />
