                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Personal Email</label>
                  <input type="email" className="w-full p-2 border border-slate-300 rounded-lg" value={userForm.personalEmail || ''} onChange={e => setUserForm({...userForm, personalEmail: e.target.value})} />
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Mobile Number *</label>
                  <input required type="tel" className="w-full p-2 border border-slate-300 rounded-lg" value={userForm.mobileNumber} onChange={e => setUserForm({...userForm, mobileNumber: e.target.value})} />
