               </div>
               <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Salary Type</label>
                    <select className="w-full p-2 border border-slate-300 rounded-lg" value={userForm.payrollDetails?.salaryType} onChange={e => setUserForm({...userForm, payrollDetails: {...userForm.payrollDetails!, salaryType: e.target.value as any}})}>
                      <option value="monthly">Monthly Salary</option>
                      <option value="hourly">Hourly Wage</option>
                      <option value="stipend">Stipend</option>
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Bank Account No.</label>
                    <input type="password" placeholder="•••• •••• •••• 1234" className="w-full p-2 border border-slate-300 rounded-lg" value={userForm.payrollDetails?.bankAccount || ''} onChange={e => setUserForm({...userForm, payrollDetails: {...userForm.payrollDetails!, bankAccount: e.target.value}})} />
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">IFSC Code</label>
                    <input type="text" className="w-full p-2 border border-slate-300 rounded-lg uppercase" value={userForm.payrollDetails?.ifsc || ''} onChange={e => setUserForm({...userForm, payrollDetails: {...userForm.payrollDetails!, ifsc: e.target.value}})} />
                  </div>
                  <div>
                    <label className="block text-xs font-bold text-slate-500 uppercase mb-1">PAN Number</label>
                    <input type="text" className="w-full p-2 border border-slate-300 rounded-lg uppercase" value={userForm.payrollDetails?.pan || ''} onChange={e => setUserForm({...userForm, payrollDetails: {...userForm.payrollDetails!, pan: e.target.value}})} />
                  </div>
                  <div className="flex items-center mt-6">
                    <label className="flex items-center gap-2 cursor-pointer">
                      <input type="checkbox" className="w-4 h-4 text-primary-600 rounded" checked={userForm.payrollDetails?.isOvertimeEligible || false} onChange={e => setUserForm({...userForm, payrollDetails: {...userForm.payrollDetails!, isOvertimeEligible: e.target.checked}})} />
                      <span className="text-sm font-medium text-slate-900">Eligible for Overtime Pay</span>
                    </label>
                 </div>
               </div>
             </div>
          )}

        </div>

        {/* Footer Actions */}
        <div className="border-t border-slate-200 pt-4 flex justify-end gap-3 mt-auto">
           <Button type="button" variant="secondary" onClick={() => setIsUserModalOpen(false)}>Cancel</Button>
           <Button type="submit">{editingUserId ? 'Update User Profile' : 'Create Corporate User'}</Button>
