  const [alertModal, setAlertModal] = useState<{isOpen: boolean, title: string, message: string}>({isOpen: false, title: '', message: ''});

  // Rejection Modal State
  const [rejectModal, setRejectModal] = useState<{isOpen: boolean, task: Task | null}>({isOpen: false, task: null});
  const [rejectionReason, setRejectionReason] = useState('');

  // Forms
  const [projectForm, setProjectForm] = useState({
    name: '',
    description: '',
    startDate: '',
    endDate: '',
    teamMemberIds: [] as string[]
  });

  const [taskForm, setTaskForm] = useState({
    title: '',
    description: '',
    priority: 'medium' as TaskPriority,
    assignedTo: [] as string[],
    dueDate: ''
  });

  // --- Filtering ---

  // Super Admin & HR Admin see ALL. Manager sees assigned or managed projects.
  const visibleProjects = isSystemAdmin 
    ? projects 
    : projects.filter(p => p.teamMemberIds.includes(currentUser.id) || p.managerId === currentUser.id);

  const activeProject = projects.find(p => p.id === activeProjectId);

  // --- Helpers ---

  // Check if a specific user has an active task (In Progress OR Testing, and NOT paused)
  const getActiveTaskForUser = (userId: string) => {
    return tasks.find(t => 
      t.assignedTo.includes(userId) && 
      (t.status === 'in-progress' || t.status === 'testing') && 
      !t.isPaused
    );
  };

  // Check if a specific user already has a task in the Testing phase (Status: testing)
  const getTestingTaskForUser = (userId: string) => {
    return tasks.find(t => 
      t.assignedTo.includes(userId) && 
      t.status === 'testing'
    );
  };

  // --- Handlers ---

  const handleCreateProject = (e: React.FormEvent) => {
    e.preventDefault();
    onAddProject({
      ...projectForm,
      status: 'active',
      managerId: currentUser.id,
    });
    setIsProjectModalOpen(false);
    setProjectForm({ name: '', description: '', startDate: '', endDate: '', teamMemberIds: [] });
  };

  const handleCreateTask = (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeProjectId) return;

    // Strict Validation
    if (!taskForm.title.trim()) {
       setAlertModal({ isOpen: true, title: 'Validation Error', message: 'Task Title is required.' });
       return;
    }
    if (!taskForm.description.trim()) {
       setAlertModal({ isOpen: true, title: 'Validation Error', message: 'Task Description is required.' });
       return;
    }
    if (!taskForm.dueDate) {
       setAlertModal({ isOpen: true, title: 'Validation Error', message: 'Due Date & Time is required.' });
       return;
    }
    if (taskForm.assignedTo.length === 0) {
       setAlertModal({ isOpen: true, title: 'Validation Error', message: 'You must assign this task to at least one employee.' });
       return;
    }

    onAddTask({
      ...taskForm,
      projectId: activeProjectId,
      status: 'todo',
    });
    setIsTaskModalOpen(false);
    setTaskForm({ title: '', description: '', priority: 'medium', assignedTo: [], dueDate: '' });
  };

  // Time Tracking Actions
  const handleStartTask = (task: Task) => {
    for (const userId of task.assignedTo) {
      // 1. BLOCK: Check if user has ANY task in 'testing'. 
      const testingTask = getTestingTaskForUser(userId);
      if (testingTask) {
        const busyUser = users.find(u => u.id === userId);
        setAlertModal({
          isOpen: true,
          title: 'Testing Queue Not Empty',
          message: `${busyUser?.username || 'User'} still has a task in Testing ("${testingTask.title}"). They must test and submit it for approval before starting a new task.`
        });
        return;
      }

      // 2. BLOCK: Check if user has another ACTIVE (running) task.
      const activeTask = getActiveTaskForUser(userId);
      if (activeTask && activeTask.id !== task.id) {
        const busyUser = users.find(u => u.id === userId);
        setAlertModal({
          isOpen: true,
          title: 'Resource Busy',
          message: `${busyUser?.username || 'User'} is currently working on "${activeTask.title}". They must place that task on HOLD before starting a new one.`
        });
        return;
      }
    }

    // Move to in-progress and start logging
    const newLog: TimeLogEntry = { status: 'in-progress', start: Date.now() };
    onUpdateTask(task.id, { 
      status: 'in-progress', 
      isPaused: false,
      timeLogs: [...(task.timeLogs || []), newLog] 
    });
  };

  const handlePauseTask = (task: Task) => {
    // Close current log entry
    const logs = [...(task.timeLogs || [])];
    const lastLog = logs[logs.length - 1];
    if (lastLog && !lastLog.end) {
      lastLog.end = Date.now();
    }
    onUpdateTask(task.id, { isPaused: true, timeLogs: logs });
  };

  const handleResumeTask = (task: Task) => {
    for (const userId of task.assignedTo) {
       // 1. BLOCK: Check if user has ANY task in 'testing'. 
       const testingTask = getTestingTaskForUser(userId);

       if (testingTask && testingTask.id !== task.id) {
            const busyUser = users.find(u => u.id === userId);
            setAlertModal({
              isOpen: true,
              title: 'Testing Queue Not Empty',
              message: `${busyUser?.username || 'User'} has a task in Testing ("${testingTask.title}"). They must complete that first.`
            });
            return;
       }

      // 2. BLOCK: Check if user has another ACTIVE (running) task.
      const activeTask = getActiveTaskForUser(userId);
      if (activeTask && activeTask.id !== task.id) {
        const busyUser = users.find(u => u.id === userId);
        setAlertModal({
          isOpen: true,
          title: 'Resource Busy',
          message: `${busyUser?.username || 'User'} is currently working on "${activeTask.title}". They must place that task on HOLD before resuming this one.`
        });
        return;
      }
    }

    // Open new log entry
    const newLog: TimeLogEntry = { 
      status: task.status as 'in-progress' | 'testing', 
      start: Date.now() 
    };
    onUpdateTask(task.id, { isPaused: false, timeLogs: [...(task.timeLogs || []), newLog] });
  };

  const handleMoveToTest = (task: Task) => {
    // 1. Validation: Check if any assignee already has a task in 'testing'
    for (const userId of task.assignedTo) {
      const testingTask = getTestingTaskForUser(userId);
      // If found and it's not the current task
      if (testingTask && testingTask.id !== task.id) {
        const busyUser = users.find(u => u.id === userId);
        setAlertModal({
          isOpen: true,
          title: 'Testing Queue Limit',
          message: `${busyUser?.username || 'User'} already has a task in Testing ("${testingTask.title}"). They must submit it for approval before moving another task to Testing.`
        });
        return;
      }
    }

    // Continuous Timing Logic:
    const logs = [...(task.timeLogs || [])];
    const lastLog = logs[logs.length - 1];
    if (lastLog && !lastLog.end) lastLog.end = Date.now();

    // Start testing log
    logs.push({ status: 'testing', start: Date.now() });

    onUpdateTask(task.id, { status: 'testing', isPaused: false, timeLogs: logs });
  };

  const handleSubmitForApproval = (task: Task) => {
    // Close testing log - Work is done for the employee. Time HOLDS here.
    const logs = [...(task.timeLogs || [])];
    const lastLog = logs[logs.length - 1];
    if (lastLog && !lastLog.end) lastLog.end = Date.now();

    onUpdateTask(task.id, { status: 'pending-approval', isPaused: false, timeLogs: logs });
  };

  const handleAdminAction = (task: Task, action: 'approve' | 'reject') => {
    // DOUBLE CHECK: Only Super Admin or HR Admin can approve
    if (!isSystemAdmin) {
      setAlertModal({ isOpen: true, title: 'Restricted Action', message: 'Only Super Admin or HR Admin can perform final approvals.' });
      return;
    }

    if (action === 'approve') {
       onUpdateTask(task.id, { status: 'done' });
    } else {
       // Open Reject Modal
       setRejectionReason('');
       setRejectModal({ isOpen: true, task });
    }
  };

  const handleConfirmReject = (e: React.FormEvent) => {
    e.preventDefault();
    if (!rejectModal.task) return;

    if (!rejectionReason.trim()) {
      setAlertModal({ isOpen: true, title: 'Required', message: 'Please provide a reason for rejection.' });
      return;
    }

    // Add rejection to history
    const newFeedback: TaskFeedback = {
      id: Date.now().toString(),
      date: new Date().toLocaleString(),
      comment: rejectionReason
    };

    // Reject back to in-progress. 
    onUpdateTask(rejectModal.task.id, { 
      status: 'in-progress', 
      isPaused: true, 
      feedbackHistory: [newFeedback, ...(rejectModal.task.feedbackHistory || [])]
    });

    setRejectModal({ isOpen: false, task: null });
  };


  // --- Components ---

  const ProjectCard: React.FC<{ project: Project }> = ({ project }) => {
    const projTasks = tasks.filter(t => t.projectId === project.id);

    return (
      <div className="bg-white rounded-xl border border-slate-200 p-5 hover:shadow-md transition-shadow relative group">
        <div className="flex justify-between items-start mb-3">
          <div>
            <h3 className="font-bold text-slate-900 text-lg">{project.name}</h3>
            <span className={`inline-flex items-center px-2 py-0.5 rounded text-xs font-medium capitalize mt-1 ${
              project.status === 'active' ? 'bg-emerald-100 text-emerald-800' : 'bg-slate-100 text-slate-600'
            }`}>
              {project.status}
            </span>
          </div>
          {hasManagementAccess && (
            <button 
              onClick={(e) => { e.stopPropagation(); setConfirmModal({isOpen: true, message: `Delete project ${project.name}?`, action: () => onDeleteProject(project.id)}); }}
              className="text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity"
            >
              <Trash2 size={18} />
            </button>
          )}
        </div>

        <p className="text-sm text-slate-500 mb-4 line-clamp-2 min-h-[40px]">{project.description}</p>

        <div className="space-y-4">
          <div>
            <div className="flex justify-between text-xs mb-1">
              <span className="text-slate-500 font-medium">Progress</span>
              <span className="text-slate-700 font-bold">{project.progress}%</span>
            </div>
            <div className="w-full bg-slate-100 rounded-full h-2">
              <div className="bg-primary-600 h-2 rounded-full transition-all" style={{ width: `${project.progress}%` }}></div>
            </div>
          </div>

          {hasManagementAccess && (
             <div className="flex items-center gap-2 text-xs text-slate-600 bg-slate-50 p-2 rounded">
                <Clock size={12} className="text-primary-500" />
                <span>Total Project Time: <LiveProjectTimer tasks={projTasks} /></span>
             </div>
          )}

          <div className="flex justify-between items-center">
            <div className="flex -space-x-2 overflow-hidden">
              {project.teamMemberIds.map(uid => {
                const u = users.find(user => user.id === uid);
                if (!u) return null;
                return (
                  <img 
                    key={uid}
                    className="inline-block h-8 w-8 rounded-full ring-2 ring-white bg-white"
                    src={u.avatar || `https://ui-avatars.com/api/?name=${u.username}`}
                    alt={u.username}
                    title={u.username}
                  />
                )
              })}
            </div>
            <Button 
              variant="secondary" 
              className="text-xs h-8"
              onClick={() => { setActiveProjectId(project.id); setViewMode('board'); }}
            >
              View Board <ArrowRight size={14} className="ml-1" />
            </Button>
          </div>
        </div>
      </div>
    );
  };

  const TaskCard: React.FC<{ task: Task }> = ({ task }) => {
    const isAssigned = task.assignedTo.includes(currentUser.id);
    const canMove = hasManagementAccess || isAssigned;

    // Status Checks
    const isActive = !task.isPaused && (task.status === 'in-progress' || task.status === 'testing');
    const hasRejections = task.feedbackHistory && task.feedbackHistory.length > 0;
    const isCurrentlyRejected = task.status === 'in-progress' && hasRejections && !isActive && task.feedbackHistory?.[0].comment;

    // Render Actions based on Status
    const renderActions = () => {
      if (!canMove) return null;

      // TODO -> IN PROGRESS
      if (task.status === 'todo') {
        return (
          <button onClick={() => handleStartTask(task)} className="mt-3 w-full py-1.5 flex items-center justify-center text-xs font-bold bg-primary-50 text-primary-700 hover:bg-primary-100 rounded transition-colors">
            <Play size={12} className="mr-1" /> Start Task
          </button>
        );
      }

      // IN PROGRESS -> [PAUSE, RESUME, TEST]
      if (task.status === 'in-progress') {
         return (
           <div className="mt-3 grid grid-cols-2 gap-2">
             {task.isPaused ? (
               <button onClick={() => handleResumeTask(task)} className="py-1.5 flex items-center justify-center text-xs font-bold bg-amber-50 text-amber-700 hover:bg-amber-100 rounded transition-colors">
                 <Play size={12} className="mr-1" /> Resume
               </button>
             ) : (
               <button onClick={() => handlePauseTask(task)} className="py-1.5 flex items-center justify-center text-xs font-bold bg-slate-100 text-slate-700 hover:bg-slate-200 rounded transition-colors">
                 <Pause size={12} className="mr-1" /> Hold
               </button>
             )}
             <button 
                onClick={() => handleMoveToTest(task)} 
                disabled={task.isPaused}
                className={`py-1.5 flex items-center justify-center text-xs font-bold rounded transition-colors ${task.isPaused ? 'bg-slate-50 text-slate-300 cursor-not-allowed' : 'bg-indigo-50 text-indigo-700 hover:bg-indigo-100'}`}
             >
               Test &rarr;
             </button>
           </div>
         );
      }

      // TESTING -> APPROVAL
      if (task.status === 'testing') {
         return (
           <button onClick={() => handleSubmitForApproval(task)} className="mt-3 w-full py-1.5 flex items-center justify-center text-xs font-bold bg-amber-50 text-amber-700 hover:bg-amber-100 rounded transition-colors">
             Submit for Approval &rarr;
           </button>
         );
      }

      // PENDING APPROVAL (Restricted to Super Admin / HR Admin)
      if (task.status === 'pending-approval') {
         if (!isSystemAdmin) {
            return (
              <div className="mt-3 bg-slate-100 rounded p-2 text-center border border-slate-200">
                 <ShieldCheck className="mx-auto text-slate-400 mb-1" size={16} />
                 <p className="text-[10px] text-slate-500 font-bold">Waiting for Final Review</p>
                 <p className="text-[9px] text-slate-400">(Super Admin / HR Only)</p>
              </div>
            );
         }
         return (
           <div className="mt-3 grid grid-cols-2 gap-2">
             <button onClick={() => handleAdminAction(task, 'reject')} className="py-1.5 text-xs font-bold bg-red-50 text-red-700 hover:bg-red-100 rounded transition-colors">Reject</button>
             <button onClick={() => handleAdminAction(task, 'approve')} className="py-1.5 text-xs font-bold bg-emerald-50 text-emerald-700 hover:bg-emerald-100 rounded transition-colors">Approve</button>
           </div>
         );
      }

      return null;
    };

    return (
      <div className={`bg-white p-4 rounded-lg shadow-sm border border-slate-200 hover:shadow-md transition-shadow group relative ${task.isPaused ? 'opacity-75 bg-slate-50' : ''} ${isActive ? 'ring-1 ring-primary-500 shadow-primary-500/10' : ''} ${isCurrentlyRejected ? 'border-red-200 bg-red-50/50' : ''}`}>
        {task.isPaused && task.status !== 'todo' && task.status !== 'done' && (
           <div className="absolute top-2 right-2 z-10">
             <span className="text-[10px] font-bold bg-slate-200 text-slate-600 px-1.5 py-0.5 rounded">ON HOLD</span>
           </div>
        )}
        {isActive && (
           <div className="absolute top-2 right-2 z-10 animate-pulse">
             <span className="text-[10px] font-bold bg-primary-100 text-primary-700 px-1.5 py-0.5 rounded flex items-center gap-1">
               <span className="w-1.5 h-1.5 rounded-full bg-primary-500"></span> LIVE
             </span>
           </div>
        )}

        <div className="flex justify-between items-start mb-2">
           <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase border ${getPriorityColor(task.priority)}`}>
             {task.priority}
           </span>
        </div>
        <h4 className="font-bold text-slate-800 text-sm mb-1">{task.title}</h4>
        <p className="text-xs text-slate-500 line-clamp-2 mb-3">{task.description}</p>

        {/* Rejection History Display */}
        {hasRejections && (
           <div className="mb-3 space-y-2">
              <div className="text-[10px] font-bold text-red-700 flex items-center gap-1 border-b border-red-100 pb-1">
                 <MessageSquare size={10} /> Admin Feedback ({task.feedbackHistory!.length}):
              </div>
              <div className="max-h-20 overflow-y-auto space-y-1 custom-scrollbar">
                {task.feedbackHistory!.map((feedback, idx) => (
                  <div key={feedback.id || idx} className="bg-red-50 border border-red-100 rounded p-1.5">
                    <p className="text-xs text-red-800 italic">"{feedback.comment}"</p>
                    <p className="text-[9px] text-red-400 mt-0.5 text-right">{feedback.date}</p>
                  </div>
                ))}
              </div>
           </div>
        )}

        <div className="flex items-center justify-between border-t border-slate-50 pt-2">
           <div className="flex -space-x-1">
             {task.assignedTo.map(uid => {
                const u = users.find(usr => usr.id === uid);
                return u ? (
                  <img key={uid} src={u.avatar} className="w-5 h-5 rounded-full ring-1 ring-white" title={u.username} />
                ) : null;
             })}
           </div>

           {/* Timer Visibility */}
           {(isAssigned || hasManagementAccess) && (
              <div className={`flex items-center text-[10px] px-1.5 py-0.5 rounded font-mono ${isActive ? 'bg-primary-50 text-primary-700 font-bold' : 'bg-slate-50 text-slate-500'}`}>
                <Clock size={10} className="mr-1" />
                <LiveTaskTimer task={task} />
              </div>
           )}
        </div>

        {renderActions()}
      </div>
    );
  };

  const renderKanbanBoard = () => {
    if (!activeProject) return <div>Project not found</div>;

    const projectTasks = tasks.filter(t => t.projectId === activeProjectId);

    const columns: { id: TaskStatus; label: string; color: string }[] = [
      { id: 'todo', label: 'To Do', color: 'bg-slate-100' },
      { id: 'in-progress', label: 'In Progress', color: 'bg-blue-50' },
      { id: 'testing', label: 'Testing', color: 'bg-indigo-50' },
      { id: 'pending-approval', label: 'Approval', color: 'bg-amber-50' },
      { id: 'done', label: 'Done', color: 'bg-emerald-50' },
    ];

    return (
      <div className="h-full flex flex-col">
        {/* Board Header */}
        <div className="flex items-center justify-between mb-4 pb-4 border-b border-slate-200">
           <div>
             <div className="flex items-center gap-2 text-sm text-slate-500 mb-1">
               <button onClick={() => { setActiveProjectId(null); setViewMode('list'); }} className="hover:text-primary-600 hover:underline">Projects</button>
               <ChevronRight size={14} />
               <span>Board</span>
             </div>
             <h2 className="text-2xl font-bold text-slate-900">{activeProject.name}</h2>
           </div>
           <div className="flex gap-2">
             <div className="flex -space-x-2 mr-4">
                {activeProject.teamMemberIds.map(uid => {
                  const u = users.find(usr => usr.id === uid);
                  return u ? <img key={uid} src={u.avatar} className="w-8 h-8 rounded-full border-2 border-white" title={u.username} /> : null;
                })}
             </div>
             {hasManagementAccess && (
               <Button onClick={() => setIsTaskModalOpen(true)}>
                 <Plus size={16} className="mr-2" /> Add Task
               </Button>
             )}
           </div>
        </div>

        {/* Board Columns */}
        <div className="flex-1 overflow-x-auto">
           <div className="flex gap-6 min-w-[1200px] h-full pb-2">
             {columns.map(col => {
               let colTasks = projectTasks.filter(t => t.status === col.id);

               // Sort 'To Do' by Priority
               if (col.id === 'todo') {
                 colTasks.sort((a, b) => getPriorityWeight(b.priority) - getPriorityWeight(a.priority));
               }

               return (
                 <div key={col.id} className="flex-1 flex flex-col min-w-[280px] max-w-[320px] h-full">
                   <div className={`flex items-center justify-between p-3 rounded-t-lg border-b-2 border-white ${col.color}`}>
                      <h3 className="font-bold text-slate-700 text-sm">{col.label}</h3>
                      <span className="bg-white/50 px-2 py-0.5 rounded text-xs font-bold text-slate-600">{colTasks.length}</span>
                   </div>

                   {/* Scrollable Column Content */}
                   <div className={`flex-1 ${col.color} bg-opacity-30 p-3 space-y-3 rounded-b-lg overflow-y-auto min-h-0 custom-scrollbar`}>
                      {colTasks.length === 0 && (
                        <div className="h-24 border-2 border-dashed border-slate-300/50 rounded-lg flex items-center justify-center text-slate-400 text-xs italic">
                          No tasks
                        </div>
                      )}
                      {colTasks.map(task => (
                        <TaskCard key={task.id} task={task} />
                      ))}
                   </div>
                 </div>
               );
             })}
           </div>
        </div>
      </div>
    );
  };

  return (
    <div className="h-full flex flex-col space-y-6 animate-in fade-in duration-500">

      {/* Main Header (Only visible in List Mode) */}
      {!activeProjectId && (
        <div className="flex justify-between items-center">
          <div>
            <h1 className="text-2xl font-bold text-slate-900">Project Management</h1>
            <p className="text-slate-500 mt-1">Manage tasks, timelines, and team approvals.</p>
          </div>
          <div className="flex bg-white p-1 rounded-lg border border-slate-200">
            <button 
              onClick={() => setViewMode('list')} 
              className={`p-2 rounded ${viewMode === 'list' ? 'bg-slate-100 text-slate-900' : 'text-slate-500'}`}
            >
              <Layout size={20} />
            </button>
            {activeProjectId && (
              <button 
                onClick={() => setViewMode('board')} 
                className={`p-2 rounded ${viewMode === 'board' ? 'bg-slate-100 text-slate-900' : 'text-slate-500'}`}
              >
                <Briefcase size={20} />
              </button>
            )}
          </div>
        </div>
      )}

      {/* Content Area */}
      <div className="flex-1 min-h-0">
        {!activeProjectId ? (
          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6 overflow-y-auto max-h-full pb-10">
            {hasManagementAccess && (
              <button 
                onClick={() => setIsProjectModalOpen(true)}
                className="flex flex-col items-center justify-center h-[280px] rounded-xl border-2 border-dashed border-slate-300 hover:border-primary-400 hover:bg-primary-50 transition-all group"
              >
                <div className="w-12 h-12 rounded-full bg-slate-100 group-hover:bg-white flex items-center justify-center mb-3 transition-colors">
                  <Plus className="text-slate-400 group-hover:text-primary-500" />
                </div>
                <span className="font-bold text-slate-500 group-hover:text-primary-600">Create New Project</span>
              </button>
            )}
            {visibleProjects.map(project => (
              <ProjectCard key={project.id} project={project} />
            ))}
          </div>
        ) : renderKanbanBoard()}
      </div>

      {/* --- Modals with High Contrast Inputs --- */}

      <Modal isOpen={isProjectModalOpen} onClose={() => setIsProjectModalOpen(false)} title="Create New Project">
        <form onSubmit={handleCreateProject} className="space-y-4">
          <div>
            <label className="block text-sm font-bold text-slate-700 mb-1">Project Name</label>
            <input required type="text" className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg" value={projectForm.name} onChange={e => setProjectForm({...projectForm, name: e.target.value})} />
          </div>
          <div>
             <label className="block text-sm font-bold text-slate-700 mb-1">Description</label>
             <textarea required rows={2} className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg" value={projectForm.description} onChange={e => setProjectForm({...projectForm, description: e.target.value})} />
          </div>
          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="block text-sm font-bold text-slate-700 mb-1">Start Date</label>
                <input required type="date" className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg" value={projectForm.startDate} onChange={e => setProjectForm({...projectForm, startDate: e.target.value})} />
             </div>
             <div>
                <label className="block text-sm font-bold text-slate-700 mb-1">End Date</label>
                <input required type="date" className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg" value={projectForm.endDate} onChange={e => setProjectForm({...projectForm, endDate: e.target.value})} />
             </div>
          </div>
          <div>
             <label className="block text-sm font-bold text-slate-700 mb-1">Assign Team (Includes Admins)</label>
             <div className="max-h-32 overflow-y-auto border border-slate-300 bg-white rounded-lg p-2 space-y-1">
               {users.map(u => (
                 <label key={u.id} className="flex items-center space-x-2 p-1 hover:bg-slate-50 rounded cursor-pointer">
                   <input 
                     type="checkbox" 
                     className="text-primary-600 focus:ring-primary-500 border-gray-300 rounded"
                     checked={projectForm.teamMemberIds.includes(u.id)}
                     onChange={(e) => {
                       if(e.target.checked) setProjectForm({...projectForm, teamMemberIds: [...projectForm.teamMemberIds, u.id]});
                       else setProjectForm({...projectForm, teamMemberIds: projectForm.teamMemberIds.filter(id => id !== u.id)});
                     }}
                   />
                   <span className="text-sm text-slate-900">
                     {u.username} <span className="text-xs text-slate-500">({u.role})</span>
                   </span>
                 </label>
               ))}
             </div>
          </div>
          <div className="flex justify-end gap-2 pt-2">
             <Button type="button" variant="secondary" onClick={() => setIsProjectModalOpen(false)}>Cancel</Button>
             <Button type="submit">Create Project</Button>
          </div>
        </form>
      </Modal>

      <Modal isOpen={isTaskModalOpen} onClose={() => setIsTaskModalOpen(false)} title="Create New Task">
        <form onSubmit={handleCreateTask} className="space-y-4">
          <div>
            <label className="block text-sm font-bold text-slate-700 mb-1">Task Title <span className="text-red-500">*</span></label>
            <input required type="text" className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg" value={taskForm.title} onChange={e => setTaskForm({...taskForm, title: e.target.value})} />
          </div>
          <div>
             <label className="block text-sm font-bold text-slate-700 mb-1">Description <span className="text-red-500">*</span></label>
             <textarea required rows={2} className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg" value={taskForm.description} onChange={e => setTaskForm({...taskForm, description: e.target.value})} />
          </div>
          <div className="grid grid-cols-2 gap-4">
             <div>
                <label className="block text-sm font-bold text-slate-700 mb-1">Priority <span className="text-red-500">*</span></label>
                <select className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg capitalize" value={taskForm.priority} onChange={e => setTaskForm({...taskForm, priority: e.target.value as TaskPriority})}>
                   <option value="low">Low</option>
                   <option value="medium">Medium</option>
                   <option value="high">High</option>
                   <option value="urgent">Urgent</option>
                </select>
             </div>
             <div>
                <label className="block text-sm font-bold text-slate-700 mb-1">Due Date & Time <span className="text-red-500">*</span></label>
                <input required type="datetime-local" className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg" value={taskForm.dueDate} onChange={e => setTaskForm({...taskForm, dueDate: e.target.value})} />
             </div>
          </div>
          <div>
             <label className="block text-sm font-bold text-slate-700 mb-1">Assign To <span className="text-red-500">*</span></label>
             <div className="border border-slate-300 bg-white rounded-lg p-2 max-h-32 overflow-y-auto">
               {activeProject && users
                 // Include Project Team Members AND the Project Manager (Admin)
                 .filter(u => activeProject.teamMemberIds.includes(u.id) || u.id === activeProject.managerId)
                 .map(u => (
                 <label key={u.id} className="flex items-center space-x-2 p-1 hover:bg-slate-50 rounded cursor-pointer">
                    <input 
                       type="checkbox"
                       className="text-primary-600 focus:ring-primary-500 border-gray-300 rounded"
                       checked={taskForm.assignedTo.includes(u.id)}
                       onChange={(e) => {
                          if(e.target.checked) setTaskForm({...taskForm, assignedTo: [...taskForm.assignedTo, u.id]});
                          else setTaskForm({...taskForm, assignedTo: taskForm.assignedTo.filter(id => id !== u.id)});
                       }}
                    />
                    <div className="flex items-center gap-2">
                       <img src={u.avatar} className="w-5 h-5 rounded-full" />
                       <span className="text-sm text-slate-900">{u.username} <span className="text-xs text-slate-500">({u.role})</span></span>
                    </div>
                 </label>
               ))}
             </div>
          </div>
          <div className="flex justify-end gap-2 pt-2">
             <Button type="button" variant="secondary" onClick={() => setIsTaskModalOpen(false)}>Cancel</Button>
             <Button type="submit">Create Task</Button>
          </div>
        </form>
      </Modal>

      {/* Rejection Reason Modal */}
      <Modal isOpen={rejectModal.isOpen} onClose={() => setRejectModal({...rejectModal, isOpen: false})} title="Reject Task">
        <form onSubmit={handleConfirmReject} className="space-y-4">
          <div className="bg-red-50 border border-red-200 rounded-lg p-3 text-sm text-red-800 flex items-start gap-2">
             <AlertCircle size={16} className="mt-0.5" />
             <p>You are about to reject this task. It will be returned to the "In Progress" status for the employee to review.</p>
          </div>
          <div>
            <label className="block text-sm font-bold text-slate-700 mb-1">Reason for Rejection <span className="text-red-500">*</span></label>
            <textarea
              required
              rows={3}
              value={rejectionReason}
              onChange={(e) => setRejectionReason(e.target.value)}
              className="w-full px-3 py-2 bg-white text-slate-900 border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-red-500"
              placeholder="Explain why the task was rejected..."
            />
          </div>
          <div className="flex justify-end gap-2 mt-2">
            <Button type="button" variant="secondary" onClick={() => setRejectModal({...rejectModal, isOpen: false})}>Cancel</Button>
            <Button type="submit" variant="danger">Confirm Rejection</Button>
          </div>
        </form>
      </Modal>

      <ConfirmationModal 
        isOpen={confirmModal.isOpen}
        onClose={() => setConfirmModal({...confirmModal, isOpen: false})}
        onConfirm={confirmModal.action}
        title="Confirm Deletion"
        message={confirmModal.message}
      />

      <AlertModal 
        isOpen={alertModal.isOpen}
        onClose={() => setAlertModal({...alertModal, isOpen: false})}
        title={alertModal.title}
        message={alertModal.message}
      />
    </div>
  );
};

export default ProjectManagement;

import React, { useState, useEffect } from 'react';
import { User, LeaveRequest, AttendanceRecord, Holiday, CalendarEvent, Department } from '../types';
import Button from '../components/ui/Button';
import Modal from '../components/ui/Modal';
import ConfirmationModal from '../components/ui/ConfirmationModal';
import { 
  Calendar as CalendarIcon, CheckCircle, XCircle, Clock, ChevronLeft, ChevronRight, 
  Plus, ShieldAlert, MessageSquare, MapPin, Briefcase, Lock, Fingerprint, FileText,
  Users, Building, Globe, Zap
} from 'lucide-react';

interface AttendancePageProps {
  currentUser: User;
  users: User[];
  departments: Department[]; // Added
  leaveRequests: LeaveRequest[];
  attendanceRecords: AttendanceRecord[];
  onAddLeaveRequest: (request: Omit<LeaveRequest, 'id' | 'status' | 'createdAt'>) => void;
  onUpdateLeaveStatus: (id: string, status: 'approved' | 'rejected', comment?: string) => void;
  onDeleteLeaveRequest: (id: string) => void;
  onUpdateAttendance: (record: AttendanceRecord) => void;
  canManageCalendar: boolean; 
}

const AttendancePage: React.FC<AttendancePageProps> = ({
  currentUser,
  users,
  departments,
  leaveRequests,
  attendanceRecords,
  onAddLeaveRequest,
  onUpdateLeaveStatus,
  onDeleteLeaveRequest,
  onUpdateAttendance,
  canManageCalendar
}) => {
  const isSystemAdmin = currentUser.role === 'super_admin' || currentUser.role === 'hr_admin';
  const isAdmin = isSystemAdmin || currentUser.role === 'manager';

  const [activeTab, setActiveTab] = useState<'calendar' | 'my_stats' | 'requests' | 'admin_overview'>('calendar');
  const [currentDate, setCurrentDate] = useState(new Date());
  const [now, setNow] = useState(new Date());

  // --- Clock & Timer ---
  useEffect(() => {
    const timer = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);

  // --- Mock Holidays & Events (Expanded) ---
  const [calendarEvents, setCalendarEvents] = useState<CalendarEvent[]>([
    { 
      id: 'e1', date: '2023-11-24', title: 'Thanksgiving', type: 'holiday', 
      createdBy: 'system', targetScope: 'all' 
    },
    { 
      id: 'e2', date: '2023-12-25', title: 'Christmas', type: 'holiday', 
      createdBy: 'system', targetScope: 'all' 
    },
    { 
      id: 'e3', date: '2023-12-15', title: 'IT Maintenance', type: 'maintenance', 
      description: 'Server downtime 2am-4am',
      createdBy: 'admin', targetScope: 'department', targetDepartmentIds: ['1'] // Targeted to IT Dept
    }
  ]);

  // --- Modals ---
  const [isLeaveModalOpen, setIsLeaveModalOpen] = useState(false);
  const [isCorrectionModalOpen, setIsCorrectionModalOpen] = useState(false);
  const [isEventModalOpen, setIsEventModalOpen] = useState(false); // New Event Modal

  const [confirmModal, setConfirmModal] = useState<{isOpen: boolean, action: () => void, message: string}>({isOpen: false, action: () => {}, message: ''});

  // Forms
  const [leaveForm, setLeaveForm] = useState({ startDate: '', endDate: '', type: 'sick', reason: '' });
  const [correctionForm, setCorrectionForm] = useState({ date: '', checkIn: '', checkOut: '', reason: '' });

  // Event Form State
  const [eventForm, setEventForm] = useState<{
    date: string;
    title: string;
    description: string;
    type: 'maintenance' | 'holiday' | 'meeting' | 'reminder';
    targetScope: 'all' | 'department' | 'user';
    targetDepartmentIds: string[];
    targetUserIds: string[];
  }>({
    date: '',
    title: '',
    description: '',
    type: 'reminder',
    targetScope: 'all',
    targetDepartmentIds: [],
    targetUserIds: []
  });

  // Admin Modals
  const [rejectModal, setRejectModal] = useState<{isOpen: boolean, req: LeaveRequest | null}>({isOpen: false, req: null});
  const [rejectionReason, setRejectionReason] = useState('');
  const [adminManualEntryModal, setAdminManualEntryModal] = useState({ isOpen: false, userId: '', date: '', checkIn: '', checkOut: '', status: 'present' });

  // --- Event Handlers ---

  const handleDateClick = (day: number) => {
    // Only Super Admin or HR Admin can create events on click
    if (!isSystemAdmin) return;

    const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
    setEventForm({
      date: dateStr,
      title: '',
      description: '',
      type: 'reminder',
      targetScope: 'all',
      targetDepartmentIds: [],
      targetUserIds: []
    });
    setIsEventModalOpen(true);
  };

  const handleCreateEvent = (e: React.FormEvent) => {
    e.preventDefault();
    const newEvent: CalendarEvent = {
      id: Math.random().toString(36).substr(2, 9),
      ...eventForm,
      createdBy: currentUser.id
    };
    setCalendarEvents([...calendarEvents, newEvent]);
    setIsEventModalOpen(false);
  };

  // --- Attendance Logic ---

  const todayStr = now.toLocaleDateString('en-CA', { timeZone: 'Asia/Kolkata' }); // YYYY-MM-DD
  const myTodayRecord = attendanceRecords.find(r => r.userId === currentUser.id && r.date === todayStr);

  const handleCheckIn = () => {
    const timeStr = now.toLocaleTimeString('en-IN', { timeZone: 'Asia/Kolkata', hour12: false, hour: '2-digit', minute: '2-digit' });
    let status: any = 'present';
    const [h, m] = timeStr.split(':').map(Number);
    if (h > 9 || (h === 9 && m > 15)) status = 'late';

    const newRecord: AttendanceRecord = {
      id: Math.random().toString(36).substr(2, 9),
      userId: currentUser.id,
      date: todayStr,
      status: status,
      checkIn: timeStr,
      location: 'Office HQ (IP: 192.168.1.55)', // Simulated
      totalHours: 0
    };
    onUpdateAttendance(newRecord);
  };

  const handleCheckOut = () => {
    if (!myTodayRecord || !myTodayRecord.checkIn) return;
    const timeStr = now.toLocaleTimeString('en-IN', { timeZone: 'Asia/Kolkata', hour12: false, hour: '2-digit', minute: '2-digit' });
    const [inH, inM] = myTodayRecord.checkIn.split(':').map(Number);
    const [outH, outM] = timeStr.split(':').map(Number);
    const start = new Date(0, 0, 0, inH, inM, 0);
    const end = new Date(0, 0, 0, outH, outM, 0);
    const diffMs = end.getTime() - start.getTime();
    const diffHrs = diffMs / (1000 * 60 * 60);

    let status = myTodayRecord.status;
    let overtime = 0;
    if (diffHrs < 4.5) status = 'half-day';
    if (diffHrs > 9) overtime = diffHrs - 9;

    onUpdateAttendance({
      ...myTodayRecord,
      checkOut: timeStr,
      totalHours: parseFloat(diffHrs.toFixed(2)),
      overtimeHours: parseFloat(overtime.toFixed(2)),
      status: status
    });
  };

  const handleCorrectionSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    alert('Correction request submitted to Admin for approval.');
    setIsCorrectionModalOpen(false);
  };

  const handleAdminManualSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const { userId, date, checkIn, checkOut, status } = adminManualEntryModal;
    let total = 0;
    if (checkIn && checkOut) {
       const [h1, m1] = checkIn.split(':').map(Number);
       const [h2, m2] = checkOut.split(':').map(Number);
       total = (h2 + m2/60) - (h1 + m1/60);
    }
    onUpdateAttendance({
      id: Math.random().toString(36).substr(2, 9),
      userId,
      date,
      status: status as any,
      checkIn,
      checkOut,
      totalHours: parseFloat(total.toFixed(2)),
      isLocked: true 
    });
    setAdminManualEntryModal({ ...adminManualEntryModal, isOpen: false });
  };

  const handleLockPayroll = () => {
    setConfirmModal({
      isOpen: true,
      message: `Are you sure you want to LOCK attendance for ${currentDate.toLocaleString('default', { month: 'long' })}? No further edits will be allowed.`,
      action: () => {
         alert('Payroll Locked Successfully. Reports generated.');
         setConfirmModal(prev => ({...prev, isOpen: false}));
      }
    });
  };

  // --- Render Helpers ---

  const getDaysInMonth = (date: Date) => new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
  const getFirstDayOfMonth = (date: Date) => new Date(date.getFullYear(), date.getMonth(), 1).getDay();
  const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));

  // --- Render Calendar ---

  const renderCalendar = () => {
    const daysInMonth = getDaysInMonth(currentDate);
    const firstDay = getFirstDayOfMonth(currentDate);
    const days = [];
    const monthName = currentDate.toLocaleString('default', { month: 'long', year: 'numeric' });

    for (let i = 0; i < firstDay; i++) {
      days.push(<div key={`empty-${i}`} className="h-32 bg-dark-900/50 border border-dark-800"></div>);
    }

    for (let d = 1; d <= daysInMonth; d++) {
      const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;

      // Data Filters
      const attendance = attendanceRecords.find(r => r.userId === currentUser.id && r.date === dateStr);
      const leave = leaveRequests.find(r => r.userId === currentUser.id && r.startDate <= dateStr && r.endDate >= dateStr && r.status === 'approved');

      // Filter Events based on Target Scope
      const eventsForDay = calendarEvents.filter(e => {
        if (e.date !== dateStr) return false;
        if (e.targetScope === 'all') return true;
        if (e.targetScope === 'department') {
           // Assume we can match dept name or ID. Using name for simplicity in mock, ideally ID.
           const myDept = departments.find(dept => dept.name === currentUser.department);
           return e.targetDepartmentIds?.includes(myDept?.id || '999'); 
        }
        if (e.targetScope === 'user') {
          return e.targetUserIds?.includes(currentUser.id);
        }
        return false;
      });

      // Default Styles
      let bgClass = 'bg-dark-800 hover:bg-dark-700';
      let borderClass = 'border-dark-700';

      // Visual Priority
      if (eventsForDay.some(e => e.type === 'holiday')) {
        bgClass = 'bg-purple-900/20 hover:bg-purple-900/30';
        borderClass = 'border-purple-800';
      } else if (eventsForDay.some(e => e.type === 'maintenance')) {
        bgClass = 'bg-blue-900/20 hover:bg-blue-900/30';
        borderClass = 'border-blue-800';
      } else if (leave) {
        bgClass = 'bg-amber-900/20 hover:bg-amber-900/30';
        borderClass = 'border-amber-800';
      } else if (attendance) {
         if (attendance.status === 'present') { bgClass = 'bg-emerald-900/20'; borderClass = 'border-emerald-800'; }
         if (attendance.status === 'late') { bgClass = 'bg-orange-900/20'; borderClass = 'border-orange-800'; }
         if (attendance.status === 'absent') { bgClass = 'bg-red-900/20'; borderClass = 'border-red-800'; }
      }

      days.push(
        <div 
          key={d} 
          onClick={() => handleDateClick(d)}
          className={`h-32 border ${borderClass} p-2 relative transition-all group ${bgClass} ${isSystemAdmin ? 'cursor-pointer hover:ring-2 hover:ring-primary-500/50' : ''}`}
        >
          <span className="text-sm font-bold text-slate-300 group-hover:text-white">{d}</span>

          <div className="mt-1 space-y-1">
             {/* Render Events */}
             {eventsForDay.map(ev => (
               <div key={ev.id} className={`text-[10px] font-bold px-1.5 py-0.5 rounded truncate ${
                 ev.type === 'holiday' ? 'bg-purple-500 text-white' :
                 ev.type === 'maintenance' ? 'bg-blue-500 text-white' :
                 ev.type === 'meeting' ? 'bg-indigo-500 text-white' : 'bg-slate-600 text-white'
               }`}>
                 {ev.title}
               </div>
             ))}

             {/* Render Leave */}
             {leave && (
               <div className="text-[10px] font-bold px-1.5 py-0.5 rounded bg-amber-900/50 text-amber-400">
                 On Leave
               </div>
             )}

             {/* Render Attendance */}
             {attendance && (
               <div className="text-[10px] text-slate-400 mt-1">
                 {attendance.status === 'present' && <span className="text-emerald-400 font-bold">P </span>}
                 {attendance.status === 'late' && <span className="text-orange-400 font-bold">L </span>}
                 {attendance.status === 'absent' && <span className="text-red-400 font-bold">A </span>}
                 {attendance.checkIn && <span>{attendance.checkIn}</span>}
               </div>
             )}
          </div>
        </div>
      );
    }

    return (
      <div className="bg-dark-900 rounded-2xl shadow-xl border border-dark-700 overflow-hidden">
        <div className="flex items-center justify-between p-5 border-b border-dark-700 bg-dark-800/50">
           <h2 className="text-xl font-bold text-white flex items-center gap-2">
             <CalendarIcon className="text-primary-500" />
             {monthName}
           </h2>
           <div className="flex gap-2">
             <Button variant="secondary" onClick={prevMonth} className="p-2 border-dark-600 text-slate-300 hover:text-white"><ChevronLeft size={16} /></Button>
             <Button variant="secondary" onClick={nextMonth} className="p-2 border-dark-600 text-slate-300 hover:text-white"><ChevronRight size={16} /></Button>
           </div>
        </div>
        <div className="grid grid-cols-7 text-center bg-dark-800 border-b border-dark-700">
          {['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].map(day => (
            <div key={day} className="py-3 text-xs font-bold text-slate-500 uppercase tracking-wider">{day}</div>
          ))}
        </div>
        <div className="grid grid-cols-7 bg-dark-900">
          {days}
        </div>
      </div>
    );
  };

  const renderStats = () => {
    // Calculate Stats for current month
    const userRecords = attendanceRecords.filter(r => r.userId === currentUser.id && r.date.startsWith(`${currentDate.getFullYear()}-${String(currentDate.getMonth()+1).padStart(2,'0')}`));
    const daysPresent = userRecords.filter(r => ['present', 'late', 'half-day'].includes(r.status)).length;
    const totalHours = userRecords.reduce((acc, curr) => acc + (curr.totalHours || 0), 0);
    const totalOT = userRecords.reduce((acc, curr) => acc + (curr.overtimeHours || 0), 0);
    const lateDays = userRecords.filter(r => r.status === 'late').length;

    return (
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
         <div className="p-4 rounded-xl bg-dark-800 border border-dark-700">
            <p className="text-xs font-bold text-slate-500 uppercase">Days Present</p>
            <p className="text-2xl font-bold text-white mt-1">{daysPresent} <span className="text-sm text-slate-500 font-normal">/ {getDaysInMonth(currentDate)}</span></p>
         </div>
         <div className="p-4 rounded-xl bg-dark-800 border border-dark-700">
            <p className="text-xs font-bold text-slate-500 uppercase">Total Hours</p>
            <p className="text-2xl font-bold text-primary-400 mt-1">{totalHours.toFixed(1)} <span className="text-sm text-slate-500 font-normal">hrs</span></p>
         </div>
         <div className="p-4 rounded-xl bg-dark-800 border border-dark-700">
            <p className="text-xs font-bold text-slate-500 uppercase">Overtime</p>
            <p className="text-2xl font-bold text-emerald-400 mt-1">{totalOT.toFixed(1)} <span className="text-sm text-slate-500 font-normal">hrs</span></p>
         </div>
         <div className="p-4 rounded-xl bg-dark-800 border border-dark-700">
            <p className="text-xs font-bold text-slate-500 uppercase">Late Arrivals</p>
            <p className="text-2xl font-bold text-orange-400 mt-1">{lateDays}</p>
         </div>
      </div>
    );
  };

  const renderAdminOverview = () => {
    // ... (Admin overview logic same as before, omitted for brevity, logic included in full file return below)
    const daysInMonth = getDaysInMonth(currentDate);
    const dateHeaders = [];
    for(let i=1; i<=daysInMonth; i++) dateHeaders.push(i);

    return (
      <div className="space-y-6">
        <div className="flex flex-col sm:flex-row justify-between items-end sm:items-center gap-4">
           <div>
             <h2 className="text-lg font-bold text-white">Attendance Master Sheet</h2>
             <p className="text-sm text-slate-400">{currentDate.toLocaleString('default', { month: 'long', year: 'numeric' })}</p>
           </div>
           {canManageCalendar && (
             <div className="flex gap-3">
               <Button variant="secondary" onClick={() => setAdminManualEntryModal({...adminManualEntryModal, isOpen: true})}>
                 <Plus size={16} className="mr-2" /> Manual Entry
               </Button>
               <Button variant="primary" className="bg-red-600 hover:bg-red-700 border-none text-white" onClick={handleLockPayroll}>
                 <Lock size={16} className="mr-2" /> Lock Month (Payroll)
               </Button>
             </div>
           )}
        </div>
        <div className="bg-dark-800 rounded-xl shadow-lg border border-dark-700 overflow-x-auto custom-scrollbar">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-dark-900/50">
                <th className="p-3 sticky left-0 bg-dark-900 z-10 border-r border-dark-700 min-w-[200px] text-xs font-bold text-slate-400 uppercase">Employee</th>
                {dateHeaders.map(d => <th key={d} className="p-2 min-w-[40px] text-center text-xs font-bold text-slate-500 border-r border-dark-700/50">{d}</th>)}
              </tr>
            </thead>
            <tbody className="divide-y divide-dark-700">
              {users.map(user => (
                <tr key={user.id} className="hover:bg-white/5 transition-colors">
                  <td className="p-3 sticky left-0 bg-dark-800 border-r border-dark-700 flex items-center gap-2">
                     <div className="w-8 h-8 rounded-full bg-dark-700 overflow-hidden border border-dark-600"><img src={user.avatar || `https://ui-avatars.com/api/?name=${user.username}`} alt="" className="w-full h-full object-cover" /></div>
                     <div><div className="text-sm font-bold text-slate-200">{user.username}</div><div className="text-[10px] text-slate-500 uppercase">{user.role}</div></div>
                  </td>
                  {dateHeaders.map(d => {
                    const dateStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
                    const record = attendanceRecords.find(r => r.userId === user.id && r.date === dateStr);
                    const leave = leaveRequests.find(r => r.userId === user.id && r.startDate <= dateStr && r.endDate >= dateStr && r.status === 'approved');
                    const event = calendarEvents.find(e => e.date === dateStr && (e.targetScope === 'all' || e.targetUserIds?.includes(user.id))); // Simplified admin view check

                    let content = <span className="text-dark-700">·</span>;
                    let bgColor = '';
                    if (event && event.type === 'holiday') { content = <span className="text-purple-500 font-bold text-xs">H</span>; bgColor = 'bg-purple-900/10'; }
                    else if (leave) { content = <span className="text-amber-500 font-bold text-xs">L</span>; bgColor = 'bg-amber-900/10'; }
                    else if (record) {
                      if (record.status === 'present') { content = <span className="text-emerald-500 font-bold text-xs">P</span>; bgColor = 'bg-emerald-900/10'; }
                      else { content = <span className="text-red-500 font-bold text-xs">A</span>; bgColor = 'bg-red-900/10'; }
                    }
                    return <td key={d} className={`text-center border-r border-dark-700/50 p-1 ${bgColor}`}>{content}</td>;
                  })}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    );
  };

  // --- Main Render ---

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-20">

      {/* Top Bar: Live Clock & Actions */}
      <div className="glass-card rounded-2xl p-6 flex flex-col md:flex-row justify-between items-center gap-6">
         <div>
            <h1 className="text-3xl font-black text-white tracking-tight">EETTI <span className="text-primary-500">Attendance</span></h1>
            <p className="text-slate-400 mt-1 flex items-center gap-2">
              <MapPin size={14} /> Corporate Office HQ • {now.toLocaleDateString('en-IN', { timeZone: 'Asia/Kolkata', weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}
            </p>
         </div>

         {/* Punch Clock Widget */}
         <div className="flex items-center gap-6 bg-dark-900/50 p-4 rounded-xl border border-dark-700">
            <div className="text-right">
               <div className="text-3xl font-mono font-bold text-white tabular-nums tracking-wider">
                 {now.toLocaleTimeString('en-IN', { timeZone: 'Asia/Kolkata', hour12: false })}
               </div>
               <div className="text-xs text-slate-500 uppercase tracking-widest font-bold">IST (Asia/Kolkata)</div>
            </div>
            <div className="h-10 w-px bg-dark-700"></div>
            <div>
              {myTodayRecord?.checkIn && !myTodayRecord.checkOut ? (
                 <Button onClick={handleCheckOut} className="bg-red-600 hover:bg-red-500 text-white border-none shadow-[0_0_15px_rgba(220,38,38,0.4)]">
                   <Briefcase className="mr-2" size={18} /> Check Out
                 </Button>
              ) : myTodayRecord?.checkOut ? (
                 <div className="px-4 py-2 bg-emerald-900/30 border border-emerald-800 text-emerald-400 rounded-lg flex items-center">
                    <CheckCircle className="mr-2" size={18} /> Day Complete
                 </div>
              ) : (
                 <Button onClick={handleCheckIn} className="bg-primary-500 hover:bg-primary-400 text-black font-bold border-none shadow-[0_0_15px_rgba(234,179,8,0.4)]">
                   <Fingerprint className="mr-2" size={18} /> Check In
                 </Button>
              )}
            </div>
         </div>
      </div>

      {/* Main Tabs */}
      <div className="border-b border-dark-700">
         <nav className="flex space-x-1">
           <button onClick={() => setActiveTab('calendar')} className={`px-6 py-4 text-sm font-bold border-b-2 transition-colors ${activeTab === 'calendar' ? 'border-primary-500 text-primary-400' : 'border-transparent text-slate-500 hover:text-slate-300'}`}>
             Calendar View
           </button>
           <button onClick={() => setActiveTab('requests')} className={`px-6 py-4 text-sm font-bold border-b-2 transition-colors ${activeTab === 'requests' ? 'border-primary-500 text-primary-400' : 'border-transparent text-slate-500 hover:text-slate-300'}`}>
             Requests & Approvals
           </button>
           {isAdmin && (
             <button onClick={() => setActiveTab('admin_overview')} className={`px-6 py-4 text-sm font-bold border-b-2 transition-colors ${activeTab === 'admin_overview' ? 'border-primary-500 text-primary-400' : 'border-transparent text-slate-500 hover:text-slate-300'}`}>
               Master Sheet (Admin)
             </button>
           )}
         </nav>
      </div>

      {/* Tab Content */}
      <div className="min-h-[400px]">
        {activeTab === 'calendar' && (
          <div className="space-y-6">
             {renderStats()}
             <div className="flex justify-end mb-2">
               {isSystemAdmin && (
                 <span className="text-xs text-slate-400 italic mr-4 self-center">
                   * Click on a date to add Company Event/Holiday
                 </span>
               )}
               <Button variant="secondary" onClick={() => setIsCorrectionModalOpen(true)} className="text-xs">
                 Request Correction
               </Button>
             </div>
             {renderCalendar()}
          </div>
        )}
        {activeTab === 'requests' && (
           /* ... Existing Request Tab Content (No change needed) ... */
           <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              {/* Request Leave Section */}
              <div className="bg-dark-800 rounded-xl p-6 border border-dark-700">
                 <div className="flex justify-between items-center mb-6">
                    <h3 className="text-lg font-bold text-white">My Leave Requests</h3>
                    <Button onClick={() => setIsLeaveModalOpen(true)} className="text-xs">
                      <Plus size={14} className="mr-1" /> New Request
                    </Button>
                 </div>
                 <div className="space-y-3">
                    {leaveRequests.filter(r => r.userId === currentUser.id).map(req => (
                      <div key={req.id} className="p-4 bg-dark-900 rounded-lg border border-dark-700 flex justify-between items-center">
                         <div>
                            <div className="font-bold text-slate-200 capitalize">{req.type} Leave</div>
                            <div className="text-xs text-slate-500">{req.startDate} to {req.endDate}</div>
                         </div>
                         <span className={`px-2 py-1 text-xs font-bold rounded uppercase ${
                           req.status === 'approved' ? 'bg-emerald-900/30 text-emerald-400' :
                           req.status === 'rejected' ? 'bg-red-900/30 text-red-400' :
                           'bg-amber-900/30 text-amber-400'
                         }`}>
                           {req.status}
                         </span>
                      </div>
                    ))}
                 </div>
              </div>

              {/* Admin Approvals */}
              {isAdmin && (
                <div className="bg-dark-800 rounded-xl p-6 border border-dark-700">
                   <h3 className="text-lg font-bold text-white mb-6 flex items-center gap-2">
                     <ShieldAlert className="text-primary-500" /> Pending Approvals
                   </h3>
                   <div className="space-y-4">
                     {leaveRequests.filter(r => r.status === 'pending').length === 0 ? (
                       <p className="text-slate-500 italic">No pending requests.</p>
                     ) : (
                       leaveRequests.filter(r => r.status === 'pending').map(req => {
                         const u = users.find(user => user.id === req.userId);
                         return (
                           <div key={req.id} className="p-4 bg-dark-900 rounded-lg border border-dark-600">
                              <div className="flex justify-between mb-2">
                                 <span className="font-bold text-white">{u?.username}</span>
                                 <span className="text-xs text-primary-400 font-bold uppercase">{req.type} Leave</span>
                              </div>
                              <p className="text-sm text-slate-400 italic mb-3">"{req.reason}"</p>
                              <div className="flex gap-2">
                                <Button variant="secondary" className="flex-1 text-xs h-8 border-red-900 text-red-400 hover:bg-red-900/20" onClick={() => { setRejectModal({isOpen: true, req}); }}>Deny</Button>
                                <Button className="flex-1 text-xs h-8 bg-emerald-600 hover:bg-emerald-500 border-none text-white" onClick={() => onUpdateLeaveStatus(req.id, 'approved', 'Approved')}>Approve</Button>
                              </div>
                           </div>
                         )
                       })
                     )}
                   </div>
                </div>
              )}
           </div>
        )}
        {activeTab === 'admin_overview' && isAdmin && renderAdminOverview()}
      </div>

      {/* --- EVENT MODAL (Super Admin / HR) --- */}
      <Modal isOpen={isEventModalOpen} onClose={() => setIsEventModalOpen(false)} title="Add Calendar Event">
         <form onSubmit={handleCreateEvent} className="space-y-4">
            <div className="p-3 bg-blue-50 border border-blue-100 rounded-lg text-xs text-blue-800">
              Create an event, reminder, or holiday for specific groups or the entire company.
            </div>

            <div className="grid grid-cols-2 gap-4">
               <div>
                 <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Date</label>
                 <input type="date" required className="w-full bg-slate-100 border-slate-200 rounded-lg p-2 text-slate-900" value={eventForm.date} onChange={e => setEventForm({...eventForm, date: e.target.value})} />
               </div>
               <div>
                 <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Type</label>
                 <select className="w-full bg-slate-100 border-slate-200 rounded-lg p-2 text-slate-900 capitalize" value={eventForm.type} onChange={e => setEventForm({...eventForm, type: e.target.value as any})}>
                    <option value="reminder">Reminder / Message</option>
                    <option value="meeting">Schedule / Meeting</option>
                    <option value="maintenance">Maintenance</option>
                    <option value="holiday">Holiday</option>
                 </select>
               </div>
            </div>

            <div>
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Title</label>
               <input type="text" required placeholder="e.g. Server Maintenance" className="w-full bg-slate-100 border-slate-200 rounded-lg p-2 text-slate-900" value={eventForm.title} onChange={e => setEventForm({...eventForm, title: e.target.value})} />
            </div>
            <div>
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Description / Message</label>
               <textarea rows={2} className="w-full bg-slate-100 border-slate-200 rounded-lg p-2 text-slate-900" value={eventForm.description} onChange={e => setEventForm({...eventForm, description: e.target.value})} />
            </div>

            {/* Targeting Logic */}
            <div className="border-t border-slate-200 pt-4 mt-2">
               <label className="block text-xs font-bold text-slate-500 uppercase mb-2">Target Audience</label>

               <div className="flex gap-4 mb-3">
                 <label className="flex items-center gap-2 cursor-pointer bg-slate-50 px-3 py-2 rounded-lg border border-slate-200 hover:border-primary-500">
                   <input type="radio" name="scope" value="all" checked={eventForm.targetScope === 'all'} onChange={() => setEventForm({...eventForm, targetScope: 'all'})} className="text-primary-600 focus:ring-primary-500" />
                   <span className="text-sm font-bold text-slate-700 flex items-center gap-1"><Globe size={14}/> Everyone</span>
                 </label>
                 <label className="flex items-center gap-2 cursor-pointer bg-slate-50 px-3 py-2 rounded-lg border border-slate-200 hover:border-primary-500">
                   <input type="radio" name="scope" value="department" checked={eventForm.targetScope === 'department'} onChange={() => setEventForm({...eventForm, targetScope: 'department'})} className="text-primary-600 focus:ring-primary-500" />
                   <span className="text-sm font-bold text-slate-700 flex items-center gap-1"><Building size={14}/> Departments</span>
                 </label>
                 <label className="flex items-center gap-2 cursor-pointer bg-slate-50 px-3 py-2 rounded-lg border border-slate-200 hover:border-primary-500">
                   <input type="radio" name="scope" value="user" checked={eventForm.targetScope === 'user'} onChange={() => setEventForm({...eventForm, targetScope: 'user'})} className="text-primary-600 focus:ring-primary-500" />
                   <span className="text-sm font-bold text-slate-700 flex items-center gap-1"><Users size={14}/> Specific Users</span>
                 </label>
               </div>

               {/* Multi-Select: Departments */}
               {eventForm.targetScope === 'department' && (
                 <div className="max-h-32 overflow-y-auto bg-slate-50 border border-slate-200 rounded-lg p-2 grid grid-cols-2 gap-2">
                    {departments.map(dept => (
                       <label key={dept.id} className="flex items-center gap-2 text-sm p-1 hover:bg-white rounded cursor-pointer">
                          <input 
                            type="checkbox" 
                            checked={eventForm.targetDepartmentIds.includes(dept.id)}
                            onChange={(e) => {
                               const newIds = e.target.checked 
                                 ? [...eventForm.targetDepartmentIds, dept.id]
                                 : eventForm.targetDepartmentIds.filter(id => id !== dept.id);
                               setEventForm({...eventForm, targetDepartmentIds: newIds});
                            }}
                            className="text-primary-600 rounded"
                          />
                          <span className="text-slate-700">{dept.name}</span>
                       </label>
                    ))}
                 </div>
               )}

               {/* Multi-Select: Users */}
               {eventForm.targetScope === 'user' && (
                 <div className="max-h-32 overflow-y-auto bg-slate-50 border border-slate-200 rounded-lg p-2 grid grid-cols-2 gap-2">
                    {users.map(u => (
                       <label key={u.id} className="flex items-center gap-2 text-sm p-1 hover:bg-white rounded cursor-pointer">
                          <input 
                            type="checkbox" 
                            checked={eventForm.targetUserIds.includes(u.id)}
                            onChange={(e) => {
                               const newIds = e.target.checked 
                                 ? [...eventForm.targetUserIds, u.id]
                                 : eventForm.targetUserIds.filter(id => id !== u.id);
                               setEventForm({...eventForm, targetUserIds: newIds});
                            }}
                            className="text-primary-600 rounded"
                          />
                          <span className="text-slate-700">{u.username}</span>
                       </label>
                    ))}
                 </div>
               )}
            </div>

            <div className="flex justify-end pt-2">
               <Button type="submit">Create Event</Button>
            </div>
         </form>
      </Modal>

      {/* ... Existing Modals ... */}
      <Modal isOpen={isLeaveModalOpen} onClose={() => setIsLeaveModalOpen(false)} title="Apply for Leave">
         <form onSubmit={(e) => { e.preventDefault(); onAddLeaveRequest({...leaveForm, type: leaveForm.type as any}); setIsLeaveModalOpen(false); }} className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
               <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">From</label>
                  <input type="date" required className="w-full bg-slate-100 border-slate-200 rounded-lg p-2 text-slate-900" value={leaveForm.startDate} onChange={e => setLeaveForm({...leaveForm, startDate: e.target.value})} />
               </div>
               <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">To</label>
                  <input type="date" required className="w-full bg-slate-100 border-slate-200 rounded-lg p-2 text-slate-900" value={leaveForm.endDate} onChange={e => setLeaveForm({...leaveForm, endDate: e.target.value})} />
               </div>
            </div>
            <div>
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Type</label>
               <select className="w-full bg-slate-100 border-slate-200 rounded-lg p-2 text-slate-900" value={leaveForm.type} onChange={e => setLeaveForm({...leaveForm, type: e.target.value})}>
                 <option value="sick">Sick Leave</option>
                 <option value="vacation">Vacation</option>
                 <option value="personal">Personal</option>
               </select>
            </div>
            <div>
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Reason</label>
               <textarea required className="w-full bg-slate-100 border-slate-200 rounded-lg p-2 text-slate-900" rows={3} value={leaveForm.reason} onChange={e => setLeaveForm({...leaveForm, reason: e.target.value})}></textarea>
            </div>
            <div className="flex justify-end pt-2">
               <Button type="submit">Submit Application</Button>
            </div>
         </form>
      </Modal>

      <Modal isOpen={isCorrectionModalOpen} onClose={() => setIsCorrectionModalOpen(false)} title="Attendance Correction">
         <form onSubmit={handleCorrectionSubmit} className="space-y-4">
            <div>
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Select Date</label>
               <input type="date" required className="w-full bg-slate-100 border-slate-200 rounded-lg p-2 text-slate-900" value={correctionForm.date} onChange={e => setCorrectionForm({...correctionForm, date: e.target.value})} />
            </div>
            <div className="grid grid-cols-2 gap-4">
               <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Check In</label>
                  <input type="time" className="w-full bg-slate-100 border-slate-200 rounded-lg p-2 text-slate-900" value={correctionForm.checkIn} onChange={e => setCorrectionForm({...correctionForm, checkIn: e.target.value})} />
               </div>
               <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Check Out</label>
                  <input type="time" className="w-full bg-slate-100 border-slate-200 rounded-lg p-2 text-slate-900" value={correctionForm.checkOut} onChange={e => setCorrectionForm({...correctionForm, checkOut: e.target.value})} />
               </div>
            </div>
            <div>
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Reason for Adjustment</label>
               <textarea required className="w-full bg-slate-100 border-slate-200 rounded-lg p-2 text-slate-900" rows={2} value={correctionForm.reason} onChange={e => setCorrectionForm({...correctionForm, reason: e.target.value})} placeholder="e.g. Forgot ID card, Biometric failure"></textarea>
            </div>
            <div className="flex justify-end pt-2">
               <Button type="submit">Request Adjustment</Button>
            </div>
         </form>
      </Modal>

      {/* Manual Admin Entry Modal */}
      <Modal isOpen={adminManualEntryModal.isOpen} onClose={() => setAdminManualEntryModal({...adminManualEntryModal, isOpen: false})} title="Admin: Manual Attendance">
         <form onSubmit={handleAdminManualSubmit} className="space-y-4">
            <div>
              <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Employee</label>
              <select className="w-full bg-slate-100 border-slate-200 rounded-lg p-2 text-slate-900" value={adminManualEntryModal.userId} onChange={e => setAdminManualEntryModal({...adminManualEntryModal, userId: e.target.value})} required>
                 <option value="">Select Employee</option>
                 {users.map(u => <option key={u.id} value={u.id}>{u.username}</option>)}
              </select>
            </div>
            <div>
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Date</label>
               <input type="date" required className="w-full bg-slate-100 border-slate-200 rounded-lg p-2 text-slate-900" value={adminManualEntryModal.date} onChange={e => setAdminManualEntryModal({...adminManualEntryModal, date: e.target.value})} />
            </div>
            <div className="grid grid-cols-2 gap-4">
               <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Check In</label>
                  <input type="time" required className="w-full bg-slate-100 border-slate-200 rounded-lg p-2 text-slate-900" value={adminManualEntryModal.checkIn} onChange={e => setAdminManualEntryModal({...adminManualEntryModal, checkIn: e.target.value})} />
               </div>
               <div>
                  <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Check Out</label>
                  <input type="time" required className="w-full bg-slate-100 border-slate-200 rounded-lg p-2 text-slate-900" value={adminManualEntryModal.checkOut} onChange={e => setAdminManualEntryModal({...adminManualEntryModal, checkOut: e.target.value})} />
               </div>
            </div>
             <div>
               <label className="block text-xs font-bold text-slate-500 uppercase mb-1">Status</label>
               <select className="w-full bg-slate-100 border-slate-200 rounded-lg p-2 text-slate-900" value={adminManualEntryModal.status} onChange={e => setAdminManualEntryModal({...adminManualEntryModal, status: e.target.value})}>
                 <option value="present">Present</option>
                 <option value="late">Late</option>
                 <option value="half-day">Half Day</option>
                 <option value="absent">Absent</option>
               </select>
            </div>
            <div className="flex justify-end pt-2">
               <Button type="submit">Add Record</Button>
            </div>
         </form>
      </Modal>

      <ConfirmationModal isOpen={confirmModal.isOpen} onClose={() => setConfirmModal({...confirmModal, isOpen: false})} onConfirm={confirmModal.action} title="Confirm Action" message={confirmModal.message} isDanger={true} confirmLabel="Confirm" />
    </div>
  );
};

export default AttendancePage;

import React from 'react';

// --- Corporate Role Structure ---
export type SystemRole = 
  | 'super_admin' 
  | 'hr_admin' 
  | 'payroll_admin' 
  | 'manager' 
  | 'shift_supervisor' 
  | 'employee' 
  | 'intern' 
  | 'contract' 
  | 'auditor' 
  | 'it_support';

export type PermissionKey = 
  | 'all_access'           // Super Admin Exclusive
  | 'view_dashboard'
  | 'calendar_view'
  | 'calendar_manage'      // Create schedules/events
  | 'user_view'
  | 'user_manage'          // Create/Edit users
  | 'role_manage'          // Configure permissions (Super Admin)
  | 'payroll_view'
  | 'payroll_manage'
  | 'project_view'
  | 'project_manage'
  | 'reports_view'
  | 'security_manage';

export interface User {
  id: string; // System Generated

  // 2.1 Core Identity
  employeeCode: string;
  username: string; // Login ID
  passwordHash?: string; // Simulated encrypted
  firstName: string;
  lastName: string;
  displayName?: string;
  gender: 'male' | 'female' | 'other';
  dateOfBirth: string;
  avatar?: string;

  // 2.2 Contact
  officialEmail: string;
  personalEmail?: string;
  mobileNumber: string;
  emergencyContactName?: string;
  emergencyContactNumber?: string;

  // 2.3 Account Status
  status: 'active' | 'inactive' | 'suspended';
  lastLogin: string;

  // 2.4 Employment
  userType: 'employee' | 'intern' | 'contract' | 'consultant';
  employmentStatus: 'permanent' | 'probation' | 'notice-period' | 'temporary';
  department: string;
  position: string; // Designation
  reportingManagerId?: string;
  workLocation: string;
  workMode: 'office' | 'remote' | 'hybrid';
  joinDate: string;
  exitDate?: string; // For offboarding

  // 2.5 Role & Access
  role: SystemRole; 
  permissionGroup?: string; // ID of custom permission set
  dataVisibilityScope: 'self' | 'team' | 'department' | 'all';

  // 2.6 Attendance Config
  shiftId?: string; // Link to Shift Config
  attendanceMode: 'web' | 'mobile' | 'biometric' | 'all';
  ipRestriction: boolean;

  // 2.8 Intern Specifics
  internDetails?: {
    type: 'paid' | 'unpaid';
    startDate: string;
    endDate: string; // Auto-expiry
    stipendAmount?: number;
    mentorId: string;
    conversionEligibility: boolean;
  };

  // 2.9 Payroll (Restricted View)
  payrollDetails?: {
    salaryType: 'monthly' | 'hourly' | 'stipend';
    bankAccount?: string;
    ifsc?: string;
    pan?: string;
    uan?: string;
    isOvertimeEligible: boolean;
  };

  // 2.10 Audit
  createdBy: string;
  createdAt: string;
  modifiedBy?: string;
  modifiedAt?: string;

  // Legacy/UI props
  bio?: string;
  preferences?: {
    theme?: 'light' | 'dark';
    notifications?: boolean;
    dashboardLayout?: string[];
  };
}

