      </div>

      {/* Main Tabs */}
      <div className="border-b border-dark-700">
         <nav className="flex space-x-1">
           <button onClick={() => setActiveTab('calendar')} className={`px-6 py-4 text-sm font-bold border-b-2 transition-colors ${activeTab === 'calendar' ? 'border-primary-500 text-primary-400' : 'border-transparent text-slate-500 hover:text-slate-300'}`}>
