      </Modal>

      {/* ... Existing Modals ... */}
      <Modal isOpen={isLeaveModalOpen} onClose={() => setIsLeaveModalOpen(false)} title="Apply for Leave">
         <form onSubmit={(e) => { e.preventDefault(); onAddLeaveRequest({...leaveForm, type: leaveForm.type as any}); setIsLeaveModalOpen(false); }} className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
