    { id: 't1', projectId: 'p1', title: 'Setup React Router', description: 'Configure main routing structure.', status: 'done', priority: 'high', assignedTo: ['99'], dueDate: '2023-11-05', createdBy: '1', createdAt: '2023-11-01', timeLogs: [], isPaused: false },
    { id: 't2', projectId: 'p1', title: 'Design Homepage UI', description: 'Implement Figma designs for landing page.', status: 'in-progress', priority: 'medium', assignedTo: ['99'], dueDate: '2023-11-15', createdBy: '1', createdAt: '2023-11-01', timeLogs: [{ status: 'in-progress', start: Date.now() - 3600000 }], isPaused: false },
    { id: 't3', projectId: 'p1', title: 'API Integration', description: 'Connect auth endpoints.', status: 'testing', priority: 'high', assignedTo: ['99'], dueDate: '2023-11-20', createdBy: '1', createdAt: '2023-11-05', timeLogs: [], isPaused: false },
    { id: 't4', projectId: 'p1', title: 'Final QA Review', description: 'Review all components before deployment.', status: 'pending-approval', priority: 'urgent', assignedTo: ['99'], dueDate: '2023-11-25', createdBy: '1', createdAt: '2023-11-10', timeLogs: [], isPaused: false },
  ]);

  // --- Mock Data for Attendance System ---

  const [leaveRequests, setLeaveRequests] = useState<LeaveRequest[]>([
    { id: '101', userId: '2', startDate: '2023-11-10', endDate: '2023-11-12', type: 'sick', reason: 'Flu symptoms', status: 'approved', createdAt: '2023-11-08' },
    { id: '102', userId: '99', startDate: '2023-12-01', endDate: '2023-12-03', type: 'vacation', reason: 'Personal family matter', status: 'pending', createdAt: '2023-11-28' },
  ]);

  const [attendanceRecords, setAttendanceRecords] = useState<AttendanceRecord[]>([
    { id: 'a1', userId: '1', date: '2023-11-01', status: 'present', checkIn: '09:00', checkOut: '17:00' },
    { id: 'a2', userId: '2', date: '2023-11-01', status: 'present', checkIn: '09:15', checkOut: '17:15' },
    { id: 'a3', userId: '99', date: '2023-11-01', status: 'present', checkIn: '09:30', checkOut: '17:30' },
    { id: 'a4', userId: '99', date: '2023-11-02', status: 'present', checkIn: '09:35', checkOut: '17:30' },
    { id: 'h1', userId: '99', date: '2023-11-24', status: 'holiday' },
    { id: 'h2', userId: '1', date: '2023-11-24', status: 'holiday' },
    { id: 'h3', userId: '2', date: '2023-11-24', status: 'holiday' },
  ]);

  const [performanceReviews, setPerformanceReviews] = useState<PerformanceReview[]>([
    { id: 'p1', userId: '2', date: '2023-10-01', rating: 5, comment: 'Excellent leadership on the Q3 project.', reviewer: 'System Administrator' },
    { id: 'p2', userId: '99', date: '2023-09-15', rating: 4, comment: 'Great code quality, but works too late.', reviewer: 'Sarah Connor' },
  ]);


  // --- Helper: Permission Check ---
  // Get current user's role definition
  const currentUserRoleDef = roles.find(r => r.name === user.role);
  const currentUserPermissions = currentUserRoleDef?.permissions || [];

  const hasPermission = (key: PermissionKey) => {
    if (user.role === 'super_admin') return true;
    if (currentUserPermissions.includes('all_access')) return true;
    return currentUserPermissions.includes(key);
  };


  // --- Handlers ---

  const handleAddUser = (newUser: User) => {
    setUsers([...users, newUser]);
  };

  const handleEditUser = (id: string, updates: Partial<User>) => {
    setUsers(users.map(u => u.id === id ? { ...u, ...updates } : u));
    if (selectedUser && selectedUser.id === id) {
      setSelectedUser({ ...selectedUser, ...updates } as User);
    }
  };

  const handleDeleteUser = (id: string) => {
    setUsers(users.filter(u => u.id !== id));
    if (selectedUser && selectedUser.id === id) {
      setCurrentView('users');
      setSelectedUser(null);
    }
  };

  const handleViewUser = (user: User) => {
    setSelectedUser(user);
    setCurrentView('user-details');
  };

  // --- Role Handlers ---
  const handleAddRole = (role: Role) => setRoles([...roles, role]);

  const handleEditRole = (roleId: string, updates: Partial<Role>) => {
    setRoles(roles.map(r => r.id === roleId ? { ...r, ...updates } : r));
  };

  const handleUpdateRolePermissions = (roleId: string, newPermissions: PermissionKey[]) => {
    setRoles(roles.map(r => r.id === roleId ? { ...r, permissions: newPermissions } : r));
  };

  const handleDeleteRole = (id: string) => setRoles(roles.filter(r => r.id !== id));

  // --- Dept Handlers ---
  const handleAddDepartment = (dept: Department) => setDepartments([...departments, dept]);

  const handleEditDepartment = (deptId: string, updates: Partial<Department>) => {
    setDepartments(departments.map(d => d.id === deptId ? { ...d, ...updates } : d));
  };

  const handleDeleteDepartment = (id: string) => setDepartments(departments.filter(d => d.id !== id));

  // --- Attendance Handlers ---
  const handleAddLeaveRequest = (request: Omit<LeaveRequest, 'id' | 'status' | 'createdAt'>) => {
    const newRequest: LeaveRequest = {
      ...request,
      id: Math.random().toString(36).substr(2, 9),
      status: 'pending',
      createdAt: new Date().toISOString().split('T')[0]
    };
    setLeaveRequests([...leaveRequests, newRequest]);
  };

  const handleUpdateLeaveStatus = (id: string, status: 'approved' | 'rejected', comment?: string) => {
    setLeaveRequests(leaveRequests.map(req => req.id === id ? { ...req, status, adminComment: comment } : req));
  };

  const handleDeleteLeaveRequest = (id: string) => {
    setLeaveRequests(leaveRequests.filter(req => req.id !== id));
  };

  const handleUpdateAttendance = (record: AttendanceRecord) => {
    setAttendanceRecords(prev => {
      const existing = prev.findIndex(r => r.id === record.id);
      if (existing >= 0) {
        const updated = [...prev];
        updated[existing] = record;
        return updated;
      }
      return [...prev, record];
    });
  };

  // --- Project Handlers ---

  const handleAddProject = (newProject: Omit<Project, 'id' | 'progress'>) => {
    const project: Project = {
      ...newProject,
      id: Math.random().toString(36).substr(2, 9),
      progress: 0
    };
    setProjects([...projects, project]);
  };

  const handleDeleteProject = (projectId: string) => {
    setProjects(projects.filter(p => p.id !== projectId));
    setTasks(tasks.filter(t => t.projectId !== projectId));
  };

  const handleAddTask = (newTask: Omit<Task, 'id' | 'createdAt' | 'createdBy' | 'timeLogs' | 'isPaused'>) => {
    const task: Task = {
      ...newTask,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString().split('T')[0],
      createdBy: user.id,
      timeLogs: [],
      isPaused: false
    };
    setTasks([...tasks, task]);
  };

  const handleUpdateTask = (taskId: string, updates: Partial<Task>) => {
    setTasks(prevTasks => {
      const newTasks = prevTasks.map(t => t.id === taskId ? { ...t, ...updates } : t);

      // Auto update project progress if status changed
      if (updates.status) {
        const task = prevTasks.find(t => t.id === taskId);
        if(task) {
          const projectTasks = newTasks.filter(t => t.projectId === task.projectId);
          const doneCount = projectTasks.filter(t => t.status === 'done').length;
          const progress = projectTasks.length > 0 ? Math.round((doneCount / projectTasks.length) * 100) : 0;

          setProjects(prevProjects => prevProjects.map(p => p.id === task.projectId ? { ...p, progress } : p));
        }
      }
      return newTasks;
    });
  };

  const handleDeleteTask = (taskId: string) => {
    setTasks(tasks.filter(t => t.id !== taskId));
  };

  // --- Render ---

  const renderContent = () => {
    switch (currentView) {
      case 'dashboard':
        return (
          <Dashboard 
            user={user} 
            tasks={tasks} 
            notifications={myNotifications} 
            onMarkRead={handleMarkNotificationRead}
            onNavigate={(view) => setCurrentView(view)}
          />
        );

      case 'attendance':
        return (
          <AttendancePage 
            currentUser={user}
            users={users}
            departments={departments}
            leaveRequests={leaveRequests}
            attendanceRecords={attendanceRecords}
            onAddLeaveRequest={handleAddLeaveRequest}
            onUpdateLeaveStatus={handleUpdateLeaveStatus}
            onDeleteLeaveRequest={handleDeleteLeaveRequest}
            onUpdateAttendance={handleUpdateAttendance}
            canManageCalendar={hasPermission('calendar_manage')}
            onAddNotification={handleAddNotification}
          />
        );

      case 'projects':
        if (!hasPermission('project_view')) return <AccessDenied />;
        return (
          <ProjectManagement 
            currentUser={user}
            users={users}
            projects={projects}
            tasks={tasks}
            onAddProject={handleAddProject}
            onDeleteProject={handleDeleteProject}
            onAddTask={handleAddTask}
            onUpdateTask={handleUpdateTask}
            onDeleteTask={handleDeleteTask}
          />
        );

      case 'users':
        // Only those with user_view can see this page
        if (!hasPermission('user_view')) return <AccessDenied />;

        return (
          <UserManagement 
            currentUser={user}
            users={users}
            roles={roles}
            departments={departments} 
            onAddUser={handleAddUser}
            onEditUser={handleEditUser}
            onDeleteUser={handleDeleteUser}
            onViewUser={handleViewUser}

            onAddRole={handleAddRole}
            onEditRole={handleEditRole}
            onUpdateRole={handleUpdateRolePermissions}
            onDeleteRole={handleDeleteRole}

            onAddDepartment={handleAddDepartment}
            onEditDepartment={handleEditDepartment}
            onDeleteDepartment={handleDeleteDepartment}
          />
        );

      case 'user-details':
        if (!selectedUser) return <div className="text-center p-10">User not found</div>;
        if (selectedUser.id !== user.id && !hasPermission('user_view')) return <AccessDenied />;

        return (
          <UserDetails 
            user={selectedUser} 
            onBack={() => setCurrentView('users')}
            onEdit={(u) => {
              if (hasPermission('user_manage')) setCurrentView('users');
            }}
            attendanceHistory={attendanceRecords.filter(r => r.userId === selectedUser.id)}
            leaveHistory={leaveRequests.filter(r => r.userId === selectedUser.id)}
            performanceHistory={performanceReviews.filter(r => r.userId === selectedUser.id)}
            tasks={tasks.filter(t => t.assignedTo.includes(selectedUser.id))}
          />
        );

      case 'settings':
        return <SettingsPage user={user} onUpdateUser={(updates) => {
          console.log('Update user preferences:', updates);
        }} />;

      default:
        // Handle views that are not allowed
        if (currentView === 'reports' && !hasPermission('reports_view')) return <AccessDenied />;
        if (currentView === 'security' && !hasPermission('security_manage')) return <AccessDenied />;

        return (
          <div className="flex items-center justify-center h-96 text-slate-400">
            <p>Module "{currentView}" is currently under development.</p>
          </div>
        );
    }
  };

  // Access Denied Component
  const AccessDenied = () => (
    <div className="flex flex-col items-center justify-center h-full py-20 text-center">
      <div className="w-16 h-16 bg-red-50 text-red-500 rounded-full flex items-center justify-center mb-4">
        <Lock size={32} />
      </div>
      <h2 className="text-2xl font-bold text-slate-900 mb-2">Access Denied</h2>
      <p className="text-slate-500 max-w-md">
        Your role ({user.role}) does not have permission to view this page. 
        Only Super Admin can grant access.
      </p>
      <Button variant="secondary" className="mt-6" onClick={() => setCurrentView('dashboard')}>
        Return to Dashboard
      </Button>
    </div>
  );

  return (
    <div className="h-screen bg-slate-50 flex overflow-hidden">
      <Sidebar 
        currentView={currentView === 'user-details' ? 'users' : currentView} 
        onChangeView={setCurrentView}
        userPermissions={currentUserPermissions}
        userRole={user.role}
      />

      <main className="flex-1 md:ml-64 transition-all h-full overflow-y-auto">
        <header className="sticky top-0 z-10 bg-white/80 backdrop-blur-md border-b border-slate-200 px-6 py-3 shadow-sm">
          <div className="flex items-center justify-between">
            <div className="hidden sm:flex items-center bg-slate-100/50 rounded-full px-4 py-2 w-64 border border-transparent focus-within:border-primary-300 focus-within:bg-white focus-within:ring-2 focus-within:ring-primary-100 transition-all">
              <Search className="w-4 h-4 text-slate-400 mr-2" />
              <input 
                type="text" 
                placeholder="Global Search..." 
                className="bg-transparent border-none outline-none text-sm w-full placeholder-slate-400 text-slate-700"
              />
            </div>

            <div className="flex sm:hidden font-bold text-slate-800">ET-TOOL-V2</div>

            <div className="flex items-center space-x-4">

              {/* Notification Bell with Dropdown */}
              <div className="relative" ref={notificationRef}>
                <button 
                  onClick={() => setIsNotificationsOpen(!isNotificationsOpen)} 
                  className={`relative p-2 rounded-full transition-colors ${isNotificationsOpen ? 'bg-primary-50 text-primary-600' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-100'}`}
                >
                  <Bell size={20} />
                  {unreadCount > 0 && (
                    <span className="absolute top-1.5 right-2 w-2 h-2 bg-red-500 rounded-full border-2 border-white animate-pulse"></span>
                  )}
                </button>

                {isNotificationsOpen && (
                  <div className="absolute right-0 mt-3 w-80 sm:w-96 bg-white rounded-xl shadow-2xl border border-slate-100 py-0 z-50 overflow-hidden ring-1 ring-black ring-opacity-5 animate-in fade-in slide-in-from-top-2 duration-200">
                     <div className="px-4 py-3 border-b border-slate-100 flex justify-between items-center bg-slate-50/50">
                        <h3 className="font-bold text-slate-800 flex items-center gap-2 text-sm">
                          <Bell size={16} className="text-primary-500" /> Notifications
                        </h3>
                        {unreadCount > 0 && (
                          <button 
                            onClick={handleMarkAllRead} 
                            className="text-xs font-medium text-primary-600 hover:text-primary-700 hover:underline"
                          >
                            Mark all read
                          </button>
                        )}
                     </div>

                     <div className="max-h-[350px] overflow-y-auto custom-scrollbar">
                        {myNotifications.length === 0 ? (
                           <div className="px-4 py-8 text-center flex flex-col items-center">
                              <div className="w-12 h-12 bg-slate-50 rounded-full flex items-center justify-center mb-3">
                                <Bell size={20} className="text-slate-300" />
                              </div>
                              <p className="text-slate-500 text-sm font-medium">No notifications yet</p>
                              <p className="text-slate-400 text-xs mt-1">We'll let you know when something arrives.</p>
                           </div>
                        ) : (
                           <div className="divide-y divide-slate-50">
                              {myNotifications.map(notif => (
                                 <div 
                                   key={notif.id} 
                                   onClick={() => handleNotificationClick(notif)} 
                                   className={`px-4 py-3 hover:bg-slate-50 transition-colors cursor-pointer group relative ${!notif.isRead ? 'bg-blue-50/40' : ''}`}
                                 >
                                    <div className="flex items-start gap-3">
                                       <div className={`mt-1 p-1.5 rounded-full flex-shrink-0 ${
                                          notif.type === 'alert' ? 'bg-red-100 text-red-600' :
                                          notif.type === 'success' ? 'bg-emerald-100 text-emerald-600' :
                                          notif.type === 'warning' ? 'bg-orange-100 text-orange-600' :
                                          'bg-blue-100 text-blue-600'
                                       }`}>
                                          {notif.type === 'alert' ? <AlertTriangle size={14} /> : 
                                           notif.type === 'success' ? <CheckCircle size={14} /> : 
                                           <Info size={14} />}
                                       </div>
                                       <div className="flex-1 min-w-0">
                                          <div className="flex justify-between items-start mb-0.5">
                                             <p className={`text-sm font-bold truncate pr-4 ${!notif.isRead ? 'text-slate-900' : 'text-slate-700'}`}>
                                                {notif.title}
                                             </p>
                                             <span className="text-[10px] text-slate-400 whitespace-nowrap">{notif.timestamp}</span>
                                          </div>
                                          <p className="text-xs text-slate-500 leading-relaxed line-clamp-2">{notif.message}</p>
                                       </div>
                                    </div>

                                    {/* Delete action on hover */}
                                    <button 
                                      onClick={(e) => handleRemoveNotification(e, notif.id)}
                                      className="absolute top-2 right-2 p-1 text-slate-300 hover:text-red-500 hover:bg-red-50 rounded opacity-0 group-hover:opacity-100 transition-all"
                                      title="Remove"
                                    >
                                      <X size={12} />
                                    </button>

                                    {!notif.isRead && (
                                       <div className="absolute left-0 top-0 bottom-0 w-1 bg-primary-500"></div>
                                    )}
                                 </div>
                              ))}
                           </div>
                        )}
                     </div>
                     <div className="bg-slate-50 p-2 text-center border-t border-slate-100">
                        <button onClick={() => { setCurrentView('dashboard'); setIsNotificationsOpen(false); }} className="text-xs text-slate-500 hover:text-primary-600 font-medium transition-colors">
                           View Dashboard
                        </button>
                     </div>
                  </div>
                )}
              </div>

              <div className="h-8 w-px bg-slate-200 mx-2"></div>

              <div className="relative group cursor-pointer flex items-center space-x-3">
                <div className="text-right hidden sm:block">
                  <p className="text-sm font-semibold text-slate-700">{user.username}</p>
                  <div className="flex items-center gap-1 justify-end">
                     <span className={`w-2 h-2 rounded-full ${user.role === 'super_admin' ? 'bg-purple-500' : 'bg-primary-500'}`}></span>
                     <p className="text-xs text-slate-500 capitalize">{user.role.replace('_', ' ')}</p>
                  </div>
                </div>
                <div className="w-10 h-10 rounded-full bg-slate-200 border-2 border-white shadow-sm overflow-hidden">
                   <img src={user.avatar || "https://picsum.photos/200"} alt="Avatar" className="w-full h-full object-cover" />
                </div>
                <ChevronDown size={16} className="text-slate-400" />

                <div className="absolute top-full right-0 mt-2 w-48 bg-white rounded-xl shadow-lg border border-slate-100 py-1 hidden group-hover:block animate-in fade-in slide-in-from-top-2 duration-200 z-50">
                  <div className="px-4 py-2 border-b border-slate-100 sm:hidden">
                     <p className="text-sm font-semibold text-slate-700">{user.username}</p>
                  </div>
                  <button 
                    onClick={() => setCurrentView('settings')}
                    className="w-full text-left px-4 py-2 text-sm text-slate-600 hover:bg-slate-50 hover:text-primary-600"
                  >
                    Profile
                  </button>
                  <button 
                    onClick={() => setCurrentView('settings')}
                    className="w-full text-left px-4 py-2 text-sm text-slate-600 hover:bg-slate-50 hover:text-primary-600"
                  >
                    Settings
                  </button>
                  <div className="border-t border-slate-100 my-1"></div>
                  <button 
                    onClick={onLogout}
                    className="w-full text-left px-4 py-2 text-sm text-red-600 hover:bg-red-50 flex items-center"
                  >
                    <LogOut size={14} className="mr-2" />
                    Sign out
                  </button>
                </div>
              </div>
            </div>
          </div>
        </header>

        <div className="p-6 lg:p-10">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default HomePage;

payload.text:
Building a complete backend for an enterprise application is a significant task. Since you are looking to host this on **Shared Hosting (Hostinger)** and your frontend is **React/TypeScript**, the best backend stack to use is **Node.js with Express** and **MySQL** (via Prisma ORM).

Shared hosting usually provides MySQL databases by default, making this the most compatible choice.

Here is the complete roadmap and the core code to build the backend.

### Prerequisite
You need to install these globally or in a new folder called `backend`:
```bash
mkdir backend
cd backend
npm init -y
npm install express cors dotenv jsonwebtoken bcryptjs @prisma/client
npm install --save-dev typescript ts-node @types/node @types/express @types/cors @types/jsonwebtoken @types/bcryptjs
npx tsc --init
```

### 1. Database Schema (Prisma)
Create a `prisma` folder and a `schema.prisma` file. This replaces your `types.ts` mock data with a real database structure.

**File:** `backend/prisma/schema.prisma`

```prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "mysql" // Works best on Hostinger Shared Hosting
  url      = env("DATABASE_URL")
}

model User {
  id               String   @id @default(uuid())
  employeeCode     String   @unique
  username         String   @unique
  passwordHash     String
  firstName        String
  lastName         String
  officialEmail    String   @unique
  role             String   // super_admin, manager, etc.
  department       String
  position         String
  status           String   @default("active") // active, inactive
  avatar           String?

  // Relations
  attendance       Attendance[]
  leaveRequests    LeaveRequest[]
  managedProjects  Project[]      @relation("ProjectManager")
  assignedTasks    Task[]         @relation("TaskAssignee") // Many-to-many implicit

  createdAt        DateTime @default(now())
  updatedAt        DateTime @updatedAt
}

model Attendance {
  id          String   @id @default(uuid())
  date        String   // YYYY-MM-DD
  status      String   // present, absent, late
  checkIn     String?
  checkOut    String?
  totalHours  Float?
  user        User     @relation(fields: [userId], references: [id])
  userId      String
}

model LeaveRequest {
  id          String   @id @default(uuid())
  startDate   String
  endDate     String
  type        String
  reason      String
  status      String   @default("pending") // pending, approved, rejected
  user        User     @relation(fields: [userId], references: [id])
  userId      String
}

model Project {
  id          String   @id @default(uuid())
  name        String
  description String?
  status      String   @default("active")
  progress    Int      @default(0)

  manager     User     @relation("ProjectManager", fields: [managerId], references: [id])
  managerId   String

  tasks       Task[]
}

model Task {
  id          String   @id @default(uuid())
  title       String
  description String?
  status      String   @default("todo") // todo, in-progress, done
  priority    String   @default("medium")
  dueDate     String?

  project     Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)
  projectId   String

  assignees   User[]   @relation("TaskAssignee")
}
```

Run `npx prisma generate` to create the client.

### 2. The Server Entry Point
Create the main server file.

**File:** `backend/src/index.ts`

```typescript
import express from 'express';
import cors from 'cors';
import dotenv from 'dotenv';
import authRoutes from './routes/authRoutes';
import userRoutes from './routes/userRoutes';
import attendanceRoutes from './routes/attendanceRoutes';
import projectRoutes from './routes/projectRoutes';

dotenv.config();

const app = express();
const PORT = process.env.PORT || 5000;

// Middleware
app.use(cors()); // Allow frontend to communicate
app.use(express.json());

// Routes
app.use('/api/auth', authRoutes);
app.use('/api/users', userRoutes);
app.use('/api/attendance', attendanceRoutes);
app.use('/api/projects', projectRoutes);

app.get('/', (req, res) => {
  res.send('ET-TOOL-V2 API is Running');
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

### 3. Authentication (JWT)
This handles Login and Registration.

**File:** `backend/src/routes/authRoutes.ts`

```typescript
import { Router } from 'express';
import { PrismaClient } from '@prisma/client';
import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';

const router = Router();
const prisma = new PrismaClient();
const JWT_SECRET = process.env.JWT_SECRET || 'super_secret_key';

// LOGIN
router.post('/login', async (req, res) => {
  const { username, password } = req.body;

  try {
    const user = await prisma.user.findUnique({ where: { username } });
    if (!user) return res.status(404).json({ message: 'User not found' });

    const isMatch = await bcrypt.compare(password, user.passwordHash);
    if (!isMatch) return res.status(400).json({ message: 'Invalid credentials' });

    // Create Token
    const token = jwt.sign(
      { id: user.id, role: user.role },
      JWT_SECRET,
      { expiresIn: '1d' }
    );

    // Return user info (excluding password)
    const { passwordHash, ...userInfo } = user;
    res.json({ token, user: userInfo });

  } catch (err) {
    res.status(500).json({ message: 'Server error' });
  }
});

// REGISTER (Ideally protected or seeded manually)
router.post('/register', async (req, res) => {
  const { username, password, firstName, lastName, email, role, employeeCode, department, position } = req.body;

  const salt = await bcrypt.genSalt(10);
  const hash = await bcrypt.hash(password, salt);

  try {
    const user = await prisma.user.create({
      data: {
        username,
        passwordHash: hash,
        firstName,
        lastName,
        officialEmail: email,
        role: role || 'employee',
        employeeCode,
        department,
        position
      }
    });
    res.json(user);
  } catch (err) {
    res.status(400).json({ message: 'User creation failed', error: err });
  }
});

export default router;
```

### 4. Middleware for Protection
Use this middleware to protect routes (like Attendance or Project Management) so only logged-in users can access them.

**File:** `backend/src/middleware/authMiddleware.ts`

```typescript
import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';

export const verifyToken = (req: Request, res: Response, next: NextFunction) => {
  const token = req.header('Authorization')?.split(' ')[1];
  if (!token) return res.status(401).json({ message: 'Access Denied' });

  try {
    const verified = jwt.verify(token, process.env.JWT_SECRET || 'super_secret_key');
    (req as any).user = verified;
    next();
  } catch (err) {
    res.status(400).json({ message: 'Invalid Token' });
  }
};
```

